window.COMMON_BANK = window.COMMON_BANK || {};
window.COMMON_BANK["law"] = window.COMMON_BANK["law"] || {name:"法律常识", items:[]};
window.COMMON_BANK["law"].items.push(
{"id": "law-180", "q": "下列哪一说法符合我国劳动合同法的规定？", "options": ["王某3 月1 日与用人单位签订劳动合同，3 月5 日正式上班，劳动关系自3 月1 日起建立", "李某在签订劳动合同时，用人单位为防止其反悔，可向其收取500 元押金做担保", "张某所在甲公司与另外一公司合并成立了乙公司，应由乙公司继续履行与之签订的劳动合同", "赵某在甲公司任职，同时在乙公司做兼职翻译，乙公司应当与其订立书面劳动合同"], "a": 2, "e": ".【C】本题考查法律常识。A项错误，根据《中华人民共和国劳动合同法》第十条规定：用人单位与劳动者在用工前订立劳动合同的，劳动关系自用工之日起建立。王某3月1日与用人单位签订劳动合同，3月5日正式上班，劳动关系应自3月5日起建立。B项错误，根据《中华人民共和国劳动合同法》第九条规定：用人单位招用劳动者，不得扣押劳动者的居民身份证和其他证件，不得要求劳动者提供担保或者以其他名义向劳动者收取财物。李某在签订劳动合同时，用人单位不得收取押金。C项正确，根据《中华人民共和国劳动合同法》第三十四条规定：用人单位发生合并或者分立等情况，原劳动合同继续有效，劳动合同由承继其权利和义务的用人单位继续履行。张某所在甲公司与另外一公司合并成立了乙公司，应由乙公司继续履行与张某签订的劳动合同。D项错误，根据《中华人民共和国劳动合同法》第六十九条规定：非全日制用工双方当事人可以订立口头协议。赵某在甲公司任职，同时在乙公司做兼职翻译，乙公司不一定要与赵某订立书面劳动合同，口头协议即可。故正确答案为C。", "tag": "法律常识"},
{"id": "law-181", "q": "小李于2013 年10 月2 日与某软件公司签订劳动合同一份，双方约定如下：合同期限为3 年，试用期9 个月，试用期工资为3000 元人民币(转正后4000)，小李于2013 年11 月2 日到公司上班，下列说法错误的是：", "options": ["小李与公司之间于2013 年11 月2 日正式建立劳动关系", "小李与公司试用期期限和工资的约定不合法", "在试用期小李可以随时解除与公司之间的劳动关系", "公司在合同期间无权单方面对小李的工作岗位作出调整"], "a": 2, "e": ".【C】《劳动合同法》第10条规定，用人单位与劳动者在用工前订立劳动合同的，劳动关系自用工之日起建立，A项正确。《劳动合同法》第19条规定，三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。《劳动合同法》第20条规定，劳动者在试用期的工资不得低于本单位相同岗位最低档工资或者劳动合同约定工资的百分之八十，并不得低于用人单位所在地的最低工资标准。因此本题中小李的试用期最长不能超过6个月，试用期工资不能低于3200元，B项正确。《劳动合同法》第37条规定，劳动者在试用期内提前三日通知用人单位，可以解除劳动合同。因此小李不能随时解除劳动合同，C项错误。《劳动合同法》第35条规定，用人单位与劳动者协商一致，可以变更劳动合同约定的内容。变更劳动合同，应当采用书面形式。工作岗位属于劳动合同的内容，用人单位要变更劳动者的工作岗位，必须与劳动者协商一致，并且变更劳动合同。用人单位无权单方面变更劳动者的工作岗位，D项正确。故正确答案为C。", "tag": "法律常识"},
{"id": "law-182", "q": "某公司与陈某在签订劳动合同时，在该合同约定“本人自愿放弃缴纳社保，公司每月给予200 元补贴作为补偿，与每月工资一同发放”，陈某工作一年后辞职。辞职后，他在当地申请劳动仲裁，要求该公司补缴社会保险金。关于以上案例，以下说法错误的是（）。", "options": ["案例中合同所约定的不缴纳社保的条款属于无效条款", "该公司应为陈某补缴社会保险", "陈某应当返还由该公司每月发放的200 元补贴", "为确保放弃缴纳社保声明合法生效，应另起协议"], "a": 3, "e": ".【D】本题考查法律常识。《劳动法》第七十条规定：“国家发展社会保险事业，建立社会保险制度，设立社会保险基金，使劳动者在年老、患病、工伤、失业、生育等情况下获得帮助和补偿。”《社会保险法》第四条第一款规定：“中华人民共和国境内的用人单位和个人依法缴纳社会保险费，有权查询缴费记录、个人权益记录，要求社会保险经办机构提供社会保险咨询等相关服务。”由此可知，用人单位负有依法缴纳社会保险费的法定义务，该法定义务不因当事人的约定而可予以免除。A项正确，公司与陈某在合同中约定放弃缴纳社会保险的条款违反了法律法规的强制性规定，属于无效条款。B、C项正确，公司有为陈某依法缴纳社会保险的法定义务，该公司应为陈某补缴社会保险，陈某应当返还由该公司每月发放的200元补贴。D项错误，用人单位与劳动者约定放弃缴纳社会保险的约定违反了法律的强制性规定，另起协议约定亦属于无效约定。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-183", "q": "下列关于试用期的说法错误的是：", "options": ["劳动者在试用期内依法享受社会保险待遇", "同一用人单位与同一劳动者只能约定一次试用期", "用人单位在试用期解除劳动合同的，应当向劳动者说明理由", "以完成一定工作任务为期限的劳动合同，约定的试用期不得超过一个月"], "a": 3, "e": ".【D】本题考查法律常识。A项正确，根据《劳动合同法》的规定，社会保险是劳动合同的必备条款，劳动关系一旦建立，用人单位就应当依法为劳动者缴纳社会保险，试用期并非独立于劳动关系外的“特殊期”，试用期包括在劳动合同期限内，因此劳动者在试用期内依法享受社会保险待遇。B项正确，D项错误，根据《劳动合同法》第十九条规定：“劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。同一用人单位与同一劳动者只能约定一次试用期。以完成一定工作任务为期限的劳动合同或者劳动合同期限不满三个月的，不得约定试用期。试用期包含在劳动合同期限内。劳动合同仅约定试用期的，试用期不成立，该期限为劳动合同期限。”因此，以完成一定工作任务为期限的劳动合同，不得约定试用期。C项正确，根据《劳动合同法》第二十一条规定：“在试用期中，除劳动者有本法第三十九条和第四十条第一项、第二项规定的情形外，用人单位不得解除劳动合同。用人单位在试用期解除劳动合同的，应当向劳动者说明理由。”本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-184", "q": "关于劳动合同，下列说法错误的是：", "options": ["劳动合同应当以书面形式订立", "劳动合同可以约定试用期，试用期最长不得超过1 年", "劳动者严重违反用人单位的规章制度的，用人单位可以解除劳动合同", "裁减人员时，与本单位订立无固定期限劳动合同的人员应当优先留用"], "a": 1, "e": ".【B】本题考查法律常识。A项正确，《劳动合同法》第十条第一款规定：“建立劳动关系，应当订立书面劳动合同。”B项错误，《劳动合同法》第十九条第一款规定：“劳动合同期限三个月以上不满一年的，试用期不得超过一个月；劳动合同期限一年以上不满三年的，试用期不得超过二个月；三年以上固定期限和无固定期限的劳动合同，试用期不得超过六个月。”故试用期最长不得超过6个月而非1年。C项正确，《劳动合同法》第三十九条规定：“劳动者有下列情形之一的，用人单位可以解除劳动合同：（一）在试用期间被证明不符合录用条件的；（二）严重违反用人单位的规章制度的；”D项正确，《劳动合同法》第四十一条第二款规定：“裁减人员时，应当优先留用下列人员：（一）与本单位订立较长期限的固定期限劳动合同的；（二）与本单位订立无固定期限劳动合同的；（三）家庭无其他就业人员，有需要扶养的老人或者未成年人的。”本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-185", "q": "下列有关工伤的说法正确的是：", "options": ["上下班途中遭受的交通事故伤害不可认定为工伤", "由于员工的重大过失造成的工伤，企业无需承担责任", "职工认为是工伤，但单位不认为是工伤的，由单位承担举证责任", "购买“五险”后，因工伤引起的所有费用可由工伤保险报销，公司不承担费用"], "a": 2, "e": ".【C】本题考查劳动法常识。A项错误，《工伤保险条例》第十四条规定：“职工有下列情形之一的，应当认定为工伤：（六）在上下班途中，受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的。”因此，在上下班途中，受到非本人主要责任的交通事故，应当认定为工伤。B项错误，《工伤保险条例》第十六条规定：“职工符合本条例第十四条、第十五条的规定，但是有下列情形之一的，不得认定为工伤或者视同工伤：（一）故意犯罪的；（二）醉酒或者吸毒的；（三）自残或者自杀的。”因此，由于员工的重大过失造成的伤害，并不是企业免责的事由。C项正确，《工伤保险条例》第十九条第二款规定：“职工或者其近亲属认为是工伤，用人单位不认为是工伤的，由用人单位承担举证责任。”D项错误，《工伤保险条例》第三十条第三、四款规定：“治疗工伤所需费用符合工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准的，从工伤保险基金支付。工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准，由国务院社会保险行政部门会同国务院卫生行政部门、食品药品监督管理部门等部门规定。职工住院治疗工伤的伙食补助费，以及经医疗机构出具证明，报经办机构同意，工伤职工到统筹地区以外就医所需的交通、食宿费用从工伤保险基金支付，基金支付的具体标准由统筹地区人民政府规定。”因此，并不是所有的费用都由工伤保险报销，公司也应当承担相应费用。故正确答案为C。", "tag": "法律常识"},
{"id": "law-186", "q": "下列行为不符合我国法律规定的是：", "options": ["小黄年满16 周岁，被某销售公司聘为正式职员", "因公司工作繁忙，小王每月加班时间达到24 小时", "劳务公司派遣到某单位工作的小李申请参加该单位工会", "老板要求小张法定节假日在公司加班，之后为其发放了双倍工资"], "a": 3, "e": ".【D】本题考查劳动法常识。A项正确，《劳动法》第十五条规定：“禁止用人单位招用未满十六周岁的未成年人。文艺、体育和特种工艺单位招用未满十六周岁的未成年人，必须遵守国家有关规定，并保障其接受义务教育的权利。”因此，销售公司聘年满16周岁小黄为职员符合法律规定。B项正确，《劳动法》第四十一条规定：“用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过一小时；因特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过三小时，但是每月不得超过三十六小时。”因此，小王每月加班时间达到24小时符合法律规定。C项正确，《劳动合同法》第六十四条规定：“被派遣劳动者有权在劳务派遣单位或者用工单位依法参加或者组织工会，维护自身的合法权益。”因此，小李可以申请参加用工单位的工会。D项错误，《劳动法》第四十四条规定：“有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬：（一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬；（二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬；（三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。”因此，老板要求小张法定节假日在公司加班，之后应为其发放不低于三倍工资的报酬。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-187", "q": "根据我国《劳动合同法》，下列说法错误的是：", "options": ["同一用人单位与同一劳动者只能约定一次试用期", "劳动合同部分无效，则整个劳动合同都将失去法律效力", "经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准支付", "用人单位需提前三十日以书面形式通知劳动者或额外支付一个月工资后才可以解除劳动合同"], "a": 1, "e": ".【B】本题考查法律常识。A项正确，根据我国《劳动合同法》第十九条第二款规定：“同一用人单位与同一劳动者只能约定一次试用期”；B项错误，根据我国《劳动合同法》第二十七条规定：“劳动合同部分无效，不影响其他部分效力的，其他部分仍然有效。”故选项中“则整个劳动合同都将失去法律效力”表述错误；C项正确，根据我国《劳动合同法》第四十七条第一款规定：“经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿”；D项正确，根据我国《劳动合同法》第四十条规定：“有下列情形之一的，用人单位提前三十日以书面形式通知劳动者本人或者额外支付劳动者一个月工资后，可以解除劳动合同：（一）劳动者患病或者非因工负伤，在规定的医疗期满后不能从事原工作，也不能从事由用人单位另行安排的工作的；（二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的；（三）劳动合同订立时所依据的客观情况发生重大变化，致使劳动合同无法履行，经用人单位与劳动者协商，未能就变更劳动合同内容达成协议的”。注：选项D表述不严谨，没有写明适用条件，但是本题为单选题，B项明显错误，故答案为B。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-188", "q": "下列哪种情形不能解除劳动关系？", "options": ["用人单位和劳动者协商一致", "试用期内提前一天通知用人单位", "合同期内，提前三十天以书面形式通知用人单位", "劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响"], "a": 1, "e": ".【B】本题主要考查法律常识。A项正确，根据我国《劳动合同法》第三十六条规定：“用人单位与劳动者协商一致，可以解除劳动合同。”因此选项表述正确。B项错误，根据我国《劳动合同法》第三十七条规定：“劳动者在试用期内提前三日通知用人单位，可以解除劳动合同。”因此选项提前一天通知表述错误。C项正确，根据我国《劳动合同法》第三十七条规定：“劳动者提前三十日以书面形式通知用人单位，可以解除劳动合同。”因此选项表述正确。D项正确，根据我国《劳动合同法》第三十九条规定：“劳动者有下列情形之一的，用人单位可以解除劳动合同：（四）劳动者同时与其他用人单位建立劳动关系，对完成本单位的工作任务造成严重影响，或者经用人单位提出，拒不改正的。”因此选项表述正确。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-189", "q": "下列选项中，符合法律规定的是：", "options": ["新录用的公务员小张，其试用期为六个月", "小陈今年15 岁，在某工地打工，干一些杂务", "因工作需要，公务员小朱前往甲单位授课，他可以在甲单位领取授课费", "某公司未按照劳动合同约定向员工小李支付劳动报酬，小李可以随时通知该公司解除劳动合同"], "a": 3, "e": ".【D】D项正确：根据《劳动法》第三十二条规定：“有下列情形之一的，劳动者可以随时通知用人单位解除劳动合同：……（三）用人单位未按照劳动合同约定支付劳动报酬或者提供劳动条件的。”A项错误，根据《公务员法》第三十四条规定：“新录用的公务员试用期为一年。试用期满合格的，予以任职；不合格的，取消录用。”B项错误：《劳动法》第十五条规定：“禁止用人单位招用未满十六周岁的未成年人。文艺、体育和特种工艺单位招用未满十六周岁的未成年人，必须依照国家有关规定，履行审批手续，并保障其接受义务教育的权利。”小陈在工地打工，用人单位不属于文艺、体育和特种工艺单位，因此不符合法律规定。C项错误，根据《公务员法》第四十四条规定：“公务员因工作需要在机关外兼职，应当经有关机关批准，并不得领取兼职报酬。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-190", "q": "2015 年五一国际劳动节是星期五，甲工厂因生产需要安排5 月1 日至3 日加班，那么该工厂下列向员工支付加班费的计算方式中，正确的是（）。", "options": ["1 号至3 号的加班费按工资的150%计算", "1 号至3 号的加班费按工资的200%计算", "1 号的加班费按工资的200%计算，2 号至3 号的加班费按工资的150%计算", "1 号的加班费按工资的300%计算，2 号至3 号的加班费按工资的200%计算"], "a": 3, "e": ".【D】根据《劳动法》第四十四条有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬：（一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬；（二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬；（三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。2015年5月1日是法定节假日，而5月2日与3日是公休日，5月1号的工资按照", "tag": "法律常识"},
{"id": "law-191", "q": "小陈2010 年7 月份大学毕业后就进入了某外资企业的上海办事处工作。2016 年3 月份，该外资企业因业务调整撤掉了上海办事处，并与小陈协商一致解除劳动合同。根据我国《劳动合同法》，该外资企业应向小陈支付( )作为经济补偿。", "options": ["6 个月工资", "5 个月工资", "5 个半月工资", "7 个月工资"], "a": 0, "e": ".【A】本题考查了《劳动合同法》的知识点。根据《劳动合同法》第四十七条规定：“经济补偿按劳动者在本单位工作的年限，每满一年支付一个月工资的标准向劳动者支付。六个月以上不满一年的，按一年计算；不满六个月的，向劳动者支付半个月工资的经济补偿。”题干中小陈从2010年7月入职到2016年3月解除劳动合同，共在该企业工作了5年零8个月，故该企业应当按照工作", "tag": "法律常识"},
{"id": "law-192", "q": "刘某的月工资为1800 元，每月工作约22 天，2008 年10 月1 至3 日，公司安排刘某在这3 天值班。根据劳动法的规定，公司应当向刘某支付大约多少加班费（）。", "options": ["360 元", "540 元", "740 元", "1000 元"], "a": 2, "e": ".【C】根据《劳动法》第四十四条规定：有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬：（三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。李某的日工资大约是82元，10月1到3日，每日加班费为246元，3天总计大约738元。故正确答案为C。注：题目中的22天，是因为劳动部《关于职工全年月平均工作时间和工资折算问题的通知》里规定，月计薪天数天。", "tag": "法律常识"},
{"id": "law-193", "q": "2018 年3 月11 日，十三届全国人大一次会议通过了《中华人民共和国宪法修正案》。下列与之相关的说法不准确的是：", "options": ["这是我国1982 年宪法公布施行以来对部分内容作的第五次修改", "确立了监察委员会作为国家的监察机关的宪法地位", "将全国人民代表大会法律委员会更名为全国人民代表大会宪法委员会", "将习近平新时代中国特色社会主义思想写入宪法"], "a": 2, "e": ".【C】本题考查法律常识。A项正确，我国于1988年、1993年、1999年、2004年和2018年对1982年现行《宪法》进行了五次修改，2018年3月", "tag": "法律常识"},
{"id": "law-194", "q": "根据我国宪法和有关法律，下列国家机关的哪一做法不符合规定？", "options": ["某市监察委员会决定对涉嫌行贿的某公司法定代表人实行留置", "某自治州人民代表大会常务委员会制定城市环境管理的地方性法规", "中国证券监督管理委员会依法制定有关上市公司的监管规章"], "a": 2, "e": ".【C】本题考查法律常识。A项正确，根据《监察法》第二十二条第一、二款规定：“被调查人涉嫌贪污贿赂、失职渎职等严重职务违法或者职务犯罪，监察机关已经掌握其部分违法犯罪事实及证据，仍有重要问题需要进一步调查，并有下列情形之一的，经监察机关依法审批，可以将其留置在特定场所：（一）涉及案情重大、复杂的；（二）可能逃跑、自杀的；（三）可能串供或者伪造、隐匿、毁灭证据的；（四）可能有其他妨碍调查行为的。对涉嫌行贿犯罪或者共同职务犯罪的涉案人员，监察机关可以依照前款规定采取留置措施。”因此，某市监察委员会决定对涉嫌行贿的某公司法定代表人实行留置符合法律规定。B项正确，根据《立法法》第七十二条第五款规定：“自治州的人民代表大会及其常务委员会可以依照本条第二款规定行使设区的市制定地方性法规的职权。”《立法法》第七十二条第二款规定：“设区的市的人民代表大会及其常务委员会根据本市的具体情况和实际需要，在不同宪法、法律、行政法规和本省、自治区的地方性法规相抵触的前提下，可以对城乡建设与管理、环境保护、历史文化保护等方面的事项制定地方性法规，法律对设区的市制定地方性法规的事项另有规定的，从其规定。”因此，某自治州人大常委会有权制定城市环境管理方面的地方性法规。C项错误，根据《宪法》第四十条规定：“中华人民共和国公民的通信自由和通信秘密受法律的保护。除因国家安全或者追查刑事犯罪的需要，由公安机关或者检察机关依照法律规定的程序对通信进行检查外，任何组织或者个人不得以任D项正确，《证券法》第一百七十九条规定：“国务院证券监督管理机构在对证券市场实施监督管理中履行下列职责：（一）依法制定有关证券市场监督管理的规章、规则，并依法行使审批或者核准权”中国证券监督管理委员会（证监会）是国务院证券监督管理机构，有权依法制定有关上市公司的监管规章。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-195", "q": "根据我国《宪法》，下列表述错误的是：", "options": ["为追查刑事犯罪，公安机关、检察机关、审判机关可依法对公民的通信进行检查", "我国在普通地方、民族自治地方和特别行政区建立了相应的地方制度", "一切组织和个人都负有实施宪法和保证宪法实施的职责"], "a": 1, "e": ".【B】B项符合题意：我国《宪法》第四十条规定：“中华人民共和国公民的通信自由和通信秘密受法律的保护。除因国家安全或者追查刑事犯罪的需要，由公安机关或者检察机关依照法律规定的程序对通信进行检查外，任何组织或者个人不得以任何理由侵犯公民的通信自由和通信秘密。”由此可知，审判机关无权对公民的通信进行检查，当选。A、C、D项说法均符合我国现行《宪法》的规定，排除。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-196", "q": "下列说法不符合我国宪法规定的是：", "options": ["国家监察机关和审判机关均由人民代表大会产生", "国家工作人员就职时应当依照法律规定公开进行宪法宣誓", "上级人民法院、人民检察院领导下级人民法院、人民检察院的工作", "监察委员会依照法律规定独立行使监察权，不受行政机关、社会团体和个人的干涉"], "a": 2, "e": ".【C】本题考查法律常识。A项正确，根据《宪法》第三条第三款规定：“国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。”B项正确，根据《宪法》第二十七条第三款规定：“国家工作人员就职时应当依照法律规定公开进行宪法宣誓。”C项错误，根据《宪法》第一百三十二条规定：“最高人民法院是最高审判机关。最高人民法院监督地方各级人民法院和专门人民法院的审判工作，上级人民法院监督下级人民法院的审判工作。”第一百三十七条规定：“最高人民检察院是最高检察机关。最高人民检察院领导地方各级人民检察院和专门人民检察院的工作，上级人民检察院领导下级人民检察院的工作。”上下级法院之间是监督关系，上下级检察院之间是领导关系。D项正确，根据《宪法》第一百二十七条规定：“监察委员会依照法律规定独立行使监察权，不受行政机关、社会团体和个人的干涉。监察机关办理职务违法和职务犯罪案件，应当与审判机关、检察机关、执法部门互相配合，互相制约。”本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-197", "q": "2018 年修订的《中华人民共和国宪法》，增加了国家监察机关的内容，关于国家监察机关，下列说法错误的是：", "options": ["国家监察委员会主任由全国人民代表大会选举和罢免", "全国人民代表大会及其常务委员会监督国家监察委员会的工作", "全国人大常委会根据委员长的提请，任免国家监察委员会副主任、委员", "县级以上地方各级人民代表大会常务委员会的组成人员不得担任国家监察机关的职务"], "a": 2, "e": ".【C】本题考查法律常识。A项正确，根据《宪法》第六十二条规定：“全国人民代表大会行使下列职权：（七）选举国家监察委员会主任”根据《宪法》第六十三条规定：“全国人民代表大会有权罢免下列人员：（四）国家监察委员会主任”所以国家监察委员会主任由全国人民代表大会选举和罢免。B项正确，根据《宪法》第一百二十六条规定：“国家监察委员会对全国人民代表大会和全国人民代表大会常务委员会负责。地方各级监察委员会对产生它的国家权力机关和上一级监察委员会负责。”所以，全国人民代表大会及其常务委员会监督国家监察委员会的工作。C项错误，根据《宪法》第六十七条规定：“全国人民代表大会常务委员会行使下列职权：（十一）根据国家监察委员会主任的提请，任免国家监察委员会副主任、委员”所以，全国人大常委会根据委员长的提请，任免国家监察委员会副主任、委员的说法错误。D项正确，根据《宪法》第一百零三条规定：“县级以上的地方各级人民代表大会常务委员会的组成人员不得担任国家行政机关、监察机关、审判机关和检察机关的职务。”本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-198", "q": "根据宪法和法律规定，我国各级人民政府是各级国家的执行机关。", "options": ["权力机关", "共产党组织", "司法机关", "社会团体"], "a": 0, "e": ".【A】本题考查法律常识。根据《宪法》第一百零五条规定：“地方各级人民政府是地方各级国家权力机关的执行机关，是地方各级国家行政机关。地方各级人民政府实行省长、市长、县长、区长、乡长、镇长负责制。”故正确答案为A。", "tag": "法律常识"},
{"id": "law-199", "q": "我国《宪法》规定，国家建立健全同（）发展水平相适应的社会保障水平。", "options": ["政治", "经济", "政治和经济", "政治、经济和社会"], "a": 1, "e": ".【B】本题考查法律常识。根据《宪法》第十四条第四款规定：“国家建立健全同经济发展水平相适应的社会保障制度。”故正确答案为B。", "tag": "法律常识"},
{"id": "law-200", "q": "全国人大常委会从属于全国人大，在全国人大闭会期间行使全国人大的部分职权，包括立法权、任免权、决定权、监督权等。下列选项中，全国人大常委会有权任免的是。", "options": ["国务委员", "国务院总理", "国务院各部部长", "最高人民检察院检察长"], "a": 2, "e": ".【C】本题考查法律常识。根据《宪法》第六十七条规定：“全国人民代表大会常务委员会行使下列职权：（九）在全国人民代表大会闭会期间，根据国务院总理的提名，决定部长、委员会主任、审计长、秘书长的人选；（十）在全国人民代表大会闭会期间，根据中央军事委员会主席的提名，决定中央军事委员会其他组成人员的人选；（十一）根据国家监察委员会主任的提请，任免国家监察委员会副主任、委员；（十二）根据最高人民法院院长的提请，任免最高人民法院副院长、审判员、审判委员会委员和军事法院院长；（十三）根据最高人民检察院检察长的提请，任免最高人民检察院副检察长、检察员、检察委员会委员和军事检察院检察长，并且批准省、自治区、直辖市的人民检察院检察长的任免。”因此，全国人大常委会有权在全国人大闭会期间任免国务院各部部长。根据《宪法》第六十二条规定：“全国人民代表大会行使下列职权：（四）选举中华人民共和国主席、副主席；（五）根据中华人民共和国主席的提名，决定国务院总理的人选；根据国务院总理的提名，决定国务院副总理、国务委员、各部部长、各委员会主任、审计长、秘书长的人选；（六）选举中央军事委员会主席；根据中央军事委员会主席的提名，决定中央军事委员会其他组成人员的人选；（七）选举国家监察委员会主任；（八）选举最高人民法院院长；（九）选举最高人民检察院检察长。”国务委员、国务院总理、最高人民检察院检察长均由全国人大产生。故正确答案为C。", "tag": "法律常识"},
{"id": "law-201", "q": "下列关于我国地方性法规的表述，正确的是：", "options": ["地方性法规特定情况下可由省、自治区和直辖市人民政府制定", "部分地方性法规可由设区的市的人民代表大会及其常务委员会制定", "地方性法规只能由省、自治区和直辖市人民代表大会常务委员会制定", "地方性法规必要时报全国人民代表大会常务委员会和国务院备案"], "a": 1, "e": ".【B】本题考查法律常识。B项正确，AC项错误。根据《宪法》第一百条的规定：“省、直辖市的人民代表大会和它们的常务委员会，在不同宪法、法律、行政法规相抵触的前提下，可以制定地方性法规，报全国人民代表大会常务委员会备案。设区的市的人民代表大会和它们的常务委员会，在不同宪法、法律、行政法规和本省、自治区的地方性法规相抵触的前提下，可以依照法律规定制定地方性法规，报本省、自治区人民代表大会常务委员会批准后施行。”可知，地方性法规的制定主体为省级以及设区市的人大及常委会，故B选项正确，AC选项错误。D选项错误，根据《立法法》第九十八条第二款的规定：“行政法规、地方性法规、自治条例和单行条例、规章应当在公布后的三十日内依照下列规定报有关机关备案：（二）省、自治区、直辖市的人民代表大会及其常务委员会制定的地方性法规，报全国人民代表大会常务委员会和国务院备案；设区的市、自治州的人民代表大会及其常务委员会制定的地方性法规，由省、自治区的人民代表大会常务委员会报全国人民代表大会常务委员会和国务院备案；”可知地方性法规不是必要时才报备案，而是必须报备案。故正确答案为B。", "tag": "法律常识"},
{"id": "law-202", "q": "关于立法，下列说法错误的是：", "options": ["只有最高国家权力机关才有权制定和修改刑事、民事基本法律", "自治区的自治条例，报全国人民代表大会常务委员会批准后生效", "地方人民代表大会在不同宪法、法律、行政法规相抵触的前提下，可以制定地方性法规", "应当制定地方性法规但条件尚不成熟的，因行政管理迫切需要，地方可以先制定地方政府规章"], "a": 2, "e": ".【C】本题考查宪法常识。A项正确，《宪法》第五十七条规定：“中华人民共和国全国人民代表大会是最高国家权力机关。它的常设机关是全国人民代表大会常务委员会。”《立法法》第七条规定：“全国人民代表大会和全国人民代表大会常务委员会行使国家立法权。全国人民代表大会制定和修改刑事、民事、国家机构的和其他的基本法律。全国人民代表大会常务委员会制定和修改除应当由全国人民代表大会制定的法律以外的其他法律；在全国人民代表大会闭会期间，对全国人民代表大会制定的法律进行部分补充和修改，但是不得同该法律的基本原则相抵触。”B项正确，《宪法》第一百一十六条规定：“民族自治地方的人民代表大会有权依照当地民族的政治、经济和文化的特点，制定自治条例和单行条例。自治区的自治条例和单行条例，报全国人民代表大会常务委员会批准后生效。自治州、自治县的自治条例和单行条例，报省或者自治区的人民代表大会常务委员会批准后生效，并报全国人民代表大会常务委员会备案。”C项错误，《立法法》第七十二条规定：“省、自治区、直辖市的人民代表大会及其常务委员会根据本行政区域的具体情况和实际需要，在不同宪法、法律、行政法规相抵触的前提下，可以制定地方性法规。设区的市的人民代表大会及其常务委员会根据本市的具体情况和实际需要，在不同宪法、法律、行政法规和本省、自治区的地方性法规相抵触的前提下，可以对城乡建设与管理、环境保护、历史文化保护等方面的事项制定地方性法规。”因此，并非只要是地方人大就可以制定地方性法规。D项正确，《立法法》第八十二条第五款规定：“应当制定地方性法规但条件尚不成熟的，因行政管理迫切需要，可以先制定地方政府规章。规章实施满两年需要继续实施规章所规定的行政措施的，应当提请本级人民代表大会或者其常务委员会制定地方性法规。”本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-203", "q": "关于中华人民共和国国歌，下列说法错误的是：", "options": ["政府机关举行重大庆典、纪念仪式时，应当奏唱国歌", "在公共场合，以歪曲、贬损方式奏唱国歌是犯罪行为", "外交活动中奏唱国歌的场合和礼仪，由外交部规定", "不得将国歌作为公共场所的背景音乐"], "a": 1, "e": ".【B】本题考查宪法常识。A项正确，《国歌法》第四条规定：“在下列场合,应当奏唱国歌：（五）各级机关举行或者组织的重大庆典、表彰、纪念仪式等。”B项错误，《国歌法》第十五条规定：“在公共场合,故意篡改国歌歌词、曲谱,以歪曲、贬损方式奏唱国歌，或者以其他方式侮辱国歌的，由公安机关处以警告或者十五日以下拘留；构成犯罪的，依法追究刑事责任。”因此，“在公共场合，以歪曲、贬损方式奏唱国歌”的行为，不一定属于犯罪行为，也可能是一般违法行为。C项正确，《国歌法》第九条第一款规定：“外交活动中奏唱国歌的场合和礼仪，由外交部规定。”D项正确，《国歌法》第八条规定：“国歌不得用于或者变相用于商标、商业广告，不得在私人丧事活动等不适宜的场合使用，不得作为公共场所的背景音乐等。”本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-204", "q": "2019 年3 月12 日，十三届全国人大二次会议举行第三次全体会议，听取审议最高人民法院工作报告和最高人民检察院工作报告。这体现了人民代表大会的（）。", "options": ["立法权", "决定权", "任免权", "监督权"], "a": 3, "e": ".【D】本题考查法律常识。全国人大有权监督由它产生的其他国家机关的工作，这些国家机关主要包括全国人大常委会、国务院、国家监察委员会、最高人民法院、最高人民检察院等，它们都要向全国人大负责，并报告工作。具体来说，全国人大听取并通过全国人大常委会的工作报告；听取最高人民法院、最高人民检察院的工作报告；改变或者撤销全国人民代表大会常务委员会不适当的决定等。故正确答案为D。", "tag": "法律常识"},
{"id": "law-205", "q": "下列情形中，公民基本权利未受侵犯的是", "options": ["小学生王某学习成绩很差，其父直接让他辍学去工厂上班", "某保安公司招聘夜班保安，在招聘启事中注明“男性优先”", "某公司的封闭车间夏季未装空调，小芳在车间工作时汗如雨下发生晕厥", "张先生和李女士结婚时约定，李女士有义务为张先生生育两个孩子"], "a": 1, "e": ".【B】本题考查法律常识。A项错误，《宪法》第四十六条第一款规定：“中华人民共和国公民有受教育的权利和义务。”王某的父亲让王某辍学的行为侵犯了王某的受教育权。B项正确，《宪法》第四十八条规定：“中华人民共和国妇女在政治的、经济的、文化的、社会的和家庭的生活等各方面享有同男子平等的权利。国家保护妇女的权利和利益，实行男女同工同酬，培养和选拔妇女干部。”该保安公司在招工时虽然限定了“男性优先”，但不是“只限男性”，没有侵犯妇女平等工作的权利。C项错误，《劳动法》第三条第一款规定：“劳动者享有平等就业和选择职业的权利、取得劳动报酬的权利、休息休假的权利、获得劳动安全卫生保护的权利、接受职业技能培训的权利、享受社会保险和福利的权利、提请劳动争议处理的权利以及法律规定的其他劳动权利。”劳动者向公司要求工作环境符合劳动环境，是劳动者的基本权利。公司在封闭车间不安装空调导致劳动者晕厥侵犯了劳动者的基本权利。D项错误，《宪法》第四十九条第二款规定：“夫妻双方有实行计划生育的义务”，夫妻双方有计划生育的义务，但是应该尊重和保障女性的生育自由权，夫妻双方约定妻子生育两个孩子的义务侵犯了妻子的生育自由权。故正确答案为B。", "tag": "法律常识"},
{"id": "law-206", "q": "下列有权制定地方政府规章的是（）", "options": ["库尔勒市人大常委会", "乌鲁木齐市人民政府", "新疆维吾尔自治区人大常委会", "新疆维吾尔自治区财政厅"], "a": 1, "e": ".【B】根据《立法法》第八十二条规定：“省、自治区、直辖市和设区的市、自治州的人民政府，可以根据法律、行政法规和本省、自治区、直辖市的地方性法规，制定规章。”AC项错误，库尔勒市人大常委会和新疆维吾尔自治区人大常委会属于人大的常设机构，无权制定地方政府规章。B项正确，乌鲁木齐市人民政府属于设区的市人民政府，有权制定地方政府规章。D项错误，新疆维吾尔自治区财政厅属于政府工作部门，无权制定地方政府规章。故正确答案为B。", "tag": "法律常识"},
{"id": "law-207", "q": "下列不属于民族自治地方的是：（）", "options": ["新疆维吾尔自治区", "伊犁哈萨克族自治州", "焉耆回族自治县", "独山子哈萨克族自治乡"], "a": 3, "e": ".【D】本题考查法律常识。《中华人民共和国宪法》第三十条第三款规定：“自治区、自治州、自治县都是民族自治地方。”所以只有自治区、自治州、自治县才是民族自治地方，民族乡则不是民族自治地方。A、B、C选项均为民族自治地方，D选项为自治乡不属于民族自治地方。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-208", "q": "下列有关我国宪法修正案的说法，错误的是：", "options": ["修宪权专属于全国人民代表大会", "只有全国人大常委会或五分之一以上全国人大代表联名，才能提出修宪的议案", "到目前为止，我国对现行宪法进行了五次修正", "宪法修正案通过后由国家主席公布"], "a": 3, "e": ".【D】本题主要考查法律常识。A项正确，《宪法》第六十二条规定：“全国人民代表大会行使下列职权：（一）修改宪法。”因此，全国人民代表大会是唯一有权修改宪法的机关。B项正确，《宪法》第六十四条第一款规定：“宪法的修改，由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过。”C项正确，我国现行宪法为1982年宪法，共历经了1988年、1993年、1999年、2004年和2018年五次修订。D项错误，在我国，宪法并未明确规定宪法修正案的公布机关。但是，数次修宪过程中已经形成了公布修正案的宪法惯例，即由全国人大主席团公布宪法修正案，而不是由国家主席公布。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-209", "q": "小明在图书馆大声说话，有读者制止他时，他却说：“这是我的权利和自由，别人无权干涉”。关于上述观点的评价正确的是：①正确，宪法规定公民有言论自由②错误，公民的自由是在法律范围内的自由③错误，未经他人许可，公民不得擅自行使权利④错误，世界上从来没有“绝对”的权利和自由", "options": ["①②", "①③", "②③", "②④"], "a": 3, "e": ".【D】本题考查宪法的相关知识，主要考查权利和自由。①错误，我国《宪法》第三十五条规定：“中华人民共和国公民有言论、出版、集会、结社、游行、示威的自由。”有言论自由并不等于不分场所的随意行使自己的权利，图书馆属于公共场所，禁止大声喧哗。选项表述正确，但不符合题意。②正确，我国公民言论、出版、集会、结社、游行、示威的自由，都必须在国家法律、法规规定的范围内行使，自由是相对的，而不是绝对的，自由和法律是统一的，法律是自由的体现和保证，自由要受法律的制约。③错误，公民有行使自己权利的自由，不需要经过任何人同意，但是，前提是行使自己的权利不得触犯法律，不得损害他人利益。图书馆内禁止大声喧哗，小明在行使自己权利时损害了他人的利益。④正确，没有绝对的权利和自由，任何权利和自由都是有条件的，都是受到一定限制的。任何权利和自由都是在法律许可的范围内行使，否则就会受到法律的制裁。行使权利和自由不得损害他人的合法权益。小明在图书馆大声喧哗，损害了他人的利益。因此，世界上不存在“绝对”的权利和自由。①③错误，②④正确。故正确答案为D。", "tag": "法律常识"},
{"id": "law-210", "q": "下列和宪法有关的表述正确的是：", "options": ["在我国，矿藏、水流和森林属于国家所有", "世界上第一部资产阶级国家的成文宪法是1791 年通过的法国宪法", "人民代表大会制度是中华人民共和国的根本制度", "中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责"], "a": 3, "e": ".【D】本题主要考查宪法有关知识。A项错误，根据我国《宪法》第九条规定：“矿藏、水流、森林、山岭、草原、荒地、滩涂等自然资源，都属于国家所有，即全民所有；由法律规定属于集体所有的森林和山岭、草原、荒地、滩涂除外。”因此，矿藏、水流属于国家所有，森林可以属于集体所有。B项错误，《1787年宪法》是美国1787年制定并于1789年批准生效的美利坚合众国联邦宪法，是世界上第一部比较完整的资产阶级成文宪法。而1791年通过的宪法是法国历史上第一部成文宪法，诞生时间晚于美国宪法。C项错误，根据我国《宪法》第一条规定：“社会主义制度是中华人民共和国的根本制度。中国共产党领导是中国特色社会主义最本质的特征。禁止任何组织或者个人破坏社会主义制度。”人民代表大会制度是我国的根本政治制度，因此选项表述错误。D项正确，根据我国《宪法》第九十四条规定：“中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责。”因此选项表述正确。故正确答案为D。", "tag": "法律常识"},
{"id": "law-211", "q": "下列属于我国基层民主自治工作的一组是：①某村村民直接参与投票选举村委会干部②某社区居委会定期向居民会议汇报工作③某区妇女联合会实行事务公开的制度④某厂职工代表大会依法选举职工代表", "options": ["①②", "②③", "③④", "①④"], "a": 0, "e": ".【A】民直接选举产生。任何组织或者个人不得指定、委派或者撤换村民委员会成员。作。故正确答案为A。", "tag": "法律常识"},
{"id": "law-212", "q": "2018 年3 月11 日第十三届全国人民代表大会第一次会议通过《中华人民共和国宪法修正案》，确立了（）是中国特色社会主义最本质的特征。", "options": ["人民当家作主", "中国共产党领导", "解放和发展社会生产力", "我国仍处于并将长期处于社会主义初级阶段"], "a": 1, "e": ".【B】本题主要考查法律常识。", "tag": "法律常识"},
{"id": "law-213", "q": "全国人大常委会《关于实行宪法宣誓制度的决定》的通过，标志着我国公职人员就职宣誓开始走上制度化发展的道路。下列关于宪法宣誓的说法正确的是", "options": ["宪法宣誓是向宣誓者施加责任的法律机制", "宪法宣誓是宣誓者向在场聆听的人员宣誓", "宪法宣誓能实现内在素质向外在规范转变", "宪法宣誓是示范敬畏宪法权威的社会仪式"], "a": 2, "e": ".【C】本题考查宪法宣誓制度相关知识。A项错误，向宪法宣誓代表了宣誓人内心的认同和良心上的约束，是对宣誓者内心的一种约束，而不是向宣誓者被动地施加责任的法律机制。B项错误，宪法宣誓既包含“向宪法宣誓”，也包含“通过宪法来宣誓”,宪法宣誓不再只是向在场的聆听者宣誓，而是向在场、不在场的“人民”宣誓，向自己的内心信仰宣誓，提醒国家工作人员清楚权力的来源、权力的依据和行使权力的准则。C项正确，宪法的权威源自人民的内心拥护和真诚信仰。通过国家工作人员在就职时进行宪法宣誓这种仪式化的程序强化国家工作人员对人民和人民赋予的权力、对宪法和法律的敬畏之心。面对宪法宣誓，意味着宣誓主体的每项职务行为都要受到宪法约束。D项错误，国家公职人员对宪法宣誓本身就是实施宪法的内容之一，更是对宪法忠诚、遵守、信仰、敬畏的法定仪式，并非社会仪式。故正确答案为C。", "tag": "法律常识"},
{"id": "law-214", "q": "关于我国宪法宣誓制度，下列说法错误的是（）。", "options": ["宣誓仪式应当采取集体宣誓的形式", "宣誓仪式应当奏唱中华人民共和国国歌", "人民法院、人民检察院任命的国家工作人员，在就职时应当公开进行宪法宣誓", "全国人民代表大会选举产生的人员，在依照法定程序产生后，进行宪法宣誓"], "a": 0, "e": ".【A】本题主要考查宪法宣誓制度相关内容。A项错误，《全国人民代表大会常务委员会关于实行宪法宣誓制度的决定》第八条规定：“宣誓仪式根据情况，可以采取单独宣誓或者集体宣誓的形式。”B项正确，《全国人民代表大会常务委员会关于实行宪法宣誓制度的决定》第八条规定：“宣誓场所应当庄重、严肃，悬挂中华人民共和国国旗或者国徽。宣誓仪式应当奏唱中华人民共和国国歌。”C项正确，《全国人民代表大会常务委员会关于实行宪法宣誓制度的决定》第一条规定：“各级人民代表大会及县级以上各级人民代表大会常务委员会选举或者决定任命的国家工作人员，以及各级人民政府、监察委员会、人民法院、人民检察院任命的国家工作人员，在就职时应当公开进行宪法宣誓。”D项正确，《全国人民代表大会常务委员会关于实行宪法宣誓制度的决定》第三条规定：“全国人民代表大会选举或者决定任命的中华人民共和国主席、副主席，全国人民代表大会常务委员会委员长、副委员长、秘书长、委员，国务院总理、副总理、国务委员、各部部长、各委员会主任、中国人民银行行长、审计长、秘书长，中华人民共和国中央军事委员会主席、副主席、委员，国家监察委员会主任，最高人民法院院长，最高人民检察院检察长，以及全国人民代表大会专门委员会主任委员、副主任委员、委员等，在依照法定程序产生后，进行宪法宣誓。宣誓仪式由全国人民代表大会会议主席团组织。”本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-215", "q": "关于我国的国家制度，下列说法错误的是：", "options": ["我国是人民民主专政的社会主义国家", "我国人民行使国家权力的机关是各级人民政府", "我国的国家机构实行民主集中制原则"], "a": 1, "e": ".【B】本题考查法律常识。A项正确，我国《宪法》第一条规定：“中华人民共和国是工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家。”B项错误，根据我国《宪法》第二条规定，中华人民共和国的一切权力属于人民。人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。C项正确，我国《宪法》第三条规定：“中华人民共和国的国家机构实行民主集中制的原则。”D项正确，根据我国《宪法》第六条规定，中华人民共和国的社会主义经济制度的基础是生产资料的社会主义公有制，本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-216", "q": "在行政诉讼中，人民法院认为规章之间不一致的，应报请（）作出解释或者裁决。", "options": ["全国人民代表大会及其常务委员会", "国务院", "最高人民法院", "司法部"], "a": 1, "e": ".【B】本题考查立法法相关内容。《立法法》第九十五条第三项规定：“部门规章之间、部门规章与地方政府规章之间对同一事项的规定不一致时，由国务院裁决。”所以当规章之间不一致的，由国务院裁决。故正确答案为B。", "tag": "法律常识"},
{"id": "law-217", "q": "下列与我国宪法有关的表述错误的是：", "options": ["每年12 月4 日是我国的国家宪法日", "人民主权是宪法规定的一项基本原则", "中央军委的职权在宪法中有明确具体的规定", "未成年人、依法被剥夺政治权利的人和外国人无选举权和被选举权"], "a": 2, "e": ".【C】本题考查法律常识。A项正确，2014年11月1日，十二届全国人大常委会第十一次会议审议通过关于设立国家宪法日的决定，明确将12月", "tag": "法律常识"},
{"id": "law-218", "q": "在我国，国家权力机关指的是：", "options": ["人民检察院", "人民政府", "人民法院", "人民代表大会"], "a": 3, "e": ".【D】本题主要考查宪法中的国家机关的主要内容。A项错误，根据《中华人民共和国宪法》第一百三十四条规定：“中华人民共和国人民检察院是国家的法律监督机关。”B项错误，根据《中华人民共和国宪法》第八十五条规定：“中华人民共和国国务院，即中央人民政府，是最高国家权力机关的执行机关，是最高国家行政机关。所以人民政府是行政机关。”C项错误，根据《中华人民共和国宪法》第一百二十三条规定：“中华人民共和国人民法院是国家的审判机关。”D项正确，根据《中华人民共和国宪法》第五十七条规定：“中华人民共和国全国人民代表大会是最高国家权力机关。它的常设机关是全国人民代表大会常务委员会。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-219", "q": "某选区共有选民1889 人，张某是候选人之一。在下列情况下，张某可以当选为该选区人大代表的是：", "options": ["参加投票的有889 人，张某获选票880 张", "参加投票的有1770 人，张某获选票1781 张", "参加投票的有1881 人，张某获选票697 张", "参加投票的有1001 人，张某获选票792 张"], "a": 3, "e": ".【D】D项正确：《选举法》第四十四条：在选民直接选举人民代表大会代表时，选区全体选民的过半数参加投票，选举有效。代表候选人获得参加投票的选民过半数的选票时，始得当选。县级以上的地方各级人民代表大会在选举上一级人民代表大会代表时，代表候选人获得全体代表过半数的选票时，始得当选。选项中参加投票人数1001人超过全体选民1889人的一半，张某获选票792张超过参加投票选民1001人的一半，可以当选。A项、C项错误：《选举法》第四十四条：在选民直接选举人民代表大会代表时，选区全体选民的过半数参加投票，选举有效。代表候选人获得参加投票的选民过半数的选票时，始得当选。县级以上的地方各级人民代表大会在选举上一级人民代表大会代表时，代表候选人获得全体代表过半数的选票时，始得当选。A项中参加投票的889人不到选民1889人一半，无法当选。C项中张某获选票697张，未获得半数选票，无法当选。B项错误：《选举法》第四十三条：每次选举所投的票数，多于投票人数的无效，等于或者少于投票人数的有效。每一选票所选的人数，多于规定应选代表人数的作废，等于或者少于规定应选代表人数的有效。选项中张某获选票数为1781张，多于参加投票的人数1770人，无法当选。故正确答案为D。", "tag": "法律常识"},
{"id": "law-220", "q": "关于我国的国家制度，下列说法错误的是：", "options": ["我国是人民民主专政的社会主义国家", "我国人民行使国家权力的机关是各级人民政府", "我国的国家机构实行民主集中制原则"], "a": 1, "e": ".【B】B项错误：《宪法》第二条：中华人民共和国的一切权力属于人民。人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。A项正确：《宪法》第一条：中华人民共和国是工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家。C项正确：《宪法》第三条：中华人民共和国的国家机构实行民主集中制的原则。D项正确：《宪法》第六条：中华人民共和国的社会主义经济制度的基础是生产资料的社会主义公有制，即全民所有制本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-221", "q": "某社区举行了居民政治参与的交流活动：甲作为选民参加了一次直接选举人大代表的活动；乙找过区人大代表反映菜市场环境问题；丙对居委会工作提出过批评建议；丁参加了市政府改造“人民公园”听证会。据此我们可以判断：", "options": ["甲选举的是省人大代表", "乙积极参与基层民主管理", "丙直接行使了民主权利", "丁参与对政府的民主监督"], "a": 2, "e": ".【C】A项错误：省市级以上人大代表的选举采用间接方式，只有区县级和乡镇级人大代表选举，才由选民直接选举。甲作为选民直接选举，可知他选举的不是省人大代表；B项错误：乙找过区人大代表反映菜市场环境问题，行使的是监督权而非管理权；C项正确：丙对居委会工作提出批评建议，属于民主管理的范畴，这是公民直接行使民主权利的体现；D项错误：丁参加听证会是属于参与民主决策。故正确答案为C。", "tag": "法律常识"},
{"id": "law-222", "q": "李克强总理指出，要继续促进教育公平，使全国财政性教育经费支出占国内生产总值比例超过4%。如果某地财政教育经费投入不足，对这一问题，假设你是当地人大代表，可以：", "options": ["行使任免权，罢免在教育投入上不足的政府领导", "行使质询权，督促当地政府依法落实财政教育经费的投入", "行使调查权，联名其他代表提请人大监督财政教育经费的使用", "行使决定权，统筹当地政府的政府教育经费投入"], "a": 1, "e": ".【B】人大代表主要享有审议权、提案权、表决权、询问权和质询权、选举权、罢免权、建议权、批评权等。B项正确：人大代表具有质询权，是指人大代表依照有关法律规定，有对本级人民政府及其所属工作部门，本级人民法院、人民检察院提出质询并要求必须予以答复的权利。人大代表发现某地财政教育经费投入不足，督促当地政府依法落实财政教育经费的投入，是行使质询权的体现。A项错误：人大代表具有任免权，可以罢免国家机关领导人员。但必须在人大举行会议期间提出，且须进行会议表决。C项错误：人大代表的权利中不包括调查权，且“联名其他代表提请人大监督财政教育经费的使用”更像监督权而非调查权。D项错误：人大代表无决定权这一权利。故正确答案为B。", "tag": "法律常识"},
{"id": "law-223", "q": "全国人大及其常委会和国务院行使不同的职权，其中全国人大常委会行使的职权是：", "options": ["批准省、自治区、直辖市的区域划分", "决定省、自治区、直辖市的部分地区范围内进入紧急状态", "决定同外国缔结的条约和重要协定的批准和废除", "审查和批准国民经济和社会发展计划和计划执行情况的报告"], "a": 2, "e": ".【C】C项正确，我国《宪法》第六十七条规定：“全国人民代表大会常务委员会行使下列职权：……（十四）决定同外国缔结的条约和重要协定的批准和废除……”。A、B两项是国务院行使的职权，D项是全国人民代表大会行使的职权。故正确答案为C。", "tag": "法律常识"},
{"id": "law-224", "q": "根据我国《选举法》规定，关于全国和地方各级人民代表大会的代表候选人提名产生，下列说法不正确的是：", "options": ["选民10 人联名推荐", "代表5 人联名推荐", "各政党单独推荐", "各人民团体联合推荐"], "a": 1, "e": ".【B】根据我国《选举法》第二十九条的规定，全国和地方各级人民代表大会的代表候选人，按选区或者选举单位提名产生。各政党、各人民团体，可以联合或者单独推荐代表候选人。选民或者代表，十人以上联名，也可以推荐代表候选人。A、C、D项说法均正确，B项错误。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-225", "q": "宪法是一个国家的根本大法，具有至高无上的地位，环顾世界各国宪法的产生和发展历程，其又呈现出各自不同的发展轨迹和特点，下列有关世界主要国家的宪法的发展与历史的表述不正确的是：", "options": ["英国是典型的不成文宪法国家，英国宪法的主体由不同历史时期颁布的宪法性文件构成", "法国是资产阶级国家中制宪最多的国家之一，共制定过15 部不同的宪法，法国现行宪法为1739 年颁布的《雅各宾宪", "1787 年的美国《联邦宪法》是世界上第一部成文宪法，迄今为止已经至少颁布了27 个宪法修正案", "新中国成立后，我国共颁布了四部宪法，其中现行的为1982 年颁布的宪法，该部宪法迄今已经进行了五次修订"], "a": 1, "e": ".【B】A项正确，英国是典型的不成文宪法国家，英国宪法除包括大量宪法惯例和宪法判例外，还包括各个历史时期颁布的宪法性文件。英国之所以保持不成文宪法，主要取决于英国资产阶级革命的特点以及习惯、历史传统与文化。B项错误，法国自18世纪资产阶级革命后，随着政治形势和阶级力量的变化，前后共制定过多部宪法。其中，1958年宪法，又称《第五共和国宪法》，是法国现行宪法。《雅各宾宪法》于1793年颁布，是法国第一部比较完整地体现资产阶级政治要求并在一定程度上反映小资产阶级和工人农民利益的宪法，但未付诸实施。C项正确，1787年的美国《联邦宪法》是世界上第一部成文宪法，也是世界上第一部比较完整的资产阶级成文宪法。它奠定了美国政治制度的法律基础，制定后多年来附有27条修正案，迄今继续生效。D项正确，中华人民共和国成立后，曾于1954年9月20日、1975年1月17日、1978年3月5日和1982年12月4日通过四个宪法，现行宪法为1982年宪法，并历经1988年、1993年、1999年、2004年、2018年五次修订。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-226", "q": "下列关于土地所有权的说法中正确的是：", "options": ["土地全部属于国家所有", "城市土地属于国家所有", "土地全部属于集体所有", "农村和城市郊区的土地，除由法律规定属于集体所有的以外，属于国家所有"], "a": 1, "e": ".【B】根据法律规定，城市的土地属于国家所有。农村和城市郊区的土地，除由法律规定属于国家所有的以外，属于集体所有；宅基地和自留地、自留山，也属于集体所有。所以土地并不是国家专属所有。矿藏和水流（包括海洋）是专属于国家所有的。故正确答案为B。本题相关知识点：关于自然资源的归属，《中华人民共和国宪法》第九条规定：矿藏、水流、森林、山岭、草原、荒地、滩涂等自然资源，都属于国家所有，即全民所有；由法律规定属于集体所有的森林和山岭、草原、荒地、滩涂除外。国家保障自然资源的合理利用，保护珍贵的动物和植物。禁止任何组织或者个人用任何手段侵占或者破坏自然资源。关于土地所有权，《中华人民共和国宪法》第十条规定：城市的土地属于国家所有。农村和城市郊区的土地，除由法律规定属于国家所有的以外，属于集体所有；宅基地和自留地、自留山，也属于集体所有。国家为了公共利益的需要，可以依照法律规定对土地实行征收或者征用并给予补偿。任何组织或者个人不得侵占、买卖或者以其他形式非法转让土地。土地的使用权可以依照法律的规定转让。一切使用土地的组织和个人必须合理地利用土地。", "tag": "法律常识"},
{"id": "law-227", "q": "某省人民政府的规章与国务院某一部门的规章不一致，按照法律规定，下列做法正确的是：", "options": ["由国务院裁决", "由最高人民法院裁决", "由国务院法制办公室裁决", "由全国人民代表大会常务委员会对违法的规章予以撤销"], "a": 0, "e": ".【A】根据《立法法》第八十六条：地方性法规、规章之间不一致时，由有关机关依照下列规定的权限作出裁决：（一）同一机关制定的新的一般规定与旧的特别规定不一致时，由制定机关裁决；（二）地方性法规与部门规章之间对同一事项的规定不一致，不能确定如何适用时，由国务院提出意见，国务院认为应当适用地方性法规的，应当决定在该地方适用地方性法规的规定；认为应当适用部门规章的，应当提请全国人民代表大会常务委员会裁决；（三）部门规章之间、部门规章与地方政府规章之间对同一事项的规定不一致时，由国务院裁决。根据授权制定的法规与法律规定不一致，不能确定如何适用时，由全国人民代表大会常务委员会裁决。本题属于部门规章之间、部门规章与地方政府规章之间对同一事项的规定不一致的情形，应由国务院裁决。故正确答案为A。", "tag": "法律常识"},
{"id": "law-228", "q": "我国有权制定行政法规的主体，限于：", "options": ["国务院", "国务院和省级人民政府", "国务院及国务院各部、各委员会", "国务院和省级人民政府及较大市的人民政府"], "a": 0, "e": ".【A】《中华人民共和国宪法》第八十九条第一款明确规定：作为最高国家行政机关，国务院可以“根据宪法和法律，规定行政措施，制定行政法规，发布决定和命令。”《立法法》第五十六条第一款规定：“国务院根据宪法和法律，制定行政法规。”《宪法》第90条规定：“各部、各委员会根据法律和国务院的行政法规、决定、命令，在本部门的权限内，发布命令、指示和规章。”由此可见，国务院有行政法规制定权，其下属各部委有发布规章的权力。故正确答案为A。本题相关知识点：行政法规调整的对象一般是行政管理领域带有普遍性、全局性、原则性以及意义重大的问题。行政规章的调整对象则限定在行政管理领域中某些特殊的、局部的、具体的问题。行政法规的制定主体是我国的中央政府，而行政规章的制定主体或是中央政府的组成部分，或是地方政府。行政法规的效力高于行政规章。行政法规可以直接依据宪法、全国人大及其常委会制定的法律（尤其是其中的行政法），对一般公民法人或其他组织在行政管理领域的权利义务作出具体规定；对于各种行政违法行为的处罚，可以在符合宪法、法律的前提下，作出带有创制性的规定；并且可以在不违背宪法、法律的情况下，对某些尚未受到法律调整的社会生活作出行政法规的调整。", "tag": "法律常识"},
{"id": "law-229", "q": "以下关于我国宪法中的规定，说法有误的是（）。", "options": ["如果遇到不能进行下届全国人民代表大会代表选举的非常情况，由全国人民代表大会常务委员会以全体组成人员的三", "宪法的修改，由全国人民代表大会常务委员会或者四分之一以上的全国人民代表大会代表提议，并由全国人民代表大", "如果全国人民代表大会常务委员会认为必要，或者有五分之一以上的全国人民代表大会代表提议，可以临时召集全国", "法律和其他议案由全国人民代表大会以全体代表的过半数通过"], "a": 1, "e": ".【B】本题考查法律常识。A项正确，根据《宪法》第六十条第二款规定：“全国人民代表大会任期届满的两个月以前，全国人民代表大会常务委员会必须完成下届全国人民代表大会代表的选举。如果遇到不能进行选举的非常情况，由全国人民代表大会常务委员会以全体组成人员的三分之二以上的多数通过，可以推迟选举，延长本届全国人民代表大会的任期。在非常情况结束后一年内，必须完成下届全国人民代表大会代表的选举。”B项错误，根据《宪法》第六十四条第一款规定：“宪法的修改，由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过。”C项正确，根据《宪法》第六十一条第一款规定：“全国人民代表大会会议每年举行一次，由全国人民代表大会常务委员会召集。如果全国人民代表大会常务委员会认为必要，或者有五分之一以上的全国人民代表大会代表提议，可以临时召集全国人民代表大会会议。”D项正确，根据《宪法》第六十四条第二款规定：“法律和其他议案由全国人民代表大会以全体代表的过半数通过。”本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-230", "q": "下列机关中，无权制定地方性法规的是：", "options": ["省级人大及其常委会", "设区的市人大及其常委会", "自治州人大及其常委会", "县级人大及其常委会"], "a": 3, "e": ".【D】本题考查地方性法规的制定机关。A项正确，根据《中国人民共和国立法法》第七十二条规定:“省、自治区、直辖市的人民代表大会及其常务委员会根据本行政区域的具体情况和实际需要，在不与宪法、法律、行政法规相抵触的前提下，可以制定地方性法规。”因此省级人大及其常委会有权制定地方性法规。B项正确，根据《中国人民共和国立法法》第七十二条规定:“设区的市的人民代表大会及其常务委员会根据本市的具体情况和实际需要，在不与宪法、法律、行政法规和本省、自治区的地方性法规相抵触的前提下，可以对城乡建设与管理、环境保护、历史文化保护等方面的事项制定地方性法规，法律对设区的市制定地方性法规的事项另有规定的，从其规定。设区的市的地方性法规须报省、自治区的人民代表大会常务委员会批准后施行。”因此设区的市人大及其常委会有权制定地方性法规。C项正确，根据《中国人民共和国立法法》第七十二条规定：“自治州的人民代表大会及其常务委员会可以依照本条第二款规定行使设区的市制定地方性法规的职权。”因此自治州人大及其常委会有权制定地方性法规。D项错误，法律未授权县级人大及其常委会制定地方性法规的权利，因此其无权制定地方性法规。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-231", "q": "下列关于我国《宪法》的说法中，不正确的是：", "options": ["全国人民代表大会为最高国家权力机关，是唯一有权修改宪法的机关", "我国法律规定的行使解释宪法职权的是全国人民代表大会专门委员会", "宪法是其他法律的立法基础，其他法律是宪法的具体化，任何法律不得同宪法相抵触，否则无效", "于1949 年9 月29 日颁布的《中国人民政治协商会议共同纲领》具有临时宪法的作用"], "a": 1, "e": ".【B】本题考查法律常识。A项正确，根据《宪法》第五十七条规定：“中华人民共和国全国人民代表大会是最高国家权力机关。”第六十二条规定：“全国人民代表大会行使下列职权：（一）修改宪法。”第六十七条中规定的全国人民代表大会常务委员会无修改宪法的职权。B项错误，《宪法》第六十七条规定：“全国人民代表大会常务委员会行使下列职权：（一）解释宪法，监督宪法的实施。”并非题目中提到的全国人民代表大会专门委员会。C项正确，《宪法》序言中规定：“本宪法以法律的形式确认了中国各族人民奋斗的成果，规定了国家的根本制度和根本任务，是国家的根本法，具有最高的法律效力。”《宪法》第五条第三款规定：“一切法律、行政法规和地方性法规都不得同宪法相抵触。”D项正确，1949年9月29日，中国人民政治协商会议第一届全体会议选举了中央人民政府委员会，宣告了中华人民共和国的成立，并且通过了起临时宪法作用的《中国人民政治协商会议共同纲领》。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-232", "q": "2015 年，全国人大常委会组织开展了对《职业教育法》《水污染防治法》《消费者权益保护法》《农业法》《民族区域自治法》《老年人权益保障法》等几部法律实施情况的检查工作，这是人常行使（）职能的重要表现。", "options": ["立法", "普法", "监督", "审查"], "a": 2, "e": ".【C】本题考查宪法。A项错误，根据《宪法》第六十七条规定，全国人民代表大会常务委员会行使下列职权：（一）解释宪法，监督宪法的实施；（二）制定和修改除应当由全国人民代表大会制定的法律以外的其他法律；（三）在全国人民代表大会闭会期间，对全国人民代表大会制定的法律进行部分补充和修改，但是不得同该法律的基本原则相抵触；（四）解释法律。题干体现的是全国人大常委会对法律实施情况的检查工作，不属于立法职能，故选项错误。B项错误，题干体现的是全国人大常委会对法律实施情况的检查工作，而非法律知识的普及工作，故选项错误。C项正确，题干体现的是全国人大常委会对法律实施情况的检查工作，这属于监督权的范畴，故选项正确。D项错误，根据《宪法》第六十七条规定，全国人民代表大会常务委员会行使下列职权：（五）在全国人民代表大会闭会期间，审查和批准国民经济和社会发展计划、国家预算在执行过程中所必须作的部分调整方案。题干没有体现人大常委会行使审查职能，故选项错误。故正确答案为C。", "tag": "法律常识"},
{"id": "law-233", "q": "按照当前我国法律规定，地方各级人民政府每届任期几年？", "options": ["三", "四", "五", "六"], "a": 2, "e": ".【C】C项正确：根据《中华人民共和国地方各级人民代表大会和地方各级人民政府组织法》第五十八条规定：地方各级人民政府每届任期五年。故正确答案为C。", "tag": "法律常识"},
{"id": "law-234", "q": "根据我国有关法律，以下说法不正确的是：", "options": ["依照我国《宪法》规定，任何组织或个人都不得有超越宪法和法律的特权", "依照我国《兵役法》规定，中华人民共和国的武装力量，由中国人民解放军、中国人民武装警察部队和民兵组成", "依照我国《全国人民代表大会和地方各级人民代表大会选举法》规定，设区的市的人民代表大会的代表，由选民直接", "依照我国《香港特别行政区基本法》规定，香港特别行政区实行高度自治，享有行政管理、立法权、独立的司法权和"], "a": 2, "e": ".【C】C项错误：我国《全国人民代表大会和地方各级人民代表大会选举法》第二条规定：全国人民代表大会的代表，省、自治区、直辖市、设区的市、自治州的人民代表大会的代表，由下一级人民代表大会选举。不设区的市、市辖区、县、自治县、乡、民族乡、镇的人民代表大会的代表，由选民直接选举；A项正确：我国《宪法》第五条规定：任何组织或者个人都不得有超越宪法和法律的特权；B项正确：我国《兵役法》第四条规定：中华人民共和国的武装力量，由中国人民解放军、中国人民武装警察部队和民兵组成；D项正确：我国《香港特别行政区基本法》第二条规定：全国人民代表大会授权香港特别行政区依照本法的规定实行高度自治，享有行政管理权、立法权、独立的司法权和终审权。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-235", "q": "宪法的基本原则是指人们在制定和实施宪法的过程中必须遵循的最基本的准则。下面对我国宪法的基本原则表述正确的是（）。", "options": ["人民主权原则、基本人权原则、法治原则和权力制约原则", "人民主权原则、罪名法定原则、法治原则和权力制约原则", "基本人权原则、依法解释原则、法治原则和经济中立原则", "基本人权原则、罪名法定原则、法治原则和经济中立原则"], "a": 0, "e": ".【A】A项正确，根据《宪法》第三条规定，“中华人民共和国的国家机构实行民主集中制的原则。”对上述原则有一定的体现。根据《宪法》第二条规定：“中华人民共和国的一切权力属于人民。”根据《宪法》第三十三条第三款规定：“国家尊重和保障人权。”根据《宪法》第五条规定：“中华人民共和国实行依法治国，建设社会主义法治国家。”B项错误，罪名法定原则是《刑法》的原则。C、D项错误，依法解释原则与经济中立原则是没有的。故正确答案为A。", "tag": "法律常识"},
{"id": "law-236", "q": "下列选项中不属于全国人民代表大会职权的是：", "options": ["行政立法，制定行政法规", "选举、任命和罢免国家机关领导人员", "审查和批准国家的预算", "修改宪法，监督宪法实施"], "a": 0, "e": ".【A】A项错误，全国人民代表大会是最高国家权力机关，根据《宪法》第六十二条的规定，全国人民代表大会的主要职权有：(一)修改宪法;(二)监督宪法的实施;(三)制定和修改刑事、民事、国家机构的和其他的基本法律;(四)选举中华人民共和国主席、副主席;(五)根据中华人民共和国主席的提名，决定国务院总理的人选;根据国务院总理的提名，决定国务院副总理、国务委员、各部部长、各委员会主任、审计长、秘书长的人选;(六)选举中央军事委员会主席;根据中央军事委员会主席的提名，决定中央军事委员会其他组成人员的人选;(七)选举最高人民法院院长;(八)选举最高人民检察院检察长;(九)审查和批准国民经济和社会发展计划和计划执行情况的报告;(十)审查和批准国家的预算和预算执行情况的报告;(十一)改变或者撤销全国人民代表大会常务委员会不适当的决定;(十二)批准省、自治区和直辖市的建置;(十三)决定特别行政区的设立及其制度;(十四)决定战争和和平的问题;(十五)应当由最高国家权力机关行使的其他职权。A项错误，根据《宪法》第八十九条规定：“国务院行使下列职权：(一)根据宪法和法律，规定行政措施，制定行政法规，发布决定和命令”。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-237", "q": "卢梭在《爱弥儿》一书中写道，妇女们应该在家中劳动，永远不要到需要讲话的公共集会上去······难道世界上还有比把家里收拾得井井有条的母亲更感人、更让人尊敬的吗？这表明卢梭反对妇女：", "options": ["争取人身自由权", "获得劳动权", "拥有教育权", "享有政治参与权"], "a": 3, "e": ".【D】政治参与权，即公民参与制定、通过或贯彻公共制度的行为的权利。它也是人权的一项基本权利。在当代，民主被视为一个国家政府体制合法性的基础，政治参与的普遍性和有效性则是检验民主制度真伪的标准。题干中“到需要讲话的公共集会上去”明显表达了公民的政治参与权。故正确答案为D。", "tag": "法律常识"},
{"id": "law-238", "q": "根据《宪法》规定，下列表述不正确的是：", "options": ["农村和城市郊区的土地，除由法律规定属于国家所有以外，属于集体所有", "国务院有权批准省、自治区、直辖市的建置和区域划分", "公民在年老、疾病或者丧失劳动能力的情况下，有从国家和社会获得物质帮助的权利", "地方各级人民检察院对产生它的国家权力机关和上级人民检察院负责"], "a": 1, "e": ".【B】根据我国《宪法》规定，有权批准省、自治区、直辖市的建置的是全国人大。有权批准省、自治区、直辖市区域划分的是国务院。故正确答案为B。", "tag": "法律常识"},
{"id": "law-239", "q": "下列关于国体与政体的说法，错误的是：", "options": ["国体决定政体，政体体现国体", "中国的国体为人民民主专政", "中国的政体是人民代表大会制", "常见的资本主义国家国体的种类有总统制、议会制"], "a": 3, "e": ".【D】国体即国家性质，也就是哪个阶级占统治地位，资本主义国家的国体是资产阶级专政，总统制、议会制都属于资本主义国家的政体，而非国体。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-240", "q": "2012 年底，首都各界齐聚人民大会堂，隆重纪念《中华人民共和国宪法》公布施行30 周年，习近平总书记强调指出，宪法与国家前途、人民命运息息相关。保证宪法实施，就是保证：", "options": ["人民民主专政的实现", "依法治国的实现", "人民根本利益的实现", "社会主义政治文明的实现"], "a": 2, "e": ".【C】2012年12月4日，习近平总书记在隆重纪念《中华人民共和国宪法》公布施行30周年的报告中指出：宪法与国家前途、人民命运息息相关。维护宪法权威，就是维护党和人民共同意志的权威。捍卫宪法尊严，就是捍卫党和人民共同意志的尊严。保证宪法实施，就是保证人民根本利益的实现。只要我们切实尊重和有效实施宪法，人民当家作主就有保证，党和国家事业就能顺利发展。故正确答案为C。", "tag": "法律常识"},
{"id": "law-241", "q": "关于我国宪法，下列说法不正确的是：", "options": ["不满四十五周岁的公民不能被选为国家主席", "人民行使国家权力的机关是各级人民政府", "人民法院和人民检察院均由人民代表大会产生", "城市郊区的土地，除由法律规定属于国家所有的以外，属于集体所有"], "a": 1, "e": ".【B】B项错误，《宪法》第二条规定，人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。而各级人民政府是权力机关的执行机关。其他各项表述正确。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-242", "q": "根据《宪法》和有关法律的规定，下列关于我国国家机构的表述错误的是：", "options": ["中华人民共和国主席、副主席由全国人民代表大会选举", "代表在人民代表大会各种会议上的发言和表决，不受法律追究", "设区的市的人民代表大会的代表由下一级人民代表大会选举产生", "有选举权和被选举权的年满五十周岁的中华人民共和国公民可以被选为中华人民共和国主席"], "a": 3, "e": ".【D】根据《宪法》第七十九条规定，中华人民共和国主席、副主席由全国人民代表大会选举。有选举权和被选举权的年满四十五周岁的中华人民共和国公民可以被选为中华人民共和国主席、副主席。D项中的“五十周岁”表述不准确。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-243", "q": "立是由哪一机关批准：", "options": ["全国人大", "全国人大常委", "国务院", "海南省人大"], "a": 2, "e": ".【C】本题考查宪法对国家机构职权的相关规定。根据宪法的规定，全国人大批准省、自治区和直辖市的建置。国务院批准省、自治区、直辖市的区域划分，批准自治州、县、自治县、市的建置和区域划分。三沙市属于地级市，其设立由国务院批准。故正确答案为C。", "tag": "法律常识"},
{"id": "law-244", "q": "新中国成立以来，特别是改革开放30 多年来，我国立法工作取得了举世瞩目的成就。建立起了以（）为统帅，以宪法相关法、民法、商法等多个法律部门的法律为主干的中国特色社会主义法律体系，国家经济建设、政治建设、文化建设、社会建设以及生态文明建设的各个方面均实现了有法可依。", "options": ["最高人民法院", "中国共产党", "法律", "宪法"], "a": 3, "e": ".【D】2011年1月24日，吴邦国委员长在形成中国特色社会主义法律体系座谈会上的讲话中说，“一个立足中国国情和实际、适应改革开放和社会主义现代化建设需要、集中体现党和人民意志的，以宪法为统帅，以宪法相关法、民法、商法等多个法律部门的法律为主干，由法律、行政法规、地方性法规等多个层次的法律规范构成的中国特色社会主义法律体系已经形成，国家经济建设、政治建设、文化建设、社会建设以及生态文明建设的各个方面实现有法可依。这是我国社会主义民主法制建设史上的重要里程碑，具有重大的现实意义和深远的历史意义。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-245", "q": "根据我国宪法规定，下列哪项权利属于公民的基本权利中的政治权利和自由：", "options": ["平等权", "言论自由", "宗教信仰自由", "批评、建议和检举权"], "a": 1, "e": ".【B】政治权利和自由是指公民依法享有的参加国家政治生活方面的权利和自由。具体包括两大方面：第一，选举权和被选举权；第二，政治自由。包括言论、出版、集会、结社、游行、示威的自由。故正确答案为B。", "tag": "法律常识"},
{"id": "law-246", "q": "下列表述错误的是：", "options": ["依据我国法律规定地级市不具备立法权", "海南省三沙市是我国总面积最大的地级市", "地级市与地区、自治州、盟属于同一行政层级", "地级市一般管辖区、县、旗、自治旗"], "a": 0, "e": ".【A】原《立法法》第六十三条规定：“较大的市的人民代表大会及其常务委员会根据本市的具体情况和实际需要，在不同宪法、法律、行政法规和本省、自治区的地方性法规相抵触的前提下，可以制定地方性法规，报省、自治区的人民代表大会常务委员会批准后施行。”“本法所称较大的市是指省、自治区的人民政府所在地的市，经济特区所在地的市和经国务院批准的较大的市。”A项提到的地级市中，有部分城市属于符合该条所规定的较大的市，有立法权。本题为选非题，故正确答案为A。【本题相关知识点】（1）海南省三沙市是中国地理纬度位置最南端的城市，目前是中国最年轻的地级市，海域面积260多万平方千米，是中国陆地面积最小、总面积最大、人口最少的城市。（2）2015年修正后的《立法法》对原第六十三条规定做了部分修改，具体内容见《立法法》第七十二条。", "tag": "法律常识"},
{"id": "law-247", "q": "某县法院在审理一起民事案件中，为查明案件事实，对一当事人的信件进行拆检，弄清了案情并作出了判决。下列说法正确的是：", "options": ["法院对当事人所有的信件都无权拆检", "法院为了查明案情可以对当事人的信件进行拆检", "法院对当事人与案件无关的信件无权拆检", "法院拆检当事人信件并不重要，重要的是作出公正的判决"], "a": 0, "e": ".【A】《宪法》第四十条规定：“中华人民共和国公民的通信自由和通信秘密受法律的保护。除因国家安全或者追查刑事犯罪的需要，由公安机关或者检察机关依照法律规定的程序对通信进行检查外，任何组织或者个人不得以任何理由侵犯公民的通信自由和通信秘密。”本题中，当事人的信件属于公民的通信秘密，是宪法赋予公民的基本权利。只有检察机关和公安机关因国家安全或追查刑事犯罪的需要才能依照法律规定的程序对通信进行检查，法院无权这样做。故正确答案为A。", "tag": "法律常识"},
{"id": "law-248", "q": "按照我国现行法律规定，下列说法不正确的是：", "options": ["国家为了公共利益的需要，可以对土地实行征收或征用", "宅基地、自留地、自留山属于集体所有", "任何组织或个人不得侵占、买卖或者以其他形式非法转让土地，土地的所有权可以依照法律的规定转让", "城市的土地属于国家所有，农村和城市郊区的土地，除法律规定属于国家所有以外，属于集体所有"], "a": 2, "e": ".【C】A项正确，根据《宪法》第十条规定：“国家为了公共利益的需要，可以依照法律规定对土地实行征收或者征用并给予补偿。”B项正确，根据《宪法》第十条规定：“宅基地和自留地、自留山，属于集体所有。”C项错误，根据《宪法》第十条规定：“任何组织或者个人不得侵占、买卖或者以其他形式非法转让土地。土地的使用权可以依照法律的规定转让。”因此，土地的所有权可以依照法律的规定转让的说法错误。D项正确，根据《宪法》第十条规定：“城市的土地属于国家所有。农村和城市郊区的土地，除由法律规定属于国家所有的以外，属于集体所有。”本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-249", "q": "根据我国现行《宪法》和有关组织的规定，下列关于我国现行立法体制权限划分的表述不正确的是：", "options": ["全国人大修改宪法，全国人大及其常委会可以制定和修改刑法、民法和其他基本法律", "省、自治区、直辖市的人民代表大会及其常委会可以制定地方性法规", "省、自治区人民政府所在市的人民政府，可以根据法律和行政法规，制定规章", "自治区人民代表大会有权制定自治条例和单行条例"], "a": 0, "e": ".【A】A项错误，《中华人民共和国立法法》第七条规定：“全国人民代表大会和全国人民代表大会常务委员会行使国家立法权。全国人民代表大会制定和修改刑事、民事、国家机构的和其他的基本法律。全国人民代表大会常务委员会制定和修改除应当由全国人民代表大会制定的法律以外的其他法律；在全国人民代表大会闭会期间，对全国人民代表大会制定的法律进行部分补充和修改，但是不得同该法律的基本原则相抵触。”因此A项的表述“全国人大及其常委会可以制定和修改刑法、民法和其他基本法律”有误，全国人大常委会没有权利制定和修改刑法、民法和其他基本法律。B项正确，根据《中华人民共和国立法法》第七十二条第一款规定：“省、自治区、直辖市的人民代表大会及其常务委员会根据本行政区域的具体情况和实际需要，在不同宪法、法律、行政法规相抵触的前提下，可以制定地方性法规。”C项正确，根据《中华人民共和国立法法》第八十二条第一款规定：“省、自治区、直辖市和设区的市、自治州的人民政府，可以根据法律、行政法规和本省、自治区、直辖市的地方性法规，制定规章。”D项正确，根据《中华人民共和国立法法》第七十五条第一款规定：“民族自治地方的人民代表大会有权依照当地民族的政治、经济和文化的特点，制定自治条例和单行条例。自治区的自治条例和单行条例，报全国人民代表大会常务委员会批准后生效。”本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-250", "q": "我国的人民代表大会制度，是实现人民当家作主和保障公民政治（）的主要形式。", "options": ["权力", "兴趣", "义务", "权利"], "a": 3, "e": ".【D】本题考查人民代表大会制度的内容。A项错误，政治权力是指统治阶级为了实现其阶级利益和建立一定的统治秩序而具有的一种组织性支配力，由此可知，权力的主体是统治阶级而非公民。B项错误，兴趣基于个人的精神需要，人民代表大会制度无法保障所有公民都对政治持有兴趣。C项错误，政治义务是宪法、法律规定的公民必须履行的对国家、社会的责任。政治义务由法律强制规定，不由人民代表大会制度保障。D项正确，权利一般是指法律赋予人实现其利益的一种力量，公民的政治权利是其参与政治活动的一切权利和自由的总称。人民代表大会制度作为我国的根本政治制度和国家政权组织形式，保障着公民政治权利的实现。故正确答案为D。", "tag": "法律常识"},
{"id": "law-251", "q": "某县为朝鲜族自治县，依照宪法，关于该县人大常委会主任或副主任说法正确的是：", "options": ["由朝鲜族公民担任主任", "由朝鲜族公民担任副主任", "主任或副主任中有朝鲜族公民即可", "主任必须由朝鲜族公民担任，副主任可由其他民族的公民担任"], "a": 2, "e": ".【C】根据《宪法》第一百一十三条第二款规定，自治区、自治州、自治县的人民代表大会常务委员会中应当由实行区域自治的民族的公民担任主任或者副主任。故正确答案为C。", "tag": "法律常识"},
{"id": "law-252", "q": "下列哪项职权不是全国人大常委会的职权：", "options": ["解释宪法，监督宪法的实施", "制定和修改基本法律", "废除同外国缔结的条约和重要协定", "撤销国务院制定的同宪法、法律相抵触的行政法规、决定和命令"], "a": 1, "e": ".【B】本题考查法律常识，主要涉及宪法的相关知识。《中华人民共和国宪法》第六十七条规定了全国人民代表大会常务委员会行使的职权，共二十一款。A项：正确，根据《中华人民共和国宪法》第六十七条第一款，解释宪法，监督宪法的实施属于全国人大常委会的职权。B项：错误，根据《中华人民共和国宪法》第六十二条第三款，制定和修改刑事、民事、国家机构的和其他的基本法律，属于全国人民代表大会的职权。根据《中华人民共和国宪法》第六十七条第二款，制定和修改除应当由全国人民代表大会制定的法律以外的其他法律，属于全国人大常委会的职权。故B项表述错误。C项：正确，根据《中华人民共和国宪法》第六十七条第十四款，决定同外国缔结的条约和重要协定的批准和废除，属于全国人大常委会的职权。D项：正确，根据《中华人民共和国宪法》第六十七条第七款，撤销国务院制定的同宪法、法律相抵触的行政法规、决定和命令，属于全国人大常委会的职权。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-253", "q": "每年3 月，我国都要召开全国人民代表大会和全国政治协商会议，全国人大代表和全国政协委员汇集北京，共商国是。以下关于“两会”代表、委员的表述，正确的是（）。", "options": ["代表的任务是参政议政，委员的任务是政治协商", "代表参加制定国家法律，委员协商国际重大事务", "人大是最高国家权力机关，政协是最高国家监督机关", "人大直接创建国家管理制度，政协间接创建国家管理制度"], "a": 1, "e": ".【B】A项错误，委员有政治协商、民主监督、参政议政的权利，而不是任务；C项错误，全国人民代表大会是最高国家权力机关，政协不是最高国家监督机关；D项错误，政协是不能创建国家管理制度的。故正确答案为B。", "tag": "法律常识"},
{"id": "law-254", "q": "依据《宪法》规定，关于公民权利和自由的表述，下列判断正确的是：", "options": ["劳动、受教育和依法服兵役既是公民的基本权利，又是公民的基本义务", "休息权的主体是全体公民", "公民在年老、疾病或者未丧失劳动能力的情况下，有从国家和社会获得物质帮助的权利", "2004 年《宪法修正案》规定，国家尊重和保障人权"], "a": 3, "e": ".【D】A项错误，《宪法》第五十五条规定：“保卫祖国、抵抗侵略是中华人民共和国每一个公民的神圣职责。依照法律服兵役和参加民兵组织是中华人民共和国公民的光荣义务。”B项错误，《宪法》第四十三条规定：“中华人民共和国劳动者有休息的权利。”C项错误，《宪法》第四十五条规定：“中华人民共和国公民在年老、疾病或者丧失劳动能力的情况下，有从国家和社会获得物质帮助的权利。”选项中说“未丧失劳动能力”。故正确答案为D。", "tag": "法律常识"},
{"id": "law-255", "q": "宪法是国家根本大法，具有最高法律效力，下列有关宪法法律效力的表述正确的是（）。", "options": ["在不成文宪法的国家中，宪法的法律效力高于其他法律", "在我国，任何法律法规都不得与宪法规范、宪法基本原则和宪法精神相抵触", "宪法的法律效力主要表现为对公民的行为约束", "宪法的法律效力不具有任何强制性"], "a": 1, "e": ".【B】本题考查宪法的法律效力。宪法是国家的根本大法，是规定国家各项基本制度和根本任务、规定国家机关的组织与活动的基本原则、保障公民基本权利的国家根本大法。A项错误，在不成文宪法国家，其宪法（宪法性法律）与普通法律的制定和修改程序完全相同，并没有法律效力上的差异而仅有法律内容上的差异，也不能以其为依据对其他法律进行违宪审查。B项正确，在我国，宪法具有最高的法律效力，具体表现为宪法是一般法律的制定基础和依据，一般法律的规定与宪法相抵触的无效。C项错误，宪法的法律效力不仅表现在对公民的行为约束上，更表现在：宪法是制定普通法律的依据，宪法是一切国家机关、社会团体和全体公民的最高行为准则。D项错误，宪法和其他法律一样，都是强制性规范，宪法强制法律和行为合宪。故正确答案为B。", "tag": "法律常识"},
{"id": "law-256", "q": "下列对选举中的平等原则的理解错误的是：", "options": ["男女平等", "一人一次一票", "票的效力相等", "地区平等"], "a": 3, "e": ".【D】本题已过时。根据2015年新修改的《选举法》第十四条第一款规定：“地方各级人民代表大会代表名额，由本级人民代表大会常务委员会或者本级选举委员会根据本行政区域所辖的下一级各行政区域或者各选区的人口数，按照每一代表所代表的城乡人口数相同的原则，以及保证各地区、各民族、各方面都有适当数量代表的要求进行分配。”因此，目前看来城乡已实现同票同权。我国平等选举原则的主要含义指：社会公民公平地享有选举权和被选举权，一人一票，同一次选举中每一选民只有一张选票，每张选票的效力相等。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-257", "q": "根据《宪法》规定，下列有关人民代表大会制度的表述，不正确的一项是：", "options": ["人民代表大会制度是我国的政体", "人民代表大会制度是我国的根本政治制度", "人民代表大会制度是共和制政体的一种具体表现形式", "人民代表大会是我国的政权组织形式"], "a": 3, "e": ".【D】A项正确，政体指一个国家政府的组织结构和管理体制，人民代表大会制度是我国人民民主专政的政权组织形式，是我国的政体。B项正确，人民代表大会制度是我国的根本政治制度，中华人民共和国的一切权力属于人民。人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。C项正确，共和制即共和政体，泛指国家代表机关和国家元首由选举产生的一种政治制度。人民代表大会制度是共和制政体的一种具体表现形式。D项错误，人民代表大会制度是我国的政权组织形式，而人民代表大会是我国宪法规定的权力机关。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-258", "q": "我国现行宪法规定：", "options": ["社会主义的公有财产不可侵犯；公民的私有财产不受侵犯", "中华人民共和国的公有财产神圣不可侵犯；公民的私有财产不受侵犯", "社会主义的合法的公有财产神圣不可侵犯；公民的私有财产不受侵犯", "社会主义的公有财产神圣不可侵犯；公民的合法的私有财产不受侵犯"], "a": 3, "e": ".【D】《宪法》第十二条规定：“社会主义的公有财产神圣不可侵犯。国家保护社会主义的公共财产。禁止任何组织或者个人用任何手段侵占或者破坏国家的和集体的财产。”《宪法》第十三条规定：“公民的合法的私有财产不受侵犯。国家依照法律规定保护公民的私有财产权和继承权。国家为了公共利益的需要，可以依照法律规定对公民的私有财产实行征收或者征用并给予补偿。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-259", "q": "某单位收发员为收集邮票，故意隐匿毁弃他人信件，其行为侵犯了宪法规定的公民的哪项权利：", "options": ["隐私权", "通信自由", "通讯秘密", "社会文化权利"], "a": 1, "e": ".【B】我国《宪法》第四十条规定：“中华人民共和国公民的通信自由和通信秘密受法律的保护。除因国家安全或者追查刑事犯罪的需要，由公安机关或者检察机关依照法律规定的程序对通信进行检查外，任何组织或者个人不得以任何理由侵犯公民的通信自由和通信秘密。”可见，通信自由是公民的基本权利，它包括公民与其他人进行正当通信的自由以及保守自己信件秘密的权利两方面内容。题干中提到某收发员为收集邮票，故意隐匿毁弃他人信件，侵犯了通信自由权利。故正确答案为B。本题相关知识点：", "tag": "法律常识"},
{"id": "law-260", "q": "根据我国《宪法》，以下关于国家机构的说法中不正确的是（）。", "options": ["全国人民代表大会有权罢免国家监察委员会主任", "自治区的自治条例需报全国人民代表大会批准生效", "国务院有权决定省内部分地区进入紧急状态", "乡、镇的建置和区域划分由省、直辖市的人民政府决定"], "a": 1, "e": ".【B】本题考查法律常识。A项正确，根据《中华人民共和国宪法》第六十三条规定：“全国人民代表大会有权罢免下列人员：（四）国家监察委员会主任。”B项错误，根据《中华人民共和国宪法》第一百一十六条规定：“民族自治地方的人民代表大会有权依照当地民族的政治、经济和文化的特点，制定自治条例和单行条例。自治区的自治条例和单行条例，报全国人民代表大会常务委员会批准后生效。自治州、自治县的自治条例和单行条例报省、自治区、直辖市的人民代表大会常务委员会批准后生效，并报全国人民代表大会常务委员会和国务院备案。”该选项中“全国人大”表述错误。C项正确，根据《中华人民共和国宪法》第八十九条规定：“国务院行使下列职权：（十六）依照法律规定决定省、自治区、直辖市的范围内部分地区进入紧急状态。”D项正确，根据《中华人民共和国宪法》第一百零七条第三款规定：“省、直辖市的人民政府决定乡、民族乡、镇的建置和区域划分。”本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-261", "q": "2018 年某大型玻璃厂超标排放大气污染物，严重污染了周边的大气环境。根据我国相关法律，下列哪项无违法记录且符合年限要求的主体有权提起公益诉讼？", "options": ["由周边住户合法有效推选出的某环保志愿者", "依法在邻省民政厅登记的某环保协会", "依法在玻璃厂所在地的县民政局登记的某环保中心", "在国外合法设立但尚未在我国民政部门登记的某环保基金会"], "a": 1, "e": ".【B】本题考查法律常识。《环境保护法》第五十八条规定：“对污染环境、破坏生态，损害社会公共利益的行为，符合下列条件的社会组织可以向人民法院提起诉讼：（一）依法在设区的市级以上人民政府民政部门登记；（二）专门从事环境保护公益活动连续五年以上且无违法记录。符合前款规定的社会组织向人民法院提起诉讼，人民法院应当依法受理。提起诉讼的社会组织不得通过诉讼牟取经济利益。”根据上述规定，无违法记录且符合年限要求的主体必须是依法在设区的市级以上人民政府民政部门登记的社会组织可以起诉。故正确答案为B。", "tag": "法律常识"},
{"id": "law-262", "q": "关于我国诉讼程序中的鉴定，下列说法错误的是：", "options": ["对于鉴定所形成的结果，当事人有异议的可申请重新鉴定", "鉴定人在鉴定意见上的签名或盖章均具有法律效力", "民事诉讼中，基于意思自治原则，鉴定只能由当事人申请", "刑事诉讼中，鉴定人是否有必要出庭由人民法院决定"], "a": 2, "e": ".【C】本题主要考查法律常识。A项正确，根据《最高人民法院关于民事诉讼证据的若干规定》第二十七条规定：“当事人对人民法院委托的鉴定部门作出的鉴定结论有异议申请重新鉴定，提出证据证明存在下列情形之一的，人民法院应予准许：（一）鉴定机构或者鉴定人员不具备相关的鉴定资格的；（二）鉴定程序严重违法的；（三）鉴定结论明显依据不足的；（四）经过质证认定不能作为证据使用的其他情形。对有缺陷的鉴定结论，可以通过补充鉴定、重新质证或者补充质证等方法解决的，不予重新鉴定。”以及第二十八条规定：“一方当事人自行委托有关部门作出的鉴定结论，另一方当事人有证据足以反驳并申请重新鉴定的，人民法院应予准许。”可知，对于鉴定所形成的结果，当事人有异议的可申请重新鉴定。根据《刑事诉讼法》第一百四十八条规定：“侦查机关应当将用作证据的鉴定意见告知犯罪嫌疑人、被害人。如果犯罪嫌疑人、被害人提出申请，可以补充鉴定或者重新鉴定。”由此可见，民事诉讼和刑事诉讼中，当事人均可以申请重新鉴定。B项正确，根据《中华人民共和国民事诉讼法》第七十七条第二款规定：“鉴定人应当提出书面鉴定意见，在鉴定书上签名或者盖章。”《中华人民共和国刑事诉讼法》第一百四十七条第一款规定：“鉴定人进行鉴定后，应当写出鉴定意见，并且签名。”由此可知，鉴定人的签名或者盖章均具有法律效力。C项错误，根据《中华人民共和国民事诉讼法》第七十六条规定：“当事人可以就查明事实的专门性问题向人民法院申请鉴定。当事人申请鉴定的，由双方当事人协商确定具备资格的鉴定人；协商不成的，由人民法院指定。当事人未申请鉴定，人民法院对专门性问题认为需要鉴定的，应当委托具备资格的鉴定人进行鉴定。”由此可见，鉴定的启动方式有二：一是当事人申请鉴定，二是法院委托鉴定。D项正确，根据《中华人民共和国刑事诉讼法》第一百九十二条第三款规定：“公诉人、当事人或者辩护人、诉讼代理人对鉴定意见有异议，人民法院认为鉴定人有必要出庭的，鉴定人应当出庭作证。经人民法院通知，鉴定人拒不出庭作证的，鉴定意见不得作为定案的根据。”可见鉴定人是否出庭，取决于人民法院是否认为有必要。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-263", "q": "下列哪种情形最可能实行一审终审：", "options": ["基层人民法院审理被告提出反诉的买卖合同纠纷案件", "基层人民法院审理夫妻双方争夺子女抚养权的离婚案件", "中级人民法院审理在本辖区有重大影响的合同纠纷案件", "基层人民法院审理权利义务关系明确的租赁合同纠纷案件"], "a": 3, "e": ".【D】《民事诉讼法》第一百六十二条规定，基层人民法院和它派出的法庭审理符合本法第一百五十七条第一款规定的简单的民事案件，标的额为各省、自治区、直辖市上年度就业人员年平均工资百分之三十以下的，实行一审终审。《民事诉讼法》第一百五十七条规定，基层人民法院和它派出的法庭审理事实清楚、权利义务关系明确、争议不大的简单的民事案件，适用本章规定。基层人民法院和它派出的法庭审理前款规定以外的民事案件，当事人双方也可以约定适用简易程序，D项符合。故正确答案为D。", "tag": "法律常识"},
{"id": "law-264", "q": "人民法院审理民事案件时，会将举证、质证过程安排在", "options": ["庭审准备阶段", "法庭辩论阶段", "法庭调查阶段", "法庭合议阶段"], "a": 2, "e": ".【C】本题主要考查民事诉讼法的主要内容。A项错误，庭审准备是开庭审理的最初阶段，是衔接审理前准备与开庭审理的一个阶段，庭审准备主要完成两项工作：（1）告知当事人及其他诉讼参与人出庭日期；（2）发布开庭审理公告。B项错误，法庭辩论，是指在审判人员的主持下，当事人及其诉讼代理人就法庭调查的事实、证据，阐明自己的意见，反驳对方的主张，相互进行辩论的诉讼活动。C项正确，法庭调查，是指审判人员在法庭上对案件事实、证据进行全面审查、核实的诉讼活动。法庭调查是庭审的重要环节，是对案件进行实体审理的重要阶段。通过双方当事人对案件事实的陈述、举证、质证，人民法院审查、核实、认证，为查清案件事实和正确适用法律提供客观依据。所以举证、质证过程安排在法庭调查阶段。D项错误，法庭合议，法庭辩论终结后，当事人不愿调解或调解未能达成协议的，合议庭应当对案件及时进行评议。合议庭应当就案件事实的认定、是非责任的划分、适用的法律及处理结果进行评议。故正确答案为C。", "tag": "法律常识"},
{"id": "law-265", "q": "小张与小刘系夫妻，婚后小张患精神病，完全丧失辨认自己行为的能力，小刘准备离婚。下列说法符合法律规定的是：", "options": ["小刘是小张第一顺位法定监护人，但其不能在离婚诉讼中作为小张的诉讼代理人", "小张的父亲作为小张的诉讼代理人参加离婚诉讼后，可以根据小张与小刘感情破裂的实际情况，代替小张对是否同意", "小张的父亲作为小张的诉讼代理人，如果不能到庭，法院不能判决准予离婚", "如果小刘愿意放弃全部夫妻共同财产，则可以与小张协议离婚"], "a": 0, "e": ".【A】A项正确：配偶作为原告提起离婚诉讼，被告为无民事行为能力人，需除了配偶外的近亲属作为诉讼代理人。A项中，小刘是小张的配偶，故其离婚诉讼中不能作为小张的诉讼代理人。B项错误：诉讼代理人不能对是否同意离婚作出意思表示，因为法律赋予公民以婚姻自主权，由公民自主决定婚姻问题，他人不能替代。B项中，小张的父亲不能代替小张作出意思表示，是否离婚只能由法院根据婚姻状况及感情破裂程度，作出是否离婚的判决。C项错误：无民事行为能力人的离婚诉讼，当事人的法定代理人应当到庭；法定代理人不能到庭的，人民法院应当在查清事实的基础上，依法作出判决。C项中，“法院不能判决”的表述错误。D项错误：对于无民事行为能力人的离婚，只能通过诉讼进行，而不能协议离婚，因为无民事行为能力人不能进行民事活动，其所作出的意思表示是无效的。D项中，“可以与小张协议离婚”表述错误。故正确答案为A。", "tag": "法律常识"},
{"id": "law-266", "q": "“正义不仅要实现，而且要以看得见的方式实现”，这句话体现了程序正义，即裁判结论要得到人们的普遍认可，裁判者必须确保判决符合公正、正义的要求。下列说法违背了程序正义的是：", "options": ["刑事案件的判处要重证据，不轻信口供", "罚款应当由作出罚款决定的行政机关收缴", "与案件有利害关系的审判人员，应当回避", "证人证言必须在法庭上经过询问、质证并查证属实后才能作为定案依据"], "a": 1, "e": ".【B】程序正义，即看得见的正义，意思是说：案件不仅要判得正确、公平，并完全符合实体法的规定和精神，而且还应当使人感受到判决过程的公平性和合理性。而我国实施罚款决定和罚款收缴分离的原则，是为了加强对罚款活动的监督。故B项说法违背了程序正义。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-267", "q": "下列关于民事纠纷诉讼的说法，不符合法律规定的是：", "options": ["我国民事诉讼实行两审终审制", "二审案件由审判员组成的合议庭进行审理，合议庭成员为单数", "起诉时，必须以书面形式向人民法院提交起诉状", "简易程序只适用于基层人民法院及其派出法庭"], "a": 2, "e": ".【C】A项，《民事诉讼法》第十条规定：“人民法院审理民事案件，依照法律规定实行合议、回避、公开审判和两审终审制度。”A项正确。B项，《民事诉讼法》第四十条第一款规定：“人民法院审理第二审民事案件，由审判员组成合议庭。合议庭的成员人数，必须是单数。”B项正确。C项，《民事诉讼法》第一百二十条规定：“起诉应当向人民法院递交起诉状，并按照被告人数提出副本。书写起诉状确有困难的，可以口头起诉，由人民法院记入笔录，并告知对方当事人。”由此可知，起诉时不是必须以书面形式，C项错误。D项，《民事诉讼法》第一百五十七条规定：“基层人民法院和它派出的法庭审理事实清楚、权利义务关系明确、争议不大的简单的民事案件，适用本章规定。基层人民法院和它派出的法庭审理前款规定以外的民事案件，当事人双方也可以约定适用简易程序。”D项正确。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-268", "q": "下列做法符合我国法律规定的是：", "options": ["甲公司向法院起诉乙公司长期拖欠农民工工资", "丙某向法院起诉外来车辆非法占用本单位停车位", "某人向法院起诉邻居搭盖房屋、影响自家采光", "某报社下属编辑部向法院起诉丁某盗版侵权行为"], "a": 2, "e": ".【C】原《民事诉讼法》第一百零八条（2012年修订并于2013年1月1日施行的《民事诉讼法》第一百一十九条）规定：“起诉必须符合下列条件：原告是与本案有直接利害关系的公民、法人和其他组织”A、B、D三项错误，甲公司、丙某和某报社下属编辑部都不是被告行为的直接被侵害对象，不存在直接利益关系，不具备起诉资格；C项正确，某人因为邻居搭盖房屋、影响自己采光，某人及其邻居存在直接利害关系。故正确答案为C。", "tag": "法律常识"},
{"id": "law-269", "q": "关于我国人民调解制度，下列说法正确的是：", "options": ["基层人民检察机关对人民调解委员会调解民间纠纷进行业务指导", "村民委员会、居民委员会、企业事业单位必须设立人民调解委员会", "人民调解委员会调解民间纠纷，可依法适当收取费用，但不能超出工作经费需要"], "a": 1, "e": ".【B】A选项错误，《人民调解法》第5条：“基层人民法院对人民调解委员会调解民间纠纷进行业务指导”；C选项错误，《人民调解法》第8条：“村民委员会、居民委员会设立人民调解委员会。企业事业单位根据需要设立人民调解委员会”；D选项错误，《人民调解法》第4条：“人民调解委员会调解民间纠纷，不收取任何费用”。故正确答案为B。", "tag": "法律常识"},
{"id": "law-270", "q": "下列人民法院作出的民事裁定，哪项当事人不可以上诉：", "options": ["关于不予受理的裁定", "关于驳回起诉的裁定", "关于管辖权异议的裁定", "关于财产保全的裁定"], "a": 3, "e": ".【D】民事裁定是指法院为处理民事诉讼中的各种程序性事项所作出的结论性判定。裁定适用于下列范围：可以上诉：不予受理、对管辖权有异议、驳回起诉。不能上诉但可申请复议：财产保全和先予执行。不能上诉也不能申请复议：准许或者不准许撤诉、中止或者终结诉讼、补正判决书中的笔误、中止或者终结执行、不予执行仲裁裁决。A项错误，可上诉；B项错误，可上诉；C项错误，可上诉；D项正确，人民法院可以依当事人的申请或者依职权作出财产保全或者先予执行的裁定。该裁定一经作出，即具有法律效力，当事人不能上诉。当事人不服该裁定，可以向作出该裁定的人民法院申请复议一次，但复议期间不停止对该裁定的执行。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-271", "q": "下列说法符合我国著作权法规定的是：", "options": ["中国公民未发表的作品不享有著作权", "外国人的作品首先在中国境内出版的，享有著作权", "美术作品出版后，该美术作品原件的展览权归出版人享有", "合作作品的著作权保护期截止于最早死亡的作者死亡后第五十年"], "a": 1, "e": ".【B】本题考查法律常识。A项错误，根据《中华人民共和国著作权法》第二条第一款规定：“中国公民、法人或者其他组织的作品，不论是否发表，依照本法享有著作权。”B项正确，根据《中华人民共和国著作权法》第二条第三款规定：“外国人、无国籍人的作品首先在中国境内出版的，依照本法享有著作权。”C项错误，根据《中华人民共和国著作权法》第十条规定：“著作权包括下列人身权和财产权：……（八）展览权，即公开陈列美术作品、摄影作品的原件或者复制件的权利……”。所以展览权归著作权人所有，而不是出版人。D项错误，根据《中华人民共和国著作权法》第二十一条第一款规定：“公民的作品，其发表权、本法第十条第一款第（五）项至第（十七）项规定的权利的保护期为作者终生及其死亡后五十年，截止于作者死亡后第五十年的12月31日；如果是合作作品，截止于最后死亡的作者死亡后第五十年的12月31日。”故正确答案为B。", "tag": "法律常识"},
{"id": "law-272", "q": "甲乙两公司签订钢铁买卖合同，并约定货到付款。甲公司交货前夕得知乙公司全部账户因民事纠纷已被冻结，遂决定暂不向乙公司交货。关于甲公司的行为，下列说法正确的是：", "options": ["因合同约定货到付款，甲公司能履行合同中的交货义务而不履行，属于违约行为", "甲公司决定暂不向乙公司交货后，应及时将此事告知乙公司", "甲公司可以依法要求乙公司先付款再交货", "甲公司将暂不交货的决定告知乙公司后，买卖合同自行解除"], "a": 1, "e": ".【B】本题考查法律常识。A项错误，我国《合同法》第六十八条规定：“应当先履行债务的当事人，有确切证据证明对方有下列情形之一的，可以中止履行：(一)经营状况严重恶化；(二)转移财产、抽逃资金，以逃避债务；(三)丧失商业信誉；(四)有丧失或者可能丧失履行债务能力的其他情形。当事人没有确切证据中止履行的，应当承担违约责任。”乙公司账户因民事纠纷被冻结后，就会丧失或者可能丧失履行债务的能力，甲公司得知此信息后有权中止履行合同，故A项错误。我国《合同法》第六十九条规定：“当事人依照本法第六十八条的规定中止履行的，应当及时通知对方。对方提供适当担保时，应当恢复履行。中止履行后，对方在合理期限内未恢复履行能力并且未提供适当担保的，中止履行的一方可以解除合同。”由此可知，甲公司应及时将此事告知乙公司，B选项正确。甲公司无权要求乙公司先付款再交货，故C选项错误。甲公司将暂不交货的决定告知乙公司后，乙公司若能提供适当担保，合同应恢复履行，只有乙在合理期限内未恢复履行能力并且未提供适当担保，甲才可以解除合同，并非买卖合同可以自行解除，故D项错误。故正确答案为B。", "tag": "法律常识"},
{"id": "law-273", "q": "下列说法不符合我国法律规定的是：", "options": ["甲带侄子外出游玩，遇地震，甲无需为侄子在地震中所受损害承担责任", "甲用拳头殴打乙，乙将甲推倒后持刀将其扎死，乙无需为甲的死亡承担责任", "甲、乙发生口角，对骂过程中甲欲讹诈乙而故意倒地，乙无需为甲因倒地所受伤害承担责任", "甲、乙因言语不和而厮打―起，丙撞见后趁机殴打与其素来不和的甲，乙无需为丙殴打甲所造成的损害承担责任"], "a": 1, "e": ".【B】本题考查法律常识。A项正确，“遇地震”属于“不可抗力”，根据《刑法》第十六条规定，行为在客观上虽然造成了损害结果，但是不是出于故意或者过失，而是由于不能抗拒或者不能预见的原因所引起的，不是犯罪。根据《民法总则》第一百八十条规定，因不可抗力不能履行民事义务的，不承担民事责任。法律另有规定的，依照其规定。因而“不可抗力”属于免责情形，甲无需担责。B项错误，乙将甲推倒属于正当防卫，当甲被推倒证明不法侵害人已经被制伏，因而此时乙再持刀将其扎死不属于防卫，构成故意杀人罪，需要承担刑事责任。C项正确，甲欲讹诈乙故意倒地，即“甲倒地”是自己造成的，与乙没有因果关系，乙无需担责。D项正确，丙殴打甲的行为与乙没有关联，乙无需担责。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-274", "q": "17 岁的刘某在工厂打工，月收入3000 元。某日，刘某外出忘关水龙头导致租住屋浸水，房东要求赔偿遭拒，遂将其诉至法院。下列关于本案的说法正确的是：", "options": ["法院应判决刘某独立承担赔偿责任，因其是完全行为能力人", "法院应判决刘某承担主要赔偿责任，因其是限制行为能力人", "法院应判决刘某家长承担赔偿责任，因刘某是无民事行为能力人", "法院应判决刘某家长承担连带赔偿责任，因为刘某是部分行为能力人"], "a": 0, "e": ".【A】《民法总则》第十八条第二款规定：“十六周岁以上的未成年人，以自己的劳动收入为主要生活来源的，视为完全民事行为能力人。”刘某是年龄在16周岁以上的未成年人，而且能以自己的劳动收入为主要生活来源，故应视为完全民事行为能力人，独立承担赔偿责任。故正确答案为A。", "tag": "法律常识"},
{"id": "law-275", "q": "《中华人民共和国民法总则》自2017 年10 月1 日起施行。关于民法总则和民法通则的关系，下列说法错误的是：", "options": ["民法总则施行后，民法通则暂不废止", "民法通则规定了我国民法的基本规则，而民法总则的内容更加广泛", "民法总则是编纂民法典的第一步，吸取和借鉴了民法通则的相关条款", "民法通则规定向人民法院请求保护民事权利的诉讼时效期间为二年，民法总则将其改为三年"], "a": 1, "e": ".【B】本题主要考查法律常识。2017年3月8日，十二届全国人大五次会议审议民法总则草案，全国人大常委会副委员长李建国作关于民法总则（草案）的说明时表示，民法总则草案通过后暂不废止民法通则。民法通则既规定了民法的一些基本制度和一般性规则，也规定了合同、所有权及其他财产权、知识产权、民事责任、涉外民事关系法律适用等具体内容，被称为一部“小民法典”。民法总则草案基本吸收了民法通则规定的民事基本制度和一般性规则，同时作了补充、完善和发展，民法通则规定的合同、所有权及其他财产权、民事责任等具体内容，还需要在编撰民法典各分编时作进一步统筹，系统整合。A项表述正确，民法总则草案通过后暂不废止民法通则。B项表述错误，民法通则既规定了民法的一些基本制度和一般性规则，也规定了合同、所有权及其他财产权、知识产权、民事责任、涉外民事关系法律适用等具体内容，被称为一部“小民法典”。而民法总则基本吸收了民法通则规定的民事基本制度和一般性规则，民法通则规定的合同、所有权及其他财产权、民事责任等具体内容，还需要在编撰民法典各分编时作进一步统筹，系统整合。所以民法通则的内容更加广泛。C项表述正确，民法总则作为中国民法典的开篇之作，民法总则表决通过，标志着民法典编纂工作第一步已经完成。民法总则基本吸收了民法通则规定的民事基本制度和一般性规则，同时作了补充、完善和发展，所以民法总则吸取和借鉴了民法通则的相关条款。D项表述正确，根据《民法通则》第135条规定，向人民法院请求保护民事权利的诉讼时效期间为二年，法律另有规定的除外。《民法总则》第188条规定，向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定的，依照其规定。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-276", "q": "晚饭后李先生和儿子在小区散步时，有一条未牵绳的小狗冲出扑向他儿子，并咬伤了他的胳膊。为了保护儿子，李先生用脚踹小狗。但因为用力过猛，将小狗踹死了。后来，狗主人说这条狗十分名贵，要求李先生赔偿损失。对此，根据相关法律规定，下列说法正确的是：", "options": ["李先生的行为属于正当防卫，不需要承担法律责任", "李先生的行为属于防卫过当，需要承担法律责任", "遛狗不牵绳导致狗咬人，养狗者要承担侵权责任", "养狗者和李先生应承担各自的法律责任"], "a": 2, "e": ".【C】本题考查法律常识。A、B项错误，根据《侵权责任法》第三十条规定：“因正当防卫造成损害的，不承担责任。正当防卫超过必要的限度，造成不应有的损害的，正当防卫人应当承担适当的责任。”第三十一条规定：“因紧急避险造成损害的，由引起险情发生的人承担责任。如果危险是由自然原因引起的，紧急避险人不承担责任或者给予适当补偿。紧急避险采取措施不当或者超过必要的限度，造成不应有的损害的，紧急避险人应当承担适当的责任。”正当防卫必须是针对实施不法侵害的行为人实施防卫行为；紧急避险针对的是一切危险，可以是来源于违法犯罪人，也可以来源于自然灾害、动物的侵袭、人的生理病理造成的危险等，所以李先生的行为属于紧急避险。C项正确，《侵权责任法》第七十八条规定：“饲养的动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任，但能够证明损害是因被侵权人故意或者重大过失造成的，可以不承担或者减轻责任。”养狗者未牵狗绳，小狗咬伤路人，养狗者应当承担侵权责任。D项错误，李先生脚踹小狗的行为属于紧急避险，由引起险情发生的人即养狗者承担责任。故正确答案为C。", "tag": "法律常识"},
{"id": "law-277", "q": "根据我国现行《民法总则》，下列说法符合相关规定的是：", "options": ["法人分为企业法人和非企业法人", "不满八周岁的未成年人为无民事行为能力人", "向人民法院请求保护民事权利的诉讼时效期间为二年", "因自愿实施紧急救助行为造成受助人损害的，救助人承担民事责任"], "a": 1, "e": ".【B】本题考查法律常识。A项错误，《民法总则》规定，我国法人分为营利法人、非营利法人和特别法人。B项正确，《民法总则》第二十条规定：“不满八周岁的未成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。”C项错误，《民法总则》第一百八十八条第一款规定：“向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定的，依照其规定。”D项错误，《民法总则》第一百八十四条规定：“因自愿实施紧急救助行为造成受助人损害的，救助人不承担民事责任。”故正确答案为B。", "tag": "法律常识"},
{"id": "law-278", "q": "某区教育局将学区调整的情况张贴在各学校门口。刘某的住房被划入新的学区，但他没有及时了解情况，将房屋低价卖给了王某。对此，下列说法正确的是", "options": ["刘某认为区教育局公开学区信息不当，有权提起行政诉讼", "区教育局公开学区信息的行为构成行政不作为", "刘某有权以重大误解为由，解除与王某的房屋买卖合同", "区教育局应对刘某的损失承担赔偿责任"], "a": 0, "e": ".【A】本题考查法律常识。A项正确，根据《政府信息公开条例》第五十一条规定：“公民、法人或者其他组织认为行政机关在政府信息公开工作中侵犯其合法权益的，可以向上一级行政机关或者政府信息公开工作主管部门投诉、举报，也可以依法申请行政复议或者提起行政诉讼。”因此，如果刘某认为教育局做法不当的，有权提起行政诉讼。B项错误，行政不作为是指行政机关应当履行职责而不履行或者拖延履行职责。区教育局主动公开学区，并不存在不作为。C项错误，根据《民法总则》第一百四十七条规定：“基于重大误解实施的民事法律行为，行为人有权请求人民法院或者仲裁机构予以撤销。”刘某因为没有及时了解情况，将学区房低价卖给了王某，双方存在重大误解，刘某可以请求人民法院或者仲裁机构将合同撤销，但不能直接与王某解除合同。D项错误，刘某没有及时了解学区变动信息，是由于自己的过错，其不能要求区教育局承担责任。但是其将房屋低价卖给了王某，存在重大误解，刘某可以通过请求人民法院或者仲裁机构将合同撤销挽回损失。故正确答案为A。", "tag": "法律常识"},
{"id": "law-279", "q": "下列行为中，不属于无效民事法律行为的是：", "options": ["15 岁的乙与某销售公司签订购买2 部手机的合同", "不能辨认自己行为的精神病人甲与他人签订房屋购买合同", "丙雇佣丁的商船走私品牌手机，并与丁达成利润分成协议", "戊通过向领导行贿的方式与某国有公司签订销售合同"], "a": 0, "e": ".【A】本题考查法律常识。A项错误，根据《民法总则》第十九条规定，八周岁以上的未成年人为限制民事行为能力人，实施民事法律行为由其法定代理人代理或者经其法定代理人同意、追认，但是可以独立实施纯获利益的民事法律行为或者与其年龄、智力相适应的民事法律行为。15岁的乙购买手机属于超出其年龄、智力相适应的行为，故为效力待定的民事法律行为，而非无效民事法律行为。B项正确，根据《民法总则》第二十一条第一款规定，不能辨认自己行为的成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。第一百四十四条规定，无民事行为能力人实施的民事法律行为无效。因此精神病人甲的行为属于无效民事法律行为。C项正确，根据《民法总则》第一百五十三条第一款规定，违反法律、行政法规的强制性规定的民事法律行为无效，但是该强制性规定不导致该民事法律行为无效的除外。丙的行为违反了法律的强制性规定，属于无效民事法律行为。D项正确，根据《民法总则》第一百五十三条第一款规定，违反法律、行政法规的强制性规定的民事法律行为无效，但是该强制性规定不导致该民事法律行为无效的除外。因此戊的行为属于无效民事法律行为。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-281", "q": "某小区内业主共有的道路被物业公司划出停车位对外出租，其收益应该归所有。", "options": ["房地产开发商", "物业公司", "小区业主共有", "小区所在地居委会"], "a": 2, "e": ".【C】我国《物权法》第七十四条第三款规定：“占用业主共有的道路或者其他场地用于停放汽车的车位，属于业主共有。”因此小区内业主共有的道路被物业公司划出停车位对外出租，其收益应该归小区业主共有。故正确答案为C。", "tag": "法律常识"},
{"id": "law-282", "q": "下列言行体现公民没有自觉履行法定义务的是：①“听说你养母病了？”“与我无关，我是被收养的。”②“听说你生父病了？”“与我无关，我已经被叔叔收养了。”③“爸，大学催缴学杂费了。”“你都成年了，自己挣钱交去。”④“爸，小学催缴生活费了。”“我与你妈离婚了，找她要去。”", "options": ["①③", "①④", "②③", "②④"], "a": 1, "e": ".【B】本题考查法律常识。《婚姻法》第二十六条规定：国家保护合法的收养关系。养父母和养子女间的权利和义务，适用本法对父母子女关系的有关规定。由此可见养母和养子女的关系适用《婚姻法》中对父母子女关系的规定。《婚姻法》第二十一条规定，父母对子女有抚养教育的义务；子女对父母有赡养扶助的义务。据此可知养子女对养母有赡养扶助的义务，养母生病之后养子女有赡养的义务，故①表述错误。《婚姻法》第三十七条规定：离婚后，一方抚养的子女，另一方应负担必要的生活费和教育费的一部或全部，负担费用的多少和期限的长短，由双方协议；协议不成时，由人民法院判决。关于子女生活费和教育费的协议或判决，不妨碍子女在必要时向父母任何一方提出超过协议或判决原定数额的合理要求。据此可知，子女必要的生活费由父母双方协议决定，协议不成时由法院判决，但是子女在必要时可以就上述费用向父母任何一方提出合理要求，因此其父亲要求子女找母亲讨要的行为不符合法律规定，故④表述错误。因此①④表述错误。《婚姻法》二十六条第二款规定：养子女和生父母间的权利和义务，因收养关系的成立而消除，故被收养之后对生父母没有扶助义务，因此②符合法律规定。根据《婚姻法》第二十一条第二款规定，父母不履行抚养义务时，未成年的或不能独立生活的子女，有要求父母付给抚养费的权利。又因《婚姻法解释（一）》第二十条规定，婚姻法第二十一条规定的“不能独立生活的子女”，是指尚在校接受高中及其以下学历教育，或者丧失或未完全丧失劳动能力等非因主观原因而无法维持正常生活的成年子女。③中子女为已成年的大学生，不符合“未成年”和“不能独立生活的子女”的条件，其父可以不支付其学费。③符合法律规定。因此②③表述正确。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-283", "q": "张某家的梧桐树枝生长到李某家的院中，落下的树叶和树絮给李某带来一定的烦恼。双方为此发生争执，本案涉及的法律关系是：", "options": ["人身关系", "债权债务关系", "相邻关系", "宅基地使用权关系"], "a": 2, "e": ".【C】C项正确：相邻关系是指两个或两个以上相互毗邻的不动产的所有人或使用人，在行使不动产的所有权或使用权时，因相邻各方应当给予便利和接受限制而发生的权利义务关系。本题中，张某家的梧桐树枝生长到李某家的院中，可知张某家和李某家为相邻的不动产的使用人关系，涉及的法律关系为相邻关系，当选；A项错误：人身关系是基于人格和身份而产生的一系列的关系总和，即自然人基于相互间的人格和身份而产生的相互关系。题干没有体现人身关系，排除；B项错误：债权得请求他人为一定行为（作为或不作为）的民法上权利。本于权利义务相对原则，相对于债权者为债务，即必须为一定行为（作为或不作为）的民法上义务。在债权债务关系中，债权和债务都不能单独存在，否则即失去意义。题干没有体现债权债务关系，排除；D项错误：宅基地使用权指的是农村集体经济组织的成员依法享有的在农民集体所有的土地上建造个人住宅的权利。本题没有涉及宅基地使用权的问题，排除。故正确答案为C。", "tag": "法律常识"},
{"id": "law-284", "q": "未成年人晓辉通过微博发表了多张村委会主任的照片，并相应地配上设计的对白和评论，使用了“死狗”等带有人格贬损性质的言语，以表达对村干部行为的不满，村委会主任对晓辉提起民事诉讼，经过调查，被告晓辉的微博评论并不属实。此案中，晓辉的行为：", "options": ["侵犯了当事人的肖像权", "侵犯了当事人的名誉权", "侵犯了当事人的隐私权", "侵犯了当事人的身份权"], "a": 1, "e": ".【B】B项正确：《民法总则》第一百一十条规定：自然人享有生命权、身体权、健康权、姓名权、肖像权、名誉权、荣誉权、隐私权、婚姻自主权等权利。题中晓辉用侮辱、诽谤等方式对村委会主任造成了名誉上的损害，侵犯了当事人的名誉权。A项错误：“公民享有肖像权，未经本人同意，不得以营利为目的使用公民的肖像”。题干中未成年人晓辉发表村委会主任的照片并非以营利为目的，不符合题意。C项错误：隐私权是指公民享有的私人生活安宁与私人信息依法受到保护的权利，题干不涉及私人信息泄露，不符合题意。D项错误：身份权是指因为民事主体的特定身份而产生的权利，题干未体现特定身份关系，不符合题意。故正确答案为B。", "tag": "法律常识"},
{"id": "law-285", "q": "甲方将乙方诉至人民法院，要求乙方偿还借款期限为一年，且已到期的2 万元借款以及借款利息。在诉讼中，甲方向法庭提交了借据作为乙方借款的证据。下列与之相关的说法正确的是：", "options": ["甲方除了提交借据外，还需要提交向乙方实际付款的凭证，才能证明甲、乙双方之间的借贷关系真实发生", "虽然借据上未约定利息，但是乙方仍应按照年利率", "甲方提交借据足以证明甲、乙双方之间的借贷关系合法成立，乙方抗辩无效", "借据上没有约定利息，故乙方无须向甲方支付借期内利息"], "a": 3, "e": ".【D】本题考查法律常识。A项错误，根据《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》第二条第一款的规定：“出借人向人民法院起诉时，应当提供借据、收据、欠条等债权凭证以及其他能够证明借贷法律关系存在的证据。”甲方凭借借据提起诉讼，可以证明甲乙之间借贷法律关系存在。B项错误，根据《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》第二十九条规定：“借贷双方对逾期利率有约定的，从其约定，但以不超过年利率为限。未约定逾期利率或者约定不明的，人民法院可以区分不同情况处理：（一）既未约定借期内的利率，也未约定逾期利率，出借人主张借款人自逾期还款之日起按照年利率支付资金占用期间利息的，人民法院应予支持；（二）约定了借期内的利率但未约定逾期利率，出借人主张借款人自逾期还款之日起按照借期内的利率支付资金占用期间利息的，人民法院应予支持。”因此，甲乙之间借据上未约定利息，则视为不支付借款期间内的利息，但是甲可以主张乙自逾期还款之日起按照年利率支付资金占用期间利息。C项错误，根据《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》第十六条规定：“原告仅依据借据、收据、欠条等债权凭证提起民间借贷诉讼，被告抗辩已经偿还借款，被告应当对其主张提供证据证明。被告提供相应证据证明其主张后，原告仍应就借贷关系的成立承担举证证明责任。被告抗辩借贷行为尚未实际发生并能作出合理说明，人民法院应当结合借贷金额、款项交付、当事人的经济能力、当地或者当事人之间的交易方式、交易习惯、当事人财产变动情况以及证人证言等事实和因素，综合判断查证借贷事实是否发生。”因此，在甲提供借据的情况下，乙仍然可以抗辩。D项正确，我国《合同法》第二百一十一条规定：“自然人之间的借款合同对支付利息没有约定或者约定不明确的，视为不支付利息。自然人之间的借款合同约定支付利息的，借款的利率不得违反国家有关限制借款利率的规定。”按照法律和司法解释规定，这里的“不支付利息”是指在约定期限内或无约定期限时，借款权利人催告并主张利息前，借款不支利息。此外根据《最高人民法院关于审理民间借贷案件适用法律若干问题的规定》第二十五条第一款规定：“借贷双方没有约定利息，出借人主张支付借期内利息的，人民法院不予支持。”故正确答案为D。", "tag": "法律常识"},
{"id": "law-286", "q": "民法典对我国现行的、制定于不同时期的民事法律规范进行全面系统地编订纂修，以下法律规范不属于民法典范围的是：", "options": ["物权法", "婚姻法", "公务员法", "侵权责任法"], "a": 2, "e": ".【C】本题考查法律常识。编纂民法典是党的十八届四中全会提出的重大立法任务，是以习近平同志为核心的党中央作出的重大法治建设部署。编纂民法典，是对我国现行的、制定于不同时期的民法通则、物权法、合同法、担保法、婚姻法、收养法、继承法、侵权责任法和人格权方面的民事法律规范进行全面系统的编订纂修。《中华人民共和国民法典》共7编、1260条，各编依次为总则、物权、合同、人格权、婚姻家庭、继承、侵权责任，以及附则。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-287", "q": "我国民法典规定，未设立村集体经济组织的，（）可以依法代行村集体经济组织职能。", "options": ["村长", "村民委员会", "村党支部", "村民小组"], "a": 1, "e": ".【B】本题考查法律常识。能所需要的民事活动。未设立村集体经济组织的，村民委员会可以依法代行村集体经济组织的职能。”故正确答案为B。", "tag": "法律常识"},
{"id": "law-288", "q": "按照我国继承法的规定，财产继承的效力顺位为：", "options": ["遗嘱继承", "法定继承", "遗赠扶养协议", "遗赠扶养协议"], "a": 2, "e": ".【C】本题考查法律常识。根据《继承法》第五条规定：“继承开始后，按照法定继承办理；有遗嘱的，按照遗嘱继承或者遗赠办理；有遗赠扶养协议的，按照协议办理。”所以，遗赠扶养协议的效力最高，其次是遗赠或者遗嘱，效力最低的是法定继承。所以效力顺位是：遗赠扶养协议>遗嘱继承>法定继承。故正确答案为C。", "tag": "法律常识"},
{"id": "law-289", "q": "下列哪种情形可以在甲、乙之间成立民事法律关系？", "options": ["甲跟乙口头约定，第二天早上八点甲搭乘乙的车上班，结果乙忘记此事，导致甲错过一单50 万元的生意", "甲购物时看到乙在扶梯上摔倒，情急之下上前救乙，但乙仍被电梯夹伤", "甲在一场赌博中输给乙5 万元，现场支付3 万元，还有2 万元未偿还", "甲对乙说，如果乙考上研究生就把自己的劳力士手表赠送给乙，乙表示同意"], "a": 3, "e": ".【D】本题考查法律常识。民事法律关系是民事主体之间就一定的物或其他对象(客体)而发生的由国家强制力保证其实现的民事权利义务关系。A项错误，关于甲搭乘便车的行为属于由道德规范的情谊行为，不受法律拘束，不成立合同关系。乙忘记此事导致甲的损失不构成违约。B项错误，根据《民法总则》第一百八十四条规定：“因自愿实施紧急救助行为造成受助人损害的，救助人不承担民事责任。”题干中甲的行为属于自愿实施紧急救助行为，因此不承担民事责任。C项错误，根据《合同法》第五十二条规定：“有下列情形之一的，合同无效：（四）损害社会公共利益；（五）违反法律、行政法规的强制性规定。”赌博行为违反了我国治安管理法等法律明令禁止赌博的规定，也损害社会公共利益，属于违法行为。D项正确，根据《合同法》第一百八十五条规定：“赠与合同是赠与人将自己的财产无偿给予受赠人，受赠人表示接受赠与的合同。”根据《合同法》第一百九十条规定：“赠与可以附义务。赠与附义务的，受赠人应当按照约定履行义务。”题干中甲、乙的行为构成赠与合同。故正确答案为D。", "tag": "法律常识"},
{"id": "law-290", "q": "贾某经相亲与李某确立恋爱关系，贾某按照习俗给李某家送了彩礼。办理结婚登记手续后，开始准备婚礼。之后因贾某与李某感情破裂，办理了离婚登记手续，贾某要求李某返还彩礼，以下哪个理由可以得到法律支持？", "options": ["彩礼金额远远超过当地平均水平", "两人还未开始共同生活", "贾某家当前因发生变故生活困难", "两人还未举行婚礼"], "a": 1, "e": ".【B】本题考查法律常识。根据《最高人民法院关于适用<中华人民共和国婚姻法>若干问题的解释（二）》第十条规定：“当事人请求返还按照习俗给付的彩礼的，如果查明属于以下情形，人民法院应当予以支持：（一）双方未办理结婚登记手续的；（二）双方办理结婚登记手续但确未共同生活的；（三）婚前给付并导致给付人生活困难的。适用前款第（二）、（三）项的规定，应当以双方离婚为条件。”A项错误，彩礼金额超过了当地平均水平并非是法院支持退还彩礼的情形。B项正确，贾某与李某办理了婚姻登记手续，但两人还未开始共同生活的，可以得到法院的支持。C项错误，夫妻双方离婚，婚前给付彩礼并导致给付人生活困难的，是法院支持退还彩礼的情形。贾某家是在离婚后因变故导致生活困难，并非是因给付彩礼导致生活困难，不可以得到法院的支持。D项错误，两人未举行婚礼不是法院支持退还彩礼的情形。故正确答案为B。", "tag": "法律常识"},
{"id": "law-291", "q": "甲、乙二人于2016 年6 月6 日登记结婚，半年后因感情不和协议离婚。下列财产中属于二人共同财产的是：", "options": ["甲婚前购买的汽车", "甲于2016 年10 月购买彩票，中奖10 万元", "乙于2014 年用父母的钱全款购买的房子，用于婚后居住", "乙的祖父于2016 年6 月1 日为祝贺乙结婚，赠与乙的名人字画"], "a": 1, "e": ".【B】本题考查法律常识。根据《婚姻法》第十七条的规定，夫妻在婚姻关系存续期间所得的下列财产，归夫妻共同所有：（一）工资、奖金；（二）生产、经营的收益；（三）知识产权的收益；（四）继承或赠与所得的财产，但遗嘱或赠与合同中确定只归夫或妻一方的财产除外；（五）其他应当归共同所有的财产。夫妻对共同所有的财产，有平等的处理权。”A项错误，甲婚前购买的汽车，属于甲婚前个人财产，不属于甲乙共同财产。B项正确，甲在婚姻存续期间购买的彩票，所中的奖属于甲乙共同财产。C项错误，乙于2014年用父母的钱全款购买的房子，属于乙婚前个人财产，不属于甲乙共同财产。D项错误，乙的祖父赠与乙的名人字画，属于乙婚前个人财产，不属于甲乙共同财产。故正确答案为B。", "tag": "法律常识"},
{"id": "law-292", "q": "6 岁的小凡身高1.05 米，某日他瞒着父母独自去商场购买4000 元的平板电脑。当天，其父母将一切完好的平板电脑退还并要求退还全款。商场以“电子商品一经使用，只换不退”为由拒绝。根据相关法律，下列说法正确的是：", "options": ["商场既不用退货退款，也不用换货", "商场做法正确，电子产品只换不退", "商场做法缺少法律依据，应全额退款", "商场应收取平板电脑原价50"], "a": 2, "e": ".【C】本题考查法律常识。《民法总则》第二十条规定：“不满八周岁的未成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。”《民法总则》第一百四十四条规定：“无民事行为能力人实施的民事法律行为无效。”《民法总则》第一百五十七条规定：“民事法律行为无效、被撤销或者确定不发生效力后，行为人因该行为取得的财产，应当予以返还；不能返还或者没有必要返还的，应当折价补偿。有过错的一方应当赔偿对方由此所受到的损失；各方都有过错的，应当各自承担相应的责任。法律另有规定的，依照其规定。”在本案中，6岁的小凡属于无民事行为能力人，他购买4000元平板电脑的行为是无效的。小凡的父母将完好无损的平板电脑带到商场，要求退还的要求符合法律规定。因此，商场的做法缺乏法律依据，应全额退款。故正确答案为C。", "tag": "法律常识"},
{"id": "law-293", "q": "关于民事责任的承担，下列说法错误的是：", "options": ["二人以上依法承担按份责任，能够确定责任大小的，各自承担相应的责任；难以确定责任大小的，平均承担责任", "二人以上依法承担连带责任的，权利人有权请求部分或全部连带责任人承担责任", "因一方当事人的违约行为，损害对方人身权益、财产权益的，受损方有权选择请求其承担违约责任或者侵权责任", "民事主体因同一行为应当承担民事责任、行政责任和刑事责任的，承担行政责任或者刑事责任不影响承担民事责任；"], "a": 3, "e": ".【D】本题考查民事责任，需要结合选项具体分析。A项正确，《中华人民共和国民法总则》第一百七十七条规定：“二人以上依法承担按份责任，能够确定责任大小的，各自承担相应的责任；难以确定责任大小的，平均承担责任”。B项正确，《中华人民共和国民法总则》第一百七十八条规定：“二人以上依法承担连带责任的，权利人有权请求部分或者全部连带责任人承担责任”。C项正确，《中华人民共和国民法总则》第一百八十六条规定：“因当事人一方的违约行为，损害对方人身权益、财产权益的，受损害方有权选择请求其承担违约责任或者侵权责任”。D项错误，《中华人民共和国民法总则》第一百八十七条规定：“民事主体因同一行为应当承担民事责任、行政责任和刑事责任的，承担行政责任或者刑事责任不影响承担民事责任；民事主体的财产不足以支付的，优先用于承担民事责任”。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-294", "q": "租客小赵经房东老张的同意，将自己所租的房子（租金2000 元/月）其中的一个卧室以800 元/月的价格租给小刘。小刘在租住期间，擅自拆除门窗造成了价值10000 元的房屋损毁。据此，下列说法正确的是：", "options": ["小刘应向老张赔偿全部损失，但可向小赵追偿", "小赵应向老张赔偿全部损失，但可向小刘追偿", "小赵、小刘应分别赔偿老张6000 元、4000 元", "小赵在支付6000 元赔偿后，可向小刘追偿"], "a": 1, "e": ".【B】本题考查法律常识，主要考查民法知识。首先，《合同法》第二百二十四条规定：“承租人经出租人同意，可以将租赁物转租给第三人。承租人转租的，承租人与出租人之间的租赁合同继续有效，第三人对租赁物造成损失的，承租人应当赔偿损失。承租人未经出租人同意转租的，出租人可以解除合同。”其次，小刘与小赵之间存在合同关系，《合同法》第一百零七条规定：“当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。”因此，基于合同关系，小赵应向老张赔偿全部损失，但可向小刘追偿。因此，B项正确，A、C、D三项错误。故正确答案为B。", "tag": "法律常识"},
{"id": "law-295", "q": "李某家有一片果园，每到果子成熟时便有人潜入果园偷窃。下列情形李某需要承担侵权责任的是（）。", "options": ["李某在还击小偷甲的棒打时，致甲眼部受伤", "李某喝止小偷乙，乙慌不择路掉入水塘头部受伤", "李某在扑倒小偷丙时撞到村民徐某，致徐某手部骨折", "李某在果园设置捕兽陷阱，小偷丁跌落后致腿部神经受损"], "a": 2, "e": ".【C】本题考查法律常识。A项错误，根据我国《侵权责任法》第三十条规定：“因正当防卫造成损害的，不承担责任。正当防卫超过必要的限度，造成不应有的损害的，正当防卫人应当承担适当的责任。”小偷甲棒打李某，李某是在正当防卫时致使甲眼部受伤，因此李某不需要承担侵权责任。B项错误，根据我国《侵权责任法》第二十七条规定：“损害是因受害人故意造成的，行为人不承担责任。”李某只是喝止小偷乙偷窃的行为，但是乙被喝止后仍然逃跑，致使慌不择路掉入水塘头部受伤，乙受伤是因为自己的逃跑行为，李某不应承担责任。C项正确，依据《最高人民法院关于审理人身损害赔偿案件适用法律若干问题的解释》第三条规定：“二人以上共同故意或者共同过失致人损害，或者虽无共同故意、共同过失，但其侵害行为直接结合发生同一损害后果的，构成共同侵权，应当承担连带责任。”李某在扑倒小偷丙，是导致村民徐某损害后果发生的直接原因，二人对此应承担连带赔偿责任。因此表述正确。D项错误，根据我国《侵权责任法》第九十一条规定：“在公共场所或者道路上挖坑、修缮安装地下设施等，没有设置明显标志和采取安全措施造成他人损害的，施工人应当承担侵权责任。”李某挖的坑是在自家果园，非公共场所或道路上，不存在过错，非法律规定的应当承担侵权赔偿的情形。故正确答案为C。", "tag": "法律常识"},
{"id": "law-296", "q": "下列关于侵权损害赔偿的说法，正确的是", "options": ["甲的房屋发生大火，乙在救火中被烧伤，甲应赔偿乙的损失", "甲在登机时往发动机投掷硬币致航班延误，应赔偿乘客的损失", "乙在与甲争吵拉扯中猝死，甲对乙的死亡应承担损害赔偿责任", "甲将乙的照片制作成表情包供大家娱乐，侵害了乙的名誉权，应承担损害赔偿责任"], "a": 2, "e": ".【C】本题考查法律常识。A项错误，根据《民法总则》第一百二十一条规定：“没有法定的或者约定的义务，为避免他人利益受损失而进行管理的人，有权请求受益人偿还由此支出的必要费用。”选项中，乙救火的行为属于无因管理，而甲作为无因管理中的受益人，有义务偿还乙因管理造成的损失，属于无因管理之债，而非侵权之债。B项错误，《中华人民共和国治安管理处罚法》第二十三条第三款规定：“有下列行为之一的，处警告或者二百元以下罚款；情节较重的，处五日以上十日以下拘留，可以并处五百元以下罚款：（三）扰乱公共汽车、电车、火车、船舶、航空器或者其他公共交通工具上的秩序的；”因此，甲向飞机发动机内投硬币的行为违反《中华人民共和国治安管理处罚法》，应当承担行政责任，予以行政处罚，而非侵权赔偿。C项正确，《侵权责任法》第六条规定：“行为人因过错侵害他人民事权益，应当承担侵权责任。根据法律规定推定行为人有过错，行为人不能证明自己没有过错的，应当承担侵权责任。”乙在与甲争吵拉扯中猝死，甲对于乙的死亡存在过错，应承担损害赔偿责任。D项错误，侵害公民、法人名誉权的行为主要有：其一，以侮辱方式侵犯他人名誉,即以口头、书面或暴力方式，对他人进行人身攻击，贬损他人人格。其二，以诽谤方式侵犯他人名誉，即以隐瞒真相、捏造事实并加以传播的方式诋毁他人名誉，损害他人尊严。甲将乙的照片制作成表情包供大家娱乐，没有贬损他人名誉。故正确答案为C。", "tag": "法律常识"},
{"id": "law-297", "q": "下列做法具有合法性的是", "options": ["某超市在入口处警示“偷一罚十”", "某商家合同载明“解释权归商家所有”", "某内衣专卖店规定“特殊商品，售出后概不退换”", "某网店声明“定作商品，不适用七日内无理由退货的规定”"], "a": 3, "e": ".【D】本题主要考查法律常识。A项错误，所谓“偷一罚十”意思即超市有处罚权利，超市作为经营性企业非行政机关，没有行政处罚权，所以超市在入口处警示“偷一罚十”的行为不具备合法性。B项错误，《消费者权益保护法》第四条规定：“经营者与消费者进行交易，应当遵循自愿、平等、公平、诚实信用的原则。”因此，商家合同载明“解释权归商家所有”的行为违背了诚实信用、公平自愿的原则，损害了消费者利益，属于不公平不合理的规定，因此该做法不具有合法性。C项错误，根据《消费者权益保护法》第二十四条规定：“经营者提供的商品或者服务不符合质量要求的，消费者可以依照国家规定、当事人约定退货，或者要求经营者履行更换、修理等义务。没有国家规定和当事人约定的，消费者可以自收到商品之日起七日内退货；七日后符合法定解除合同条件的，消费者可以及时退货，不符合法定解除合同条件的，可以要求经营者履行更换、修理等义务。”因此，内衣店规定的“特殊商品，售后概不退换”的行为不具有合法性。D项正确，根据我国《消费者权益保护法》第二十五条第一款规定：“经营者采用网络、电视、电话、邮购等方式销售商品，消费者有权自收到商品之日起七日内退货，且无需说明理由，但下列商品除外：(一)消费者定作的；(二)鲜活易腐的；(三)在线下载或者消费者拆封的音像制品、计算机软件等数字化商品；(四)交付的报纸、期刊。”因此，网店声明“定作商品，不适用七日内无理由退货的规定”的行为是合法的。故正确答案为D。", "tag": "法律常识"},
{"id": "law-298", "q": "下列情形不构成民法所称“不当得利”的是（）。", "options": ["李某借用王某的单反相机，借用期间私自将相机出租给刘某，收取租金300 元", "张某在便利店买东西，收银员因疏忽大意错将50 元当成10 元找零给张某，张某收钱后即刻离开", "纪某为使其子能够通过某高校自主招生考试，找到严某“打招呼”，严某因此收取纪某8000 元打点费", "赵某请周某辅导其复习考试，并约定如及格将赠予周某价值500 元的化妆品，考后赵某认为肯定能及格，提前将化妆"], "a": 2, "e": ".【C】本题考查法律常识。《中华人民共和国民法总则》第一百二十二条规定：因他人没有法律根据，取得不当利益，受损失的人有权请求其返还不当利益。不当得利的成立要件有四：一方取得财产利益；一方受有损失；取得利益与所受损失间有因果关系；没有法律上的根据。注意，因不法原因而为给付的情况不属于不当得利。A项正确，李某借用王某的单反相机，并未取得相机的所有权，其将相机出租给刘某并收取租金的行为，同时满足上述四个成立要件，构成不当得利。B项正确，张某多收取的40元找零，使便利店遭受损失，满足上述四个成立要件，构成不当得利。C项错误，纪某给严某打点好处费的行为，属于因不法原因而为给付。这种情况不属于不当得利。D项正确，赵某与周某约定，当考试及格这一条件成立之后，赵某才应当赠与周某化妆品。但是最终赵某并未及格，此时周某收受赵某的化妆品，并没有合法的依据，使得赵某受到了损失。同时满足上述四个成立要件，构成不当得利。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-299", "q": "我国继承法规定，继承人对于被继承人生前的合法债务：", "options": ["应当负责全额偿还", "可以负责全额偿还", "可以不负责偿还", "应当在遗产的实际价值范围内负责清偿"], "a": 3, "e": ".【D】本题考查法律常识，主要考查继承法的知识。《继承法》第三十三条规定：“继承遗产应当清偿被继承人依法应当缴纳的税款和债务，缴纳税款和清偿债务以他的遗产实际价值为限。超过遗产实际价值部分，继承人自愿偿还的不在此限。继承人放弃继承的，对被继承人依法应当缴纳的税款和债务可以不负偿还责任。”所以，继承人对于被继承人生前的合法债务应当在遗产的实际价值范围内负责清偿。因此D项正确，A、B、C三项错误。故正确答案为D。", "tag": "法律常识"},
{"id": "law-300", "q": "关于法律、法规授权的组织，下列说法错误的是：", "options": ["受害妇女田某提起诉讼需要帮助，当地妇联给予支持", "公立大学对违反学校管理规定的学生不予颁发学位证书", "公安派出所对参与赌资较大的赌博行为处以400 元罚款", "保险行业协会对违反行业自律公约的保险公司处以罚款"], "a": 3, "e": ".【D】本题考查法律常识，主要涉及民法的相关知识。A项正确，《中华人民共和国妇女权益保障法》第五十四条规定：“妇女组织对于受害妇女进行诉讼需要帮助的，应当给予支持。”妇联即妇女联合会，其基本功能是代表、捍卫妇女权益、促进男女平等，亦同时维护少年儿童权益。所以田某可以请求当地妇联给予支持。B项正确，根据相关法律法规违反成绩、纪律等规定的均可不颁发学位证。如《中华人民共和国学位条例》第四条高等学校本科毕业生，成绩优良，达到下述学术水平者，授予学士学位：（一）较好地掌握本门学科的基础理论、专门知识和基本技能；（二）具有从事科学研究工作或担负专门技术工作的初步能力。如果行为人违反上述规定，未达到相关标准，即可不予颁发学位证书。故正确。C项正确，《中华人民共和国治安管理处罚法》第七十条规定：“以营利为目的，为赌博提供条件的，或者参与赌博赌资较大的，处5日以下拘留或者500元以下罚款；情节严重的，处10日以上15日以下拘留，并处500元以上3000元以下罚款。”同时，根据《治安管理处罚法》第九十一条规定：“治安管理处罚由县级以上人民政府公安机关决定；其中警告、五百元以下的罚款可以由公安派出所决定。”所以公安派出所对参与赌资较大的赌博行为处以400元罚款是合理的。D项错误，根据《中国保监会关于加强保险行业协会建设的指导意见》指出：“进行自律惩戒。对于违反协会章程、自律公约和管理制度、损害投保人和被保险人合法权益、参与不正当竞争等致使行业利益和形象受损的会员，可按章程或自律公约的有关规定，实施警告、业内批评、公开通报批评、扣罚违约金、开除会员资格等惩戒措施，也可建议监管部门依法对其进行行政处罚。”因此保险行业协会无罚款权。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-301", "q": "下列行为属于公民正确行使法定权利的是：①陈某向有关部门举报公交站旁的诈骗团伙②林某将朋友送给他的手表又送给他的弟弟③张某在妻子中止妊娠后第四个月起诉离婚④吴某应聘时因受到用人单位性别歧视而起诉至法院", "options": ["①②③", "①②④", "②③④", "①③④"], "a": 1, "e": ".【B】①正确，《刑事诉讼法》第一百零八条：任何单位和个人发现有犯罪事实或者犯罪嫌疑人，有权利也有义务向公安机关、人民检察院或者人民法院报案或者举报。②正确，依据《合同法》第一百八十五条：赠与合同是赠与人将自己的财产无偿给予受赠人。朋友把表送给林某后，所有权归林某，他有权处分，送给他弟弟合法。③错误，《婚姻法》第三十四条：女方在怀孕期间、分娩后一年内或中止妊娠后六个月内，男方不得提出离婚。④正确，《就业促进法》第六十二条：违反本法规定，实施就业歧视的，劳动者可以向人民法院提起诉讼。故正确答案为B。", "tag": "法律常识"},
{"id": "law-302", "q": "王某将自家三层楼房的承建工程承包给没有施工资质的包工头李某。双方合同约定，李某“包工不包料”，在施工过程中产生的一切责任由李某承担。李某找来邻居张某帮工，工资100 元/天。施工过程中脚手架倒塌，将在地面上递砖块的张某压成重伤。张某要求包工头李某赔偿医药费、误工费等。李某不允，双方闹至法院。那么，下列说法正确的是：", "options": ["李某承担全部责任", "王某、李某、张某都要承担责任", "李某、张某承担责任，王某没有责任", "王某、李某承担责任，张某没有责任"], "a": 3, "e": ".【D】根据《最高人民法院关于审理人身损害赔偿案件适用法律若干问题的解释》第十条规定，承揽人在完成工作过程中对第三人造成损害或者造成自身损害的，定作人不承担赔偿责任。但定作人对定作、指示或者选任有过失的，应当承担相应的赔偿责任。题干当中王某是定作人，李某是承揽人，张某和李某是雇佣关系，张某被压成重伤，李某应该承担责任。王某将楼房承包给没有施工资质的李某，选人有过失，因此王某也应当承担相应的赔偿责任。故正确答案为D。", "tag": "法律常识"},
{"id": "law-303", "q": "胡某承包的鱼塘被洪水冲垮，饲养的鱼游入杨某的蟹塘。胡某要求杨某返还游入蟹塘中的鱼，杨某认为鱼是自己游入的，没有义务返还。双方为此发生纠纷。经村干部调解，杨某同意补偿胡某3000 元。后杨某反悔，胡某诉至法院。下列关于本案的说法，正确的是：", "options": ["杨某蟹塘里游入胡某饲养的鱼，属于善意取得", "胡某诉杨某的理由可以是杨某获得了不当利益", "杨某对村干部的调解反悔，违反法律的规定", "双方在本案中均无过错，法院应依公平原则来处理"], "a": 1, "e": ".【B】B项正确：根据《民法总则》第一百二十二条：“因他人没有法律根据，取得不当利益，受损失的人有权请求其返还不当利益。”本题中，胡某承包的鱼塘被洪水冲垮，导致饲养的鱼游入杨某的蟹塘，属于由自然事件引起的不当得利关系，受损方胡某可以基于不当得利请求获益方杨某返还不当得利。A项错误：善意取得是指无权处分他人动产的占有人,在不法将动产转让给第三人后,如果受让人在取得该动产时出于善意,并以合理价格取得，就可依法取得对该动产的所有权。本题中不涉及到动产的转让和接受。C项错误：村干部的调解不具备法律上的强制执行的效力，杨某反悔不属于违法行为。D项错误：公平责任原则即指在法律没有规定适用无过错责任原则，而适用过错责任原则又对受害人显失公平时，依公平原则在当事人之间分配损害的归责原则。适用公平责任原则的基本条件是当事人对造成损害都没有过错。本题中，杨某是不当得利的获益方，不符合公平责任原则的适用条件。故正确答案为B。", "tag": "法律常识"},
{"id": "law-304", "q": "根据法律规定，下列情形中，甲可以向乙主张违约责任的是：", "options": ["乙表示愿意在开车赴省城办事时捎上甲，甲便退掉了之前购买的火车票，不料乙动身时忘了与甲的约定", "甲乙签订书面协议，约定甲买上房子乙便嫁给甲。但甲买上房子时，乙已嫁给他人", "甲乘坐乙开的出租车上班，中途因乙车速过快而发生车祸，甲受伤致残", "甲乙同乘火车，约定到A 站时乙提醒甲下车。火车到A 站时，二人均沉睡未醒，导致甲支出额外费用"], "a": 2, "e": ".【C】根据《民法总则》第二条规定，民法调整平等主体的自然人、法人和非法人组织之间的人身关系和财产关系。可总称为民事关系，这是一种社会生活关系，但并非所有的社会生活关系都是民法调整的对象，只有民法所规定的才受民法所调整，其他的社会生活关系受道德、习惯等的调整。因此，一个行为需要承担违约责任的前提是其应受民法调整。A、D两项都是好意施惠关系，不属于民事法律事实，不产生合同关系（即不产生违约责任或者缔约过失责任）。B项看似签订了书面协议，但是该项涉及“法外空间”。比如日出、日落、刮风、下雨等自然现象，宗教关系、同乡关系、师生关系、同学关系、恋爱关系、友谊关系的客观情况，这些总称为法外空间，不属于民事法律事实，不产生民事法律关系。违约责任是违反合同的民事责任的简称，是指合同当事人一方不履行合同义务或履行合同义务不符合合同约定所应承担的民事责任。C项属于运输合同，甲可以追究乙的违约责任。故正确答案为C。", "tag": "法律常识"},
{"id": "law-305", "q": "下列行为侵犯了公民肖像权的是：", "options": ["杨某碰到走失儿童小赵，未经其同意将其照片印制在寻亲广告上", "学校未经学生小王同意，将其获奖照片张贴在宣传窗内", "报社未经省委书记同意，将其视察民情的照片刊登在报纸上", "影楼未经张小姐同意，将其个人写真印制在宣传册上"], "a": 3, "e": ".【D】根据《民法总则》第一百一十条第一款规定“自然人享有生命权、身体权、健康权、姓名权、肖像权、名誉权、荣誉权、隐私权、婚姻自主权等权利。”A选项没有以营利为目的，B选项学校也没有以营利为目的，C选项报社没有以营利为目的，D选项满足未经本人同意，且以营利为目的两个条件。故正确答案为D。", "tag": "法律常识"},
{"id": "law-306", "q": "甲于2010 年3 月1 日开始使用“红红太阳”牌商标，乙同年4 月1 日开始使用相同商标。商标局于2011 年5 月10 日同一天收到甲、乙关于“红红太阳”商标的申请文件，但甲的文件是5 月8 日寄出的，乙的文件是5 月5 日寄出的。商标局应初步审定公告谁的申请？", "options": ["公告甲的申请，因甲、乙虽同时申请，但甲使用在先", "同时公告，因甲、乙申请日期相同", "公告乙的申请，因乙申请在先", "可以由商标局自由裁定"], "a": 0, "e": ".【A】《中华人民共和国商标法》第三十一条规定：“两个或者两个以上的商标注册申请人，在同一种商品或者类似商品上，以相同或者近似的商标申请注册的，初步审定并公告申请在先的商标；同一天申请的，初步审定并公告使用在先的商标，驳回其他人的申请，不予公告。”《商标法实施条例》第十八条第一款规定：“商标注册的申请日期以商标局收到申请书件的日期为准。”题目表述的寄出时间是迷惑信息，按照相关法律的规定，商标局应先初步审定公告甲的商标申请。故正确答案为A。", "tag": "法律常识"},
{"id": "law-307", "q": "下列不属于夫妻共同财产的是：", "options": ["婚前房屋在婚后所得的租金", "夫妻关系存续期间，军人的复员费和自主择业费", "婚后由一方父母出资购买的不动产，产权登记在出资人子女名下", "婚姻存续期间虽未实际取得，但明确可以取得的知识产权收益"], "a": 2, "e": ".【C】A项正确，根据最高人民法院民一庭意见——个人所有房屋的婚后收益认定及其处理中表明：一方个人所有的房屋婚后用于出租，其租金收入属于经营性收入，应认定为夫妻共同财产。B项正确，根据《最高人民法院关于适用<中华人民共和国婚姻法>若干问题的解释（二）》第十四条第一款规定：“人民法院审理离婚案件，涉及分割发放到军人名下的复员费、自主择业费等一次性费用的，以夫妻婚姻关系存续年限乘以年平均值，所得数额为夫妻共同财产。”C项错误，根据《最高人民法院关于适用<中华人民共和国婚姻法>若干问题的解释（三）》第七条第一款规定，婚后由一方父母出资购买的不动产，产权登记在出资人子女名下的，可按照婚姻法第十八条第（三）项的规定，视为只对自己子女一方的赠与，该不动产应认定为夫妻一方的财产。D项正确，根据《婚姻法》第十七条规定：“夫妻在婚姻关系存续期间所得的下列财产，归夫妻共同所有：……（三）知识产权的收益……”。根据《最高人民法院关于适用<中华人民共和国婚姻法>若干问题的解释（二）》第十二条规定：“婚姻法第十七条第三项规定的‘知识产权的收益’，是指婚姻关系存续期间，实际取得或者已经明确可以取得的财产性收益。”本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-308", "q": "返乡大学生陈某利用互联网销售家乡的土特农产品，取得了较好的收益，为了更好地发展当地的互联网经济，他准备发起成立本县电商协会。该协会的合法登记机关应是：", "options": ["县公安局", "县工商局", "县民政局", "县经信局"], "a": 2, "e": ".【C】根据《社会团体登记管理条例》第六条第一款规定：“国务院民政部门和县级以上地方各级人民政府民政部门是本级人民政府的社会团体登记管理机关。”故正确答案为C。", "tag": "法律常识"},
{"id": "law-309", "q": "2014 年12 月，钟某将名下的一处房屋出售给梁某，双方签订了买卖合同并约定于2015 年6 月付清全部房款后办理过户手续。2015 年1 月，该处房屋价格上涨，钟某后悔过早出售该房屋，又将该房屋出售给张某并约定在2015 年5 月办理过户手续。2015 年4 月，钟某将房屋重复出售的行为暴露，此时该房屋属于（）。", "options": ["钟某所有", "梁某所有", "张某所有", "梁某与张某共同所有"], "a": 0, "e": ".【A】根据我国《物权法》第九条第一款规定，“不动产物权的设立、变更、转让和消灭，经依法登记，发生效力；未经登记，不发生效力，但法律另有规定的除外”。题中截至2015年4月，该房产未办理过户登记手续，因此仍旧属于原所有人钟某所有。不管梁某还是张某都没有办理过户手续，所以BCD选项均错误。故正确答案为A。", "tag": "法律常识"},
{"id": "law-310", "q": "某股份有限公司经营管理出现严重困难，其股东甲担心自己的利益受到损失，欲提起解散公司之诉，则下列说法错误的是：", "options": ["甲须持有公司全部股东表决权10% 以上", "甲在起诉的同时可以申请人民法院对公司进行清算", "甲起诉时，向人民法院申请财产保全的，人民法院可以予以保全", "如甲坚持以其他股东和公司为共同被告，人民法院将驳回其对其他股东的起诉"], "a": 1, "e": ".【B】B项错误，《最高人民法院关于适用<中华人民共和国公司法>若干问题的规定（二）》第二条规定：“股东提起解散公司诉讼，同时又申请人民法院对公司进行清算的，人民法院对其提出的清算申请不予受理……”，因此，甲在起诉的同时，不能申请人民法院对公司进行清算。A项正确，根据《最高人民法院关于适用<中华人民共和国公司法>若干问题的规定（二）》第一条规定，单独或者合计持有公司全部股东表决权百分之十以上的股东，以下列事由之一提起解散公司诉讼，并符合公司法第一百八十三条规定的，人民法院应予受理：（四）经营管理发生其他严重困难，公司继续存续会使股东利益受到重大损失的情形。C项正确，根据《最高人民法院关于适用<中华人民共和国公司法>若干问题的规定（二）》第三条规定，股东提起解散公司诉讼时，向人民法院申请财产保全或者证据保全的，在股东提供担保且不影响公司正常经营的情形下，人民法院可予以保全。D项正确，根据《最高人民法院关于适用<中华人民共和国公司法>若干问题的规定（二）》第四条第二款规定，原告以其他股东为被告一并提起诉讼的，人民法院应当告知原告将其他股东变更为第三人；原告坚持不予变更的，人民法院应当驳回原告对其他股东的起诉。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-311", "q": "下列做法符合我国法律规定的是：", "options": ["某公立大学以其教学大楼产权作抵押向银行申请贷款", "某乡镇企业以所属土地所有权作抵押向银行申请贷款", "某农民以所属宅基地的使用权作抵押向银行申请贷款", "某国有企业以所属土地使用权作抵押向银行申请贷款"], "a": 3, "e": ".【D】根据《物权法》第一百八十四条规定：下列财产不得抵押：（一）土地所有权；（二）耕地、宅基地、自留地、自留山等集体所有的土地使用权，但法律规定可以抵押的除外；（三）学校、幼儿园、医院等以公益为目的的事业单位、社会团体的教育设施、医疗卫生设施和其他社会公益设施；（四）所有权、使用权不明或者有争议的财产；（五）依法被查封、扣押、监管的财产；（六）法律、行政法规规定不得抵押的其他财产。A项错误，“教学大楼”属于以公益为目的的设施，学校不得抵押，排除；B项错误，“土地所有权”不得抵押，排除；C项错误，“宅基地”不得抵押，排除；D项正确，土地使用权可以抵押，当选。故正确答案为D。", "tag": "法律常识"},
{"id": "law-312", "q": "甲乙两家是邻居，甲家在距乙家地基2 米处种有一棵大树。每逢刮大风，风便会将这棵树的一些大树枝刮落到乙家房屋上。乙担心会损坏房屋，多次找甲协商，要求甲将树枝砍去一些，被甲拒绝。某日，暴风雨即将来临，乙再次找甲协商却没找到，情急之下自己砍去了一些伸到自家房屋上的树枝。甲回家后要求乙赔偿500 元，乙不同意，甲将乙起诉至法院。下列说法正确的是：", "options": ["狂风暴雨即将来临，乙砍掉一些树枝来避免自己房屋的损害属于紧急避险，因而乙不应承担民事责任", "乙的行为已经构成了对甲财产权利的侵害，因为乙为自己的利益未经甲同意就砍掉了一些树枝，因此，乙应当承担赔", "虽然这棵树属于甲，但因伸到了乙的房顶，这棵树在乙房屋界内的部分应当属于乙，因此，乙砍掉那些树枝是合法的，", "乙的行为已经构成了对甲财产权利的侵害，因为乙为自己的利益未经甲同意就砍掉了一些树枝。但是乙在砍之前有意"], "a": 0, "e": ".【A】本题考查侵权行为与免责条款的相关知识。《最高人民法院关于贯彻执行〈民法通则〉若干问题的意见(试行)》第103条规定，相邻一方在自己使用的土地上挖水沟、水池、地窖等或者种植的竹木根枝伸延，危及另一方建筑物的安全和正常使用的，应当分别情况，责令其消除危险，恢复原状，赔偿损失。本题中，甲家的树可能对乙家房屋构成威胁，乙有权利要求甲加强对自家树的管理，甲也有义务排除对相邻一方的妨害。A项，紧急避险，是指为了使公共利益、本人或者他人的合法权益免受现实和紧急的损害危险，不得已而采取的、致人损害的行为。本题中，甲没有履行消除妨害的义务，乙在暴风雨来临时为了避免房屋损坏，不得已砍掉伸到自家房屋上的树枝，属于民法上的紧急避险，无需承担民事责任。该项表述正确。B项，本题中甲有义务消除妨害但没有履行义务，乙在狂风暴雨来临时，为了避免树枝刮落给自家房屋造成损坏而砍掉伸到自家房屋上的树枝，属于民法上的紧急避险，无需承担赔偿责任。该项表述错误。C项，树木的所有权属于甲，树枝是树木的一部分，不论其延伸到何处，其所有权均属于甲。该项表述错误。D项，本题中甲有义务消除妨害但没有履行义务，乙在狂风暴雨来临时，为了避免树枝刮落给自家房屋造成损坏而砍掉伸到自家房屋上的树枝，属于民法上的紧急避险，无需承担民事责任。该项表述错误。故正确答案为A。", "tag": "法律常识"},
{"id": "law-313", "q": "根据《商标法》，下列说法正确的是：", "options": ["商标中有商品地理标志的，不予注册", "国内某著名品牌通过一份申请就多个类别的商品申请注册同一商标", "某企业将QQ 消息声等其他企业特有的声音标识作为商标申请注册", "某经营者将“驰名商标”字样用于广告宣传、展览以及其他商业活动中"], "a": 1, "e": ".【B】本题考查法律常识。A项错误，根据《商标法》第十六条规定：“商标中有商品的地理标志，而该商品并非来源于该标志所标示的地区，误导公众的，不予注册并禁止使用；但是，已经善意取得注册的继续有效。前款所称地理标志，是指标示某商品来源于某地区，该商品的特定质量、信誉或者其他特征，主要由该地区的自然因素或者人文因素所决定的标志。”商标中有商品的地理标志，并非一律不予注册。B项正确，根据《商标法》第二十二条第二款规定：“商标注册申请人可以通过一份申请就多个类别的商品申请注册同一商标。”C项错误，根据《商标法》第八条规定：“任何能够将自然人、法人或者其他组织的商品与他人的商品区别开的标志，包括文字、图形、字母、数字、三维标志、颜色组合和声音等，以及上述要素的组合，均可以作为商标申请注册。”第九条规定：“申请注册的商标，应当有显著特征，便于识别，并不得与他人在先取得的合法权利相冲突。”虽然声音可以作为商标进行申请注册，但是QQ消息声是其他企业在先取得的权利，因此该企业不能将此声音标识作为商标申请注册。D项错误，根据《商标法》第十四条第五款规定：“生产、经营者不得将‘驰名商标’字样用于商品、商品包装或者容器上，或者用于广告宣传、展览以及其他商业活动中。”故正确答案为B。", "tag": "法律常识"},
{"id": "law-314", "q": "戴女士在某美容医院进行了肉毒素注射，注射前医生与她签过《知情同意书》，该同意书内容均为术后注意事项。注射两天后出现发烧、脸疼、头晕等症状，最后被医院诊断为肉毒素中毒，后续医疗费用又花费两万元。对此，根据相关法律规定，下列说法正确的是：", "options": ["因双方事先签订了《知情同意书》，所以医院没有责任", "戴女士自己身体有问题，因此她只能自己承担全部责任", "因《知情同意书》未履行了充分、完全的告知义务，因此医院要承担部分责任", "戴女士可依据医疗费发票、工资流水单等，向法院起诉，要求美容医院支付医疗费、营养费、误工费"], "a": 3, "e": ".【D】本题考查法律常识。根据《侵权责任法》第五十五条规定：“医务人员在诊疗活动中应当向患者说明病情和医疗措施。需要实施手术、特殊检查、特殊治疗的，医务人员应当及时向患者说明医疗风险、替代医疗方案等情况，并取得其书面同意；不宜向患者说明的，应当向患者的近亲属说明，并取得其书面同意。医务人员未尽到前款义务，造成患者损害的，医疗机构应当承担赔偿责任。”美容院虽然与戴女士签订了《知情同意书》，但该《知情同意书》内容均为术后注意事项，并无医疗风险等内容，医务人员未履行完全的告知义务，造成戴女士肉毒素中毒，医疗机构应承担赔偿责任，按照上述法条的规定，医疗机构对未履行告知义务造成的损害后果是承担完全赔偿责任，而非部分赔偿责任，因此，D项符合题意。故正确答案为D。", "tag": "法律常识"},
{"id": "law-315", "q": "春节期间，刘女士在某超市购买了两箱牛奶，一周后发现牛奶都已发霉变质。她找到超市要求退货，超市却告知牛奶销售商只是租赁其柜台，卖完牛奶就“人去楼空”。超市还拿出租赁协议，双方约定“谁销售谁负责”，让刘女士找牛奶销售商。对此，根据相关法律规定，下列说法正确的是：", "options": ["刘女士、销售商、超市共同担责", "因刘女士购买时未仔细辨别，所以她应当担责", "超市对进场销售的商品检查不到位应当承担全部责任", "超市承担责任后，刘女士还可向销售商进行追偿"], "a": 2, "e": ".【C】本题考查法律常识。《食品安全法》第一百四十八条第一款规定：“消费者因不符合食品安全标准的食品受到损害的，可以向经营者要求赔偿损失，也可以向生产者要求赔偿损失。接到消费者赔偿要求的生产经营者，应当实行首负责任制，先行赔付，不得推诿；属于生产者责任的，经营者赔偿后有权向生产者追偿；属于经营者责任的，生产者赔偿后有权向经营者追偿。”《消费者权益保护法》第四十三条规定：“消费者在展销会、租赁柜台购买商品或者接受服务，其合法权益受到损害的，可以向销售者或者服务者要求赔偿。展销会结束或者柜台租赁期满后，也可以向展销会的举办者、柜台的出租者要求赔偿。展销会的举办者、柜台的出租者赔偿后，有权向销售者或服务者追偿。”《食品安全法》第五十二条也指出：“集中交易市场的开办者、柜台出租者和展销会举办者，应当依法审查入场食品经营者的许可证，明确其食品安全管理责任，定期对其经营环境和条件进行检查，发现其有违反本法规定行为的，应当及时制止并立即报告所在地县级人民政府食品药品监督管理部门。”牛奶虽然是由他人所售，但超市是柜台的出租者。在柜台租赁期满后，消费者有权向超市要求赔偿。超市承担责任后，可向牛奶销售商进行追偿。故正确答案为C。", "tag": "法律常识"},
{"id": "law-316", "q": "因酒量都比较大，小李和小唐在单位被戏称为“二斤哥”和“酒仙”。某日，他俩戏言说要在酒桌上“一决高下”，于是很多同事跟着看热闹。酒过三巡，两人都有些醉，但没分出胜负，同事小王掏出500 元钱做诱饵，说谁赢归谁，结果小李最后因酒精中毒被送至医院，治疗痊愈共花去医药费6 万元。对此，根据相关法律规定，下列说法正确的是：", "options": ["小李可要求小王赔偿部分医药费", "劝酒人小王应当承担全部赔偿责任", "因小李过错所以应独自承担所有医药费", "小李可向小唐、小王和在场的同事索赔全部医药费"], "a": 0, "e": ".【A】本题考查法律常识。小王掏出500元钱做诱饵进行劝酒行为，使得小李求胜心切饮酒过度，导致酒精中毒，在饮酒过程中有明显的强迫性劝酒行为，主观上存在强迫的过错，此时对于损害后果的发生，劝酒人应当承担相应的过错赔偿责任。醉酒人自身也有一定的过错。因为这种强迫并非是暴力性的，应当减轻劝酒人的赔偿责任。故正确答案为A。", "tag": "法律常识"},
{"id": "law-317", "q": "韩某与几个朋友一起吃饭时都喝了酒，饭后，由于朋友李某喝的比较少就提出开韩某的车送韩某回家。途中与一辆轿车相撞，该事故使对方车辆损坏，对方要求赔偿维修费用4 万元，交管部门认定韩某一方应承担事故的全部责任。对此，根据相关法律规定，下列说法正确的是：", "options": ["李某无偿为韩某提供劳务，因此两人共同承担责任", "在该起交通事故中，韩某对机动车享有事实上和法律上的运行支配权，因此韩某承担全部责任", "李某未从机动车的运行中获利，因此不承担责任", "李某酒后驾驶，属于重大过失，因此承担全部责任"], "a": 3, "e": ".【D】本题考查法律常识。根据《中华人民共和国侵权责任法》第四十九条规定：“因租赁、借用等情形机动车所有人与使用人不是同一人时，发生交通事故后属于该机动车一方责任的，由保险公司在机动车强制保险责任限额范围内予以赔偿。不足部分，由机动车使用人承担赔偿责任；机动车所有人对损害的发生有过错的，承担相应的赔偿责任。”使用人李某驾驶机动车并发生属于该机动车一方责任的交通事故，虽然李某是无偿提供帮助，但因为酒后驾驶存在重大过失，因此应该承担全部责任。故正确答案为D。", "tag": "法律常识"},
{"id": "law-318", "q": "某进攻、郑某防守时，双方发生了肢体碰撞，张某受伤倒地。经医院诊断，张某韧带撕裂。于是张某起诉郑某要求其承担的赔偿责任，支付各项损失共计15 万余元。对此，根据相关法律规定，下列说法正确的是：", "options": ["张某自愿参加踢球，郑某没有故意加害行为，所以损害后果应由张某自担", "张某、郑某以及其他参与踢球者应共同承担赔偿责任", "张某起诉郑某理由充分，合理合法"], "a": 0, "e": ".【A】本题考查法律常识。根据《侵权责任法》第六条规定：“行为人因过错侵害他人民事权益，应当承担侵权责任。根据法律规定推定行为人有危险应当具有充分的认识。张某自愿参加该项体育活动，应视为同意甘冒风险、认可风险自担。除非其他参与者故意加害，参与该项活动而发生的损害后果应由参与者自担。而张某、郑某在张某受伤前存在肢体碰撞，在有强身体对抗的足球运动中是十分常见的，郑某对张某的受伤亦非恶意加害。所以损害后果由张某自行承担。故正确答案为A。", "tag": "法律常识"},
{"id": "law-319", "q": "根据我国商标法相关规定，下列表述正确的是：", "options": ["声音不可以作为商标申请注册", "行政机关可以成为商标权的主体", "注册商标的有效期自核准注册之日起计算", "商标的地理标志主要由该地区的经济因素所决定"], "a": 2, "e": ".【C】本题考查法律常识。A项错误，根据《商标法》第八条规定：“任何能够将自然人、法人或者其他组织的商品与他人的商品区别开的标志，包括文字、图形、字母、数字、三维标志、颜色组合和声音等，以及上述要素的组合，均可以作为商标申请注册。”B项错误，根据《商标法》第四条规定：“自然人、法人或者其他组织在生产经营活动中，对其商品或者服务需要取得商标专用权的，应当向商标局申请商标注册。本法有关商品商标的规定，适用于服务商标。”行政机关不能作为商标权的主体。C项正确，根据《商标法》第三十九条规定：“注册商标的有效期为十年，自核准注册之日起计算。”D项错误，根据《商标法》第十六条规定：“商标中有商品的地理标志，而该商品并非来源于该标志所标示的地区，误导公众的，不予注册并禁止使用；但是，已经善意取得注册的继续有效。前款所称地理标志，是指标示某商品来源于某地区，该商品的特定质量、信誉或者其他特征，主要由该地区的自然因素或者人文因素所决定的标志。”故正确答案为C。", "tag": "法律常识"},
{"id": "law-320", "q": "根据《中华人民共和国民法总则》，以下行为中属于无效民事行为的是：", "options": ["年满10 周岁的周某接受他人赠予的铅笔一支", "年满7 周岁的李某到村头的小商店购买酱油一瓶", "年满9 周岁的赵某到村头的小商店购买饮料一瓶", "年满16 周岁，以自己的劳动收入为主要生活来源的王某到超市购买了彩电一台"], "a": 1, "e": ".【B】本题考查法律常识。《民法总则》第一百四十四条规定：“无民事行为能力人实施的民事法律行为无效。”第一百四十五条第一款规定：“限制民事行为能力人实施的纯获利益的民事法律行为或者与其年龄、智力、精神健康状况相适应的民事法律行为有效；实施的其他民事法律行为经法定代理人同意或者追认后有效。”A项错误，《民法总则》第十九条规定：“八周岁以上的未成年人为限制民事行为能力人，实施民事法律行为由其法定代理人代理或者经其法定代理人同意、追认，但是可以独立实施纯获利益的民事法律行为或者与其年龄、智力相适应的民事法律行为。”年满10周岁的周某属于限制民事行为能力人，接受他人赠予属于纯获利益民事行为，故其民事行为有效。B项正确，《民法总则》第二十条规定：“不满八周岁的未成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。”年满7周岁的李某为无民事行为能力人，其实施的民事法律行为无效。C项错误，年满9周岁的赵某属于限制民事行为能力人，购买饮料属于与其年龄、智力、精神健康状况相适应的民事法律行为，故其民事行为有效。D项错误，《民法总则》第十八条规定：“成年人为完全民事行为能力人，可以独立实施民事法律行为。十六周岁以上的未成年人，以自己的劳动收入为主要生活来源的，视为完全民事行为能力人。”故年满16周岁，以自己的劳动收入为主要生活来源的王某被视为完全民事行为能力人，其买彩电的民事行为有效。故正确答案为B。", "tag": "法律常识"},
{"id": "law-321", "q": "要约，是指希望和他人订立合同的意思表示，下列属于要约的是：", "options": ["某企业在报纸上刊登的商业广告", "某股份有限公司发布的招股说明书", "某商场向居民小区散发的商品价目表", "某单位向经销商发出订购50 台最新配置的某品牌电脑的订货单"], "a": 3, "e": ".【D】本题考查法律常识中《合同法》的相关知识。根据《合同法》第十四条规定：要约是希望和他人订立合同的意思表示，该意思表示应当符合下列规定：（一）内容具体确定；（二）表明接受要约人承诺，要约人即受该意思表示约束。根据《合同法》第十五条的规定：要约邀请是指希望他人向自己发出要约的意思表示。寄送的价目表、拍卖公告、招标公告、招股说明书、商业广告等为要约邀请。据此，A、B、C项均属于要约邀请，D项属于要约。故正确答案为D。", "tag": "法律常识"},
{"id": "law-322", "q": "下列说法中，不正确的是：", "options": ["在2017 年3 月通过的《中华人民共和国民法总则》中，规定了无行为能力人的年龄为10 周岁以下", "《唐六典》第一次以法典形式确定了审判官员的回避制度", "在人民法院审判期间，被告人甲死亡，同时根据已经查明的案件事实和认定的证据材料，已经能够确认甲无罪，最后", "公安机关是行政机关"], "a": 0, "e": ".【A】A项错误：在2017年3月通过的《中华人民共和国民法总则》中，规定了无行为能力人的年龄为8周岁以下。B、C、D三项均表述正确。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-323", "q": "关于民事法律关系，下列说法错误的是：", "options": ["民事法律关系是平等主体之间的关系，一般是根据法律规定设立的", "民事法律关系一经确立，当事人一方即享有民事权利，而另一方便负有相应的民事义务", "民事法律关系的保障措施具有补偿性和财产性", "民事法律关系可分为财产法律关系和人身法律关系"], "a": 0, "e": ".【A】A项错误：民事法律关系是平等主体之间的关系，一般是自愿设立的。只要当事人依其意思实施的行为不违反法律规定，所设立的法律关系就受法律保护。B项正确：民事法律关系主体是指参与民事法律关系、享受民事权利和负担民事义务的人。民事法律关系一经确立，当事人一方即享有民事权利，而另一方便负有相应的民事义务。C项正确：民事法律关系的保障措施具有补偿性和财产性。民法调整对象的平等性和财产性也表现在民事法律关系的保障手段上，即民事责任以财产补偿为主要内容，惩罚性和非财产性责任不是主要的民事责任形式。D项正确：民事法律关系可分为财产法律关系和人身法律关系。财产法律关系是指直接与财产有关的具有财产内容的民事法律关系。人身关系是指与主体不可分离的，不直接具有财产内容的民事法律关系。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-324", "q": "甲将自有房屋出售给乙，乙将双方约定的房款支付给甲，将房子交给儿子丙使用。后由于价格变动，甲又将房子出售给丁，并办理了房屋过户手续，此时，该房屋的所有权归属：", "options": ["甲", "乙", "丙", "丁"], "a": 3, "e": ".【D】根据我国《物权法》第九条规定：“不动产物权设立、变更、转让和消灭，应当登记；未经登记，不发生物权效力，但法律另有规定的除外。”根据题目得知，甲与乙并未登记，没有法律效力，不动产登记在丁的名下，故所有权归丁所有。故正确答案为D。", "tag": "法律常识"},
{"id": "law-325", "q": "下列处理保险合同纠纷案件的说法，符合我国相关法律法规的是：", "options": ["陈女士购买了一份意外伤害保险，她收到的投保单与保险单不一致，应以保险单为准", "王先生所在的单位为他购买了一份车辆盗损险，他的保险凭证记载的时间不同，以形成时间在前的为准", "张先生购买了一份财产损失保险，该保险单的非格式条款和格式条款不一致，以格式条款为准", "李女士购买了一份重大疾病保险，保险单存有手写和打印两种方式，以双方签字、盖章的手写部分的内容为准"], "a": 3, "e": ".【D】本题考查法律常识。主要涉及保险法的相关内容。最高人民法院关于适用《中华人民共和国保险法》若干问题的解释（二）中第十四条规定：保险合同中记载的内容不一致的，按照下列规则认定：（一）投保单与保险单或者其他保险凭证不一致的，以投保单为准。但不一致的情形系经保险人说明并经投保人同意的，以投保人签收的保险单或者其他保险凭证载明的内容为准；（二）非格式条款与格式条款不一致的，以非格式条款为准；（三）保险凭证记载的时间不同的，以形成时间在后的为准；（四）保险凭证存在手写和打印两种方式的，以双方签字、盖章的手写部分的内容为准。A项错误，应以投保单为准。B项错误，应以形成时间在后的为准。C项错误，应以非格式条款为准。D项正确，符合第四种情形。若保险凭证存在手写和打印两种方式的话，应以双方签字、盖章的手写部分的内容为准。故正确答案为D。", "tag": "法律常识"},
{"id": "law-326", "q": "甲长期下落不明，经其配偶乙向法院申请，法院判决宣告甲死亡。其后，乙就与丁结婚，并将一6 岁的儿子送给丙收养，双方办理了收养手续。实际上甲并未死亡。经甲请求法院撤销了对其死亡的宣告。甲回家后发现儿子被人收养，乙也改嫁他人，幸丁已死亡。因此，甲就要求与乙恢复婚姻关系，并以自己未同意将儿子送丙收养主张收养无效。关于甲可否与乙自动恢复婚姻关系及甲的儿子与丙间的收养关系是否无效，下列正确的是：", "options": ["不能自动恢复婚姻关系、收养关系有效", "能自动恢复婚姻关系、收养关系无效", "能自动恢复婚姻关系、收养关系有效", "不能自动恢复婚姻关系、收养关系无效"], "a": 0, "e": ".【A】本题考查法律常识。根据《民法总则》第五十一条规定：“被宣告死亡的人的婚姻关系，自死亡宣告之日起消灭。死亡宣告被撤销的，婚姻关系自撤销死亡宣告之日起自行恢复，但是其配偶再婚或者向婚姻登记机关书面声明不愿意恢复的除外。”乙已经再婚，故甲和乙不能自动恢复婚姻关系。根据《民法总则》第五十二条规定：“被宣告死亡的人在被宣告死亡期间，其子女被他人依法收养的，在死亡宣告被撤销后，不得以未经本人同意为由主张收养关系无效。”故甲的儿子和丙收养关系有效。故正确答案为A。", "tag": "法律常识"},
{"id": "law-327", "q": "春节期间，小李出国旅游，与旅行社签订了旅游合同。在前往其中一个景点之前，旅行社通知小李当地突发泥石流，道路无法通过，并以此为由取消了行程中的该景点。为此，该旅行社（）。", "options": ["承担赔偿责任，需向小李退还所有费用", "承担赔偿责任，需向小李退还部分费用", "不承担赔偿责任，无需向小李退还任何费用", "不承担赔偿责任，但需向小李退还部分费用"], "a": 3, "e": ".【D】本题考查了民法中合同法的知识点。根据《合同法》第一百一十七条规定：“因不可抗力不能履行合同的，根据不可抗力的影响，部分或者全部免除责任，但法律另有规定的除外。当事人迟延履行后发生不可抗力的，不能免除责任。本法所称不可抗力，是指不能预见、不能避免并不能克服的客观情况。”题干中“突发泥石流”属于不可抗力的情况，故旅行社无需承担赔偿责任，但因为小李没有到预定景点游玩，故旅行社应当退还去该景点的费用。故正确答案为D。", "tag": "法律常识"},
{"id": "law-328", "q": "张家欲购买刘家的老宅，刘家一直没有同意，后张家见刘家人老势弱，迫使刘家在自己起草的房屋买卖协议上签了字。张家的行为主要违背了下列哪项民法原则？", "options": ["自愿原则", "平等原则", "公平原则", "诚信原则"], "a": 0, "e": ".【A】A项正确：自愿原则，就是在民事活动中当事人的意思自治，即当事人可以根据自己的判断去从事民事活动。本案中刘家一直未同意卖房，张家迫使刘家违背本意的情况下签订了房屋买卖协议，违背了自愿原则。B项错误：平等原则，是指主体的身份平等，是指不论其自然条件和社会处境如何，其法律资格亦即权利能力一律平等。本案中刘家和张家的法律地位是平等的，因此张家未违背民法的平等原则。C项错误：公平原则是指在民事活动中以利益均衡作为价值判断标准，在民事主体之间发生利益关系摩擦时，以权利和义务是否均衡来平衡双方的利益。本案中刘家与张家签订了卖房协议，并未谈到刘家迫使张家低于市场价格出售，未显失公平。D项错误：诚信原则是指民事主体进行民事活动必须意图诚实、善意、行使权利不侵害他人与社会的利益，履行义务信守承诺和法律规定，最终达到所有获取民事利益的活动。本案中刘家并未出现欺骗等不诚信的行为，他只是迫使张家卖房。故正确答案为A。", "tag": "法律常识"},
{"id": "law-329", "q": "根据《中华人民共和国物权法》，下列属于不动产的是：", "options": ["邮轮", "私人飞机", "个人住宅", "房车"], "a": 2, "e": ".【C】C项正确：在司法实践中，不动产和动产是根据物能否移动和移动后是否会损害物的价值为标准进行划分的。不动产指依自然性质或法律规定不可移动的物，如土地、房屋等；动产是指能够移动并且不因移动损害其价值的物，不动产以外的物可解释为动产。《担保法》第九十二条规定：“不动产是指土地以及房屋、林木等地上定着物。动产是指不动产以外的物。”四个选项中，C项“个人住宅”属于不动产，A、B、D项均属于动产。故正确答案为C", "tag": "法律常识"},
{"id": "law-330", "q": "甲某委托乙某为代理人购买一批货物，乙某的下列行为违反法律规定的是：", "options": ["乙某及时将购买货物的过程报告给甲某", "乙某以高于市场价的价格从某亲友处购入货物", "乙某因个人原因不能履行委托之职，并通知了甲某", "乙某经甲某同意，另行委托丙某办理货物购买事宜"], "a": 1, "e": ".【B】本题考查民法知识。A项正确，基于代理人尽勤勉、谨慎义务的原则，代理人应当将代理事务如实报告给被代理人。B项错误，《中华人民共和国民法总则》第一百六十四条第二款规定：“代理人和相对人恶意串通，损害被代理人合法权益的，代理人和相对人应当承担连带责任。”乙某以高于市场价从亲友处购入货物，属于恶意串通损害被代理人合法权益，乙某的行为违反法律规定。C项正确，基于代理人尽勤勉、谨慎义务的原则，代理人不能履行委托事务，则应通知被代理人。D项正确，《中华人民共和国民法总则》第一百六十九条第一款规定：“代理人需要转委托第三人代理的，应当取得被代理人的同意或者追认。”题干中乙某转委托丙某，事先经被代理人甲某同意的做法符合法律规定。本题为选非题，故正确答案为B。", "tag": "法律常识"},
{"id": "law-331", "q": "歌手甲和乙一起参加某歌唱比赛，为在比赛中获胜，甲在网上公开宣称乙生活作风有问题，且在比赛场下不尊重其他参赛歌手。该言论一出就引起了媒体热议，乙因此受到了众多网民的辱骂，退出了歌唱比赛，也失去了许多广告代言机会，经济受到巨额损失。那么，甲的行为侵害了乙的（）。", "options": ["财产权", "名誉权", "荣誉权", "隐私权"], "a": 1, "e": ".【B】A选项财产权包括物权和债权两大类，题中没有侵犯财产权，排除A选项；题中甲妄自在网上发布对乙不利的言论，侵害了对方的名誉权，B选项正确；C选项荣誉权，是指公民、法人所享有的，因自己的突出贡献或特殊劳动成果而获得的光荣称号或其他荣誉的权利，题中没有侵犯荣誉权，排除C选项；D选项隐私权是指自然人享有的私人生活安宁与私人信息秘密依法受到保护，不被他人非法侵扰、知悉、收集、利用和公开的一种人格权，题中没有涉及到，排除D选项。故正确答案为B。", "tag": "法律常识"},
{"id": "law-332", "q": "一年半之前孙某病危时曾当着2 个儿子和4 位医护人员的面说：“我死后家里的一切财产都留给老大”，后经抢救治疗，孙某病愈出院。一年半以后，孙某旧病复发死亡。孙某大儿子把孙某的全部遗产据为己有，理由是一年半前孙某病危时立了口头遗嘱。孙某的口头遗嘱（）。", "options": ["有效", "无效", "由大儿子告知其他亲属后有效", "经医护人员证明后有效"], "a": 1, "e": ".【B】根据《继承法》第17条第5款规定，遗嘱人在危急情况下，可以立口头遗嘱。口头遗嘱应当有两个以上见证人在场见证。危急情况解除后，遗嘱人能够用书面或者录音形式立遗嘱的，所立的口头遗嘱无效。故正确答案为B。", "tag": "法律常识"},
{"id": "law-333", "q": "甲、乙、丙三人合伙开一饭店，店名为“客来香”，依法登记。甲全权负责饭店对外事务。顾客丁来店中用餐时，被服务员戊不小心烫伤。丁欲向法院起诉，则：", "options": ["被告应为“客来香”饭店", "甲、乙、丙为共同被告，并注明“客来香”字号", "被告应为甲", "甲和戊为共同被告"], "a": 1, "e": ".【B】《最高人民法院关于适用〈中华人民共和国民事诉讼法〉的解释》（2015年2月4日起实施）第六十条规定：“在诉讼中，未依法登记领取营业执照的个人合伙的全体合伙人为共同诉讼人。个人合伙有依法核准登记的字号的，应在法律文书中注明登记的字号。全体合伙人可以推选代表人；被推选的代表人，应由全体合伙人出具推选书。”本题中，甲、乙、丙合伙开办的饭店有依法登记，因此丁向法院起诉，全体合伙人甲、乙、丙为共同被告，同时注明登记字号“客来香”。故正确答案为B。", "tag": "法律常识"},
{"id": "law-334", "q": "下列情形符合法律规定的是：", "options": ["甲、乙二人自由恋爱，因两人均年满20 周岁，经双方父母同意，两人可以结婚", "丙12 岁，玩火酿成火灾造成重大财产损失，但丙不承担失火罪的刑事责任", "丁6 岁，春节收到红包若干，其母认为丁尚年幼，红包里的钱应归监护人所有", "19 岁的大学生戊，认为父母有义务支付他的教育费及生活费至其独立工作为止"], "a": 1, "e": ".【B】A项错误，根据《婚姻法》第六条规定，结婚年龄，男不得早于二十二周岁，女不得早于二十周岁。晚婚晚育应予鼓励。该项中男方未达法定婚龄，故不可以结婚。B项正确，根据《刑法》第十七条规定，已满十六周岁的人犯罪，应当负刑事责任。已满十四周岁不满十六周岁的人，犯故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投毒罪的，应当负刑事责任。已满十四周岁不满十八周岁的人犯罪，应当从轻或者减轻处罚。因不满十六周岁不予刑事处罚的，责令他的家长或者监护人加以管教；在必要的时候，也可以由政府收容教养。丙未满14周岁，因此不追究刑事责任。C项错误，根据《民法总则》第三十五条规定：“监护人应当按照最有利于被监护人的原则履行监护职责。监护人除为维护被监护人利益外，不得处分被监护人的财产。”孩子对压岁钱享有所有权，压岁钱是孩子的个人财产。父母对孩子的财产具有保管义务，除非为维护孩子的利益外，不得处分孩子的财产。故监护人不得将被监护人的财产据为己有。D项错误，根据《婚姻法》第二十一条第二款规定，父母不履行抚养义务时，未成年的或不能独立生活的子女，有要求父母付给抚养费的权利。根据《婚姻法解释（一）》第二十条规定，婚姻法第二十一条规定的“不能独立生活的子女”，是指尚在校接受高中及其以下学历教育，或者丧失或未完全丧失劳动能力等非因主观原因而无法维持正常生活的成年子女。该项中19岁的大学生戊不符合“未成年”和“不能独立生活的子女”的条件。故其父母没有义务支付他的教育费及生活费至其独立工作为止。故正确答案为B。", "tag": "法律常识"},
{"id": "law-335", "q": "某重点高校20 岁的大二学生王晓，起诉要求父亲王军支付大学期间的教育费和生活费，但王军因收入有限拒绝支付。对此，下列观点正确的是：", "options": ["甲认为王晓仍为在校生，王军有义务支付其在校期间的教育费和生活费", "乙认为王晓虽已成年，但无独立生活来源，王军仍有支付的义务", "丙认为王晓已成年，王军没有义务继续支付王晓教育和生活费用", "丁认为王军在能力所及的范围内有义务支付王晓教育费和生活费"], "a": 2, "e": ".【C】根据《婚姻法》第二十一条第二款规定，父母不履行抚养义务时，未成年的或不能独立生活的子女，有要求父母付给抚养费的权利。根据《婚姻法解释（一）》第二十条规定，婚姻法第二十一条规定的“不能独立生活的子女”，是指尚在校接受高中及其以下学历教育，或者丧失或未完全丧失劳动能力等非因主观原因而无法维持正常生活的成年子女。该题中20岁的大二学生王晓不符合“未成年”和“不能独立生活的子女”的条件。故其父亲王军没有义务继续支付王晓教育和生活费用。故正确答案为C。", "tag": "法律常识"},
{"id": "law-336", "q": "根据《中华人民共和国物权法》的规定，下列不属于国家所有的是（）。", "options": ["农村宅基地", "国家建设征用的土地", "河流", "矿藏"], "a": 0, "e": ".【A】《中华人民共和国物权法》第四十六条规定：“矿藏、水流、海域属于国家所有。”因此，C、D两项排除。《中华人民共和国物权法》第一百三十五条规定：“建设用地使用权人依法对国家所有的土地享有占有、使用和收益的权利，有权利用该土地建造建筑物、构筑物及其附属设施。”因此，建设用地属于国家所有，B项排除。《中华人民共和国物权法》第一百五十二条规定：“宅基地使用权人依法对集体所有的土地享有占有和使用的权利，有权依法利用该土地建造住宅及其附属设施。”因此，宅基地属于集体所有，而不属于国家所有，A项当选。本题为选非题，故正确答案为A。", "tag": "法律常识"},
{"id": "law-337", "q": "通常所说的“五险一金”，包括养老保险、医疗保险、失业保险、工伤保险、生育保险和住房公积金。其内容可能因不同地区、不同工作条件和不同的工作内容而有所不同。但除（）之外，其他的几项都是国家法定的，必须包含在劳动合同中。", "options": ["养老保险和失业保险", "医疗保险", "住房公积金", "工伤保险和生育保险"], "a": 2, "e": ".【C】《中华人民共和国社会保险法》第二条规定：“国家建立基本养老保险、基本医疗保险、工伤保险、失业保险、生育保险等社会保险制度，保障公民在年老、疾病、工伤、失业、生育等情况下依法从国家和社会获得物质帮助的权利。”《中华人民共和国劳动合同法》第十七条规定：“劳动合同应当具备以下条款：（一）用人单位的名称、住所和法定代表人或者主要负责人；（二）劳动者的姓名、住址和居民身份证或者其他有效身份证件号码；（三）劳动合同期限；（四）工作内容和工作地点；（五）工作时间和休息休假；（六）劳动报酬；（七）社会保险；（八）劳动保护、劳动条件和职业危害防护；（九）法律、法规规定应当纳入劳动合同的其他事项。”故A、B、D三项排除。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-338", "q": "甲向乙购买了一只羊，钱已付，因天黑路滑，甲决定明天再来牵羊，乙将甲所买的羊与自己的羊一起拴在门口树下，当晚雷雨交加，将甲所买的羊与乙的羊一起击死，此事件中乙是否需要赔偿甲？下列说法正确的是（）。", "options": ["乙有过错，乙应该承担全部赔偿责任", "乙有小部分过错，乙要承担小部分赔偿责任", "乙有大部分过错，乙要承担大部分赔偿责任", "乙没有任何过错，乙不用承担任何赔偿责任"], "a": 3, "e": ".【D】本题中，甲、乙的买卖合同已经成立并且生效，从题干信息可知，甲已经付款，是因为天黑路滑没有牵羊，所以应视为交付完成。此后，甲、乙之间成立了保管合同关系。我国《合同法》第三百七十四条规定：“保管期间，因保管人保管不善造成保管物毁损、灭失的，保管人应当承担损害赔偿责任，但保管是无偿的，保管人证明自己没有重大过失的，不承担损害赔偿责任。”本题中乙将甲所买的羊与自己的羊一起拴在门口树下，当晚雷雨交加，导致羊被击死，所以乙没有过错，故不承担赔偿责任。故正确答案为D。", "tag": "法律常识"},
{"id": "law-339", "q": "甲因与乙发生互殴，受伤入院治疗。两周后，甲即将痊愈出院，但在最后一次换药时，因主治医生丙操作医疗器具失误，甲伤口被感染而需继续留院治疗。第二天，医院病房因电线老化短路而引发火灾，甲不幸在火灾中遇难。按照法律，谁应对甲的死亡承担法律责任（）", "options": ["乙", "丙", "医院", "乙、丙和医院共同"], "a": 2, "e": ".【C】构成民事责任的要件为：1.损害事实的客观存在。损害是指因一定的行为或事件使民事主体的权利遭受某种不利的影响。2.行为的违法性。指对法律禁止性或命令性规定的违反。3.违法行为与损害事实之间的因果关系。作为构成民事责任要件的因果关系指行为人的行为及其物件与损害事实之间所存在的前因后果的必然联系。4.行为人的过错。行为人的过错是行为人在实施违法行为时所具备的心理状态，是构成民事责任的主观要件。本题中，造成甲死亡的主要因素为医院病房因电线老化短路而引发火灾，主治医生丙的失误对甲的死亡不构成直接因素。所以医院应对甲的死亡承担法律责任。故正确答案为C。", "tag": "法律常识"},
{"id": "law-340", "q": "根据民事诉讼法的规定，下列说法错误的是：", "options": ["人民法院调解和好的离婚案件，可以不制作调解书", "修改后的民事诉讼法增加了“公益诉讼”的内容", "人民法院可以根据实际情况，决定采取传真的方式送达判决书", "修改后的民事诉讼法规定，当事人所在社区可推荐公民作为诉讼代理"], "a": 2, "e": ".【C】A项正确，我国《民事诉讼法》第九十条和最高人民法院《关于人民法院民事调解工作若干问题的规定》第十三条的规定，调解和好的离婚案件，人民法院可以不制作调解书；B项正确，十一届全国人大常委会第二十八次会议表决通过了全国人大常委会关于修改《民事诉讼法》的决定，修改后的民诉法自2013年1月1日起实施。修改后的民事诉讼法增加了“公益诉讼”的内容；C项错误，电子送达经受送达人同意，法院可以采用传真、电子邮件等能够确认其收悉的方式送达诉讼文书，但是，判决书、裁定书、调解书除外。传真、电子邮件等到达受送达人特定系统日期为送达日期；D项正确，修改后的《民事诉讼法》第五十八条第三款规定当事人所在社区推荐的公民可以被委托为诉讼代理人。本题为选非题，故正确答案为C。", "tag": "法律常识"},
{"id": "law-341", "q": "我国《民法通则》规定，公民具有民事权利能力的年龄时限为：", "options": ["从出生时起到18 岁时止", "从14 岁时起到死亡时止", "从18 岁时起到死亡时止", "从出生时起到死亡时止"], "a": 3, "e": ".【D】根据我国《民法通则》的规定，公民的民事权利能力始于出生，终于死亡。故正确答案为D。", "tag": "法律常识"},
{"id": "law-342", "q": "王某在大街上遛狗。张某故意挑逗狗，之后跑掉，结果狗将路过的孙某咬伤，并继续追赶孙某。王某为阻止狗继续伤人，在狗不听使唤的情况下，用木棍将狗的腿打断。对此，下列表述正确的是：", "options": ["孙某可以向张某或王某要求赔偿", "孙某只能向王某要求赔偿", "孙某要求王某承担赔偿责任，必须证明王某存在过错", "王某不能要求张某赔偿狗受伤的损失"], "a": 0, "e": ".【A】我国《侵权责任法》第八十三条规定：“因第三人的过错致使动物造成他人损害的，被侵权人可以向动物饲养人或者管理人请求赔偿，也可以向第三人请求赔偿。动物饲养人或者管理人赔偿后，有权向第三人追偿”。故孙某既可以向张某也可以向王某要求赔偿，A正确，B错误。此外，个人饲养动物致人损害，适用无过错责任原则，孙某无需证明王某存在过错，C错误。王某赔偿后可以向张某追偿，D错误。故正确答案为A。", "tag": "法律常识"},
{"id": "law-343", "q": "根据相关法律法规，下列各类经济组织，无需对自身债务承担无限责任的是：", "options": ["甲、乙、丙三人合伙开办的律师事务所", "小丽在服装市场租下店铺注册成立的服装个体工商户", "Z 是国有独资钢铁制造公司", "小王个人注册登记的从事电子贸易的独资企业"], "a": 2, "e": ".【C】A项错误，根据《合伙企业法》第二条第二三款规定：“普通合伙企业由普通合伙人组成，合伙人对合伙企业债务承担无限连带责任。本法对普通合伙人承担责任的形式有特别规定的，从其规定。有限合伙企业由普通合伙人和有限合伙人组成，普通合伙人对合伙企业债务承担无限连带责任，有限合伙人以其认缴的出资额为限对合伙企业债务承担责任。”B项错误，根据《民法总则》第五十六条规定，个体工商户的债务，个人经营的，以个人财产承担；家庭经营的，以家庭财产承担；无法区分的，以家庭财产承担。C项正确，国有独资公司是指国家单独出资、由国务院或者地方人民政府授权本级人民政府国有资产监督管理机构履行出资人职责的有限责任公司。国有独资公司符合有限责任公司的一般特征：股东以其出资额为限对公司承担责任，公司以其全部法人财产对公司的债务承担责任。故正确答案为C。", "tag": "法律常识"},
{"id": "law-344", "q": "下列对有关法律的解释，正确的是：", "options": ["人民法院不可以在当事人不在场或者不知情的情况下缺席判决离婚", "有配偶的人又与他人以夫妻的名义同居生活，形成事实有效婚姻", "我国法律规定，对婚姻关系解除的判决不能申请再审", "对于父母无力赡养的祖父母，有负担能力的孙子女没有赡养义务"], "a": 2, "e": ".【C】A项错误，根据最高人民法院关于适用《中华人民共和国民事诉讼法》若干问题的意见规定，无民事行为能力的当事人的法定代理人，经传票传唤无正当理由拒不到庭的，如属原告方，可以比照民事诉讼法第一百二十九条的规定，按撤诉处理；如属被告方，可以比照民事诉讼法第一百三十条的规定，缺席判决；B项错误，此行为构成重婚；C项正确，我国《民事诉讼法》第202条规定，当事人对已经发生法律效力的解除婚姻关系的判决、调解书，不得申请再审；D项错误，我国《婚姻法》第28条规定：“有负担能力的孙子女、外孙子女对于子女已经死亡或者子女无力赡养的祖父母、外祖父母，有赡养义务。”故正确答案为C。", "tag": "法律常识"},
{"id": "law-345", "q": "甲、乙结婚后，乙的父母于2011 年11 月1 日出资300 万为甲、乙购买了房屋，房屋产权登记在乙的名下，由于甲外出打工，乙长期在娘家居住，经夫妻协商将房屋出租。2012 年4 月20 日，因甲在外出打工期间与他人同居，乙提起诉讼离婚，法院判决甲与乙离婚。下列说法不正确的是：", "options": ["该房屋认定为乙的个人财产", "该房屋应视为乙的父母只对乙的赠与", "房屋租金属于夫妻共同财产", "应当将房屋视为夫妻共同财产并依法分割"], "a": 3, "e": ".【D】A、B项正确，D项错误。最高人民法院关于适用《中华人民共和国婚姻法》若干问题的解释（三）的规定，第七条第一款规定，婚后由一方父母出资为子女购买的不动产，产权登记在出资人子女名下的，可按照婚姻法第十八条第（三）项的规定，视为只对自己子女一方的赠与，该不动产应认定为夫妻一方的个人财产，即乙的财产，当选。C项正确，根据《最高人民法院关于适用﹤中华人民共和国婚姻法﹥若干问题的解释（三）》第五条的规定，夫妻一方个人财产在婚后产生的收益，除孳息和自然增值外，应认定为夫妻共同财产。又因最高人民法院民一庭意见——个人所有房屋的婚后收益认定及其处理中表明：一方个人所有的房屋婚后用于出租，其租金收入属于经营性收入，应认定为夫妻共同财产，排除。本题为选非题，故正确答案为D。", "tag": "法律常识"},
{"id": "law-346", "q": "某甲共育有三儿一女，2000 年甲在公证机关公证下立a 遗嘱将其财产给予其小儿子所有，后因与小儿子关系恶化，甲又自书b 遗嘱决定将财产给予二儿子所有。根据我国《继承法》的相关规定，下列表述正确的是：", "options": ["a 遗嘱因经公证而效力优先，故应以a 遗嘱为准", "b 遗嘱为后立遗嘱，故应以b 遗嘱为准", "", "b 遗嘱均因侵犯其他继承人的合法权利而无效", "", "b 遗嘱均因可能侵犯其他继承人的合法权利而效力待定"], "a": 0, "e": ".【A】《最高人民法院关于贯彻执行<中华人民共和国继承法>若干问题的意见》第42条规定：“遗嘱人以不同形式立有数份内容相抵触的遗嘱，其中有公证遗嘱的，以最后所立公证遗嘱为准；没有公证遗嘱的，以最后所立的遗嘱为准”。本题中，a遗嘱是公证遗嘱，因此应当以a遗嘱为准。故正确答案为A。", "tag": "法律常识"},
{"id": "law-347", "q": "李俊在某服装店挑选衣服，店主向其推荐了一款风衣。李俊试穿后觉得不合适，脱下风衣后准备离开，店主却强追李俊买下了这件风衣。店主的这一行为侵犯了李俊的：", "options": ["财产安全权", "损害求偿权", "维护尊严权", "选择商品自主权"], "a": 3, "e": ".【D】《消费者权益保护法》第九条规定，消费者享有自主选择商品或者服务的权利。消费者有权自主选择提供商品或者服务的经营者，自主选择商品品种或者服务方式，自主决定购买或者不购买任何一种商品、接受或者不接受任何一项服务。店主强追李俊买下风衣的行为，侵犯了李俊自主选择商品的权利。故正确答案为D。", "tag": "法律常识"},
{"id": "law-348", "q": "某首饰店误将一枚银戒指当作铂金戒指卖给李某。首饰店的这一行为属于：", "options": ["犯罪行为", "无效的民事法律行为", "可撤销的民事法律行为", "有效的民事法律行为"], "a": 2, "e": ".【C】我国《民法总则》第一百四十七条规定：“基于重大误解实施的民事法律行为，行为人有权请求人民法院或者仲裁机构予以撤销”。首饰店误将银戒指当作铂金，对行为内容存在重大误解，属于可撤销的民事法律行为。故正确答案为C。", "tag": "法律常识"},
{"id": "law-349", "q": "张某有一株珍稀兰花，后不慎遗失。李某无意中捡到后，带回家自行种养。李某的朋友关某在其家中见到此兰花，十分喜爱，李某便送给了他。后来张某发现后向关某索取。对此，以下说法正确的是：", "options": ["兰花属于遗失物，张某有权索回", "兰花属于无主物，所有权属于李某", "兰花已被李某赠与关某，故所有权属于关某", "兰花虽然已赠与关某，但所有权仍属于李某"], "a": 0, "e": ".【A】《物权法》第106条规定：“无处分权人将不动产或者动产转让给受让人的，所有权人有权追回。”本题中不存在善意第三人取得所有权的情形，因为善意取得的成立要件之一是“有偿转让”，而本题中的情况是“无偿赠与”，因此张某有权向关某索回。故正确答案为A。", "tag": "法律常识"},
{"id": "law-350", "q": "下列选项中不属于我国著作权法所保护的作品是：", "options": ["法院的判决书", "没有剧本的小品表演", "建筑施工图纸", "用C++语言编写的计算机程序"], "a": 0, "e": ".【A】根据我国《著作权法》规定，法院判决书属于国家机关司法性质的文件，属于公有领域文件，著作权法不予保护。没有剧本的小品表演、施工图纸和计算机程序都属于著作权保护的范畴。故正确答案为A。", "tag": "法律常识"},
{"id": "law-351", "q": "某小区召开业主大会，会上物业管理处马主任现场解答业主的提问，其中符合法律规定的是：", "options": ["未经业主委员会同意，顶楼业主不得私自封闭屋顶天台", "经物业管理处同意，业主可在自家临街外墙设置广告牌", "未经业主委员会同意，开发商无权出售架空层内的车库", "经工商行政管理部门许可，业主可将自家住宅改为商店"], "a": 0, "e": ".【A】本题考查法律常识。A项正确，根据《最高人民法院关于审理建筑物区分所有权纠纷案件具体应用法律若干问题的解释》第三条规定，屋顶天台属于该楼全体业主共有，改变共有部分的用途应当由业主共同决定，所以顶楼业主无权私自封闭屋顶天台；B项错误，根据《最高人民法院关于审理建筑物区分所有权纠纷案件具体应用法律若干问题的解释》第三条规定，建筑物的外墙属于业主共有，利用共有部分从事经营性活动应当由业主共同决定；C项错误，架空层是建筑用词，指建筑物中只有结构支撑，没有四周围护的建筑空间。架空层属于建筑区划的一部分。根据《物权法》第七十四条第二款的规定，“建筑区划内，规划用于停放汽车的车位、车库的归属，由当事人通过出售、附赠或者出租等方式约定”，开发商有权对这部分车位进行处理，无需经业主委员会同意；D项错误，《物权法》第七十七条规定，“业主不得违反法律、法规以及管理规约，将住宅改变为经营性用房。业主将住宅改变为经营性用房的，除遵守法律、法规以及管理规约外，应当经有利害关系的业主同意”。故正确答案为A。", "tag": "法律常识"},
{"id": "law-352", "q": "下列请求应依法予以支持的是：", "options": ["某男擅自按市价出售双方共有住房，其妻要求追回", "某女起诉请求离婚，要求分割其丈夫的工伤补助金", "按父母遗嘱某女继承全部家产，其兄要求平分家产", "某夫妻已育有一个健康男孩，现申请收养一名孤儿"], "a": 3, "e": ".【D】《物权法》第一百零六条规定：“无处分权人将不动产或者动产转让给受让人的，所有权人有权追回；除法律另有规定外，符合下列情形的，受让人取得该不动产或者动产的所有权：（一）受让人受让该不动产或者动产时是善意的；（二）以合理的价格转让；（三）转让的不动产或者动产依照法律规定应当登记的已经登记，不需要登记的已经交付给受让人。受让人依照前款规定取得不动产或者动产的所有权的，原所有权人有权向无处分权人请求赔偿损失。”根据题目的表述从擅自出售和按市价两个关键词得出符合善意取得的特征，这就意味着其妻子丧失了所有权，但是可以向其丈夫追偿。A项错误。根据《婚姻法》第十八条第二项，因身体受到伤害获得的医疗费、残疾人生活补助费等费用属于夫妻一方的财产。由于离婚时财产的分配只涉及夫妻共同财产，工伤补助金是丈夫的个人财产，妻子无权要求分配。B项错误。根据我国《继承法》的规定，继承开始后有遗嘱的，按照遗嘱继承办理，所以C项中应依照合法遗嘱进行继承，不支持平分家产的要求。根据《收养法》第八条规定，收养人只能收养一名子女；收养孤儿、残疾儿童或者社会福利机构抚养的查找不到生父母的弃婴和儿童，可以不受收养人无子女和收养一名的限制。D项这对夫妻虽然有一名健康的男孩，由于收养对象是孤儿，不受已有子女不能收养以及仅收养一名的限制。故正确答案为D。", "tag": "法律常识"},
{"id": "law-353", "q": "下列有关知识产权的说法符合法律规定的是：", "options": ["国家版权局是著作权集体管理组织", "注册商标有效期满前未申请续展注册的，应在有效期满后被注销", "发明和实用新型属于专利权，而外观设计属于版权的范畴", "原则上县级以上行政区划的地名和公众知晓的外国地名不得作为商标"], "a": 3, "e": ".【D】《商标法》第10条规定：“县级以上行政区划的地名或者公众知晓的外国地名，不得作为商标。但是，地名具有其他含义或者作为集体商标、证明商标组成部分的除外；已经注册的使用地名的商标继续有效。”因此，原则上县级以上行政区划的地名和公众知晓的外国地名不得作为商标。故正确答案为D。", "tag": "法律常识"},
{"id": "law-354", "q": "关于知识产权，下列说法正确的是：", "options": ["知识产权为权利人所有，不能随意转让", "知识产权只是在特定的国家领域内发生法律效力", "知识产权如无设定期限，则永久有效", "企业的注册商标不属于知识产权"], "a": 1, "e": ".【B】知识产权，指“权利人对其所创作的智力劳动成果所享有的专有权利”，知识产权具有专有性的特点，即独占性或垄断性，除权利人同意或法律规定外，权利人以外的任何人不得享有或使用该权利。A项错误，知识产权主体分为：知识产权出让主体与知识产权受让主体，根据与知识产权转让有关的法律法规和双方签定的转让合同，可以将知识产权权利进行出让；B项正确，知识产权具有地域性；C项错误，知识产权具有时间性，即法律对各项权利的保护，都规定有一定的有效期；D项错误，知识产权主要包括著作权、专利权、商标权等。故正确答案为B。", "tag": "法律常识"},
{"id": "law-355", "q": "张某有甲、乙、丙三子，张某去世后，没有留下遗嘱。在其遗产处理前，甲明确表示放弃继承，乙明确表示要继承，丙没有作出放弃或接受的继承表示，那么丙的行为视为：", "options": ["放弃继承", "接受继承", "丧失继承权", "转继承"], "a": 1, "e": ".【B】根据《继承法》第25条的规定：“继承开始后，继承人放弃继承的，应当在遗产处理前，做出放弃继承的表示。没有表示的，视为接受继承。受遗赠人应当在知道受遗赠后两个月内，做出接受或者放弃受遗赠的表示。到期没有表示的，视为放弃受遗赠。”本题丙作为继承人没有表示视为接受继承。故正确答案为B。", "tag": "法律常识"},
{"id": "law-356", "q": "丁某与村委会签约承包本村一鱼塘，后丁某搬到镇上居住，遂拟将鱼塘转包给本村经营另一鱼塘的赵某。下列说法正确的是：", "options": ["鱼塘转包应经过村委会同意", "丁某拖欠村委会5 万元，村委会有权收回鱼塘抵顶欠款", "如转包费高于丁某向村委会交纳的承包金，则超出部分由村委会享有", "如因鱼塘承包经营发生纠纷，丁某既可向农村土地承包仲裁机构申请仲裁，也可直接向法院起诉"], "a": 3, "e": ".【D】根据《农村土地承包法》的规定，“承包期内，承包方全家迁入小城镇落户的，应当按照承包方的意愿，保留其土地承包经营权或者允许其依法进行土地承包经营权流转”。A选项错误，“采取转让方式流转的，应当经发包方同意；采取转包、出租、互换或者其他方式流转的，应当报发包方备案”，所以，鱼塘转包只需报村委会备案，不须经村委会同意；B选项错误，“承包期内，发包方不得单方面解除承包合同，……不得将承包地收回抵顶欠款”；C选项错误，“土地承包经营权流转的转包费、租金、转让费等，应当由当事人双方协商确定。流转的收益归承包方所有，任何组织和个人不得擅自截留、扣缴”；D选项正确，“因土地承包经营发生纠纷的，可以向农村土地承包仲裁机构申请仲裁，也可以直接向人民法院起诉”。故正确答案为D。", "tag": "法律常识"}
);
